\label{thm:introtails}
	Let $r^{-1}\psi$ be a solution to \eqref{eq:CSFintro} with $\mathfrak{q}\neq 0$ with respect to the conformally smooth electromagnetic gauge $A=-\frac{Q}{r}d\tau$, with $\tau$ a time function whose level sets are horizon-intersecting and asymptotically hyperboloidal spacelike hypersurfaces and with $\partial_{\tau}$ a Killing vector field normalized at infinity that is timelike away from the event horizon.  Assume that $\psi$ arises from the evolution of smooth, compactly supported initial data. Then, for $1-\frac{|Q|}{M}\ll 1$ or $|\mathfrak{q}Q|\ll 1$:
	\begin{align*}
		\psi(\tau,r,\theta,\varphi)\sim \sum_{\substack{\ell\in \mathbb{N}_0\\\ell(\ell+1)<\mathfrak{q}^2Q^2}}\sum_{\substack{m\in \mathbb{Z}\\ |m|\leq \ell}}\left[\Psi_{\ell m}^{\infty}(\tau,r;\mathfrak{q}, \mathfrak{I}_{\ell m}[\psi])+\Psi^+_{\ell m}(\tau,r;\mathfrak{q},\mathfrak{H}_{\ell m}[\psi])\right]Y_{\ell m}(\theta,\varphi)\quad (\tau\to \infty),
	\end{align*}
	where $\Psi^{+}_{\ell m}(\tau,r;\mathfrak{q},\mathfrak{H}_{\ell m}[\psi])=e^{-i\mathfrak{q}Qr_+^{-1}\tau}\Psi_{\ell m}^{\infty}\left(\tau,r_++\frac{r_+^2}{r-r_+};-\mathfrak{q},\mathfrak{H}_{\ell m}[\psi]\right)$, with $r_+$ the event horizon area radius, and where $\Psi_{\ell m}^{\infty}$ are globally-defined functions satisfying the following late-time asymptotics with $r_0\geq r_+$:
	\begin{align}
	\label{eq:introasympPsiinfty1}
	\Psi^{\infty}_{\ell m}(\tau,\infty;\mathfrak{q},\mathfrak{I}_{\ell m}[\psi])\sim &\: \mathfrak{I}_{\ell m}[\psi]\tau^{-\frac{1}{2}-\frac{1}{2}\beta_{\ell}+i\mathfrak{q}Q},\quad & (\beta_{\ell}\in (0,1)),\\
		\label{eq:introasympPsiinfty2}
		\Psi^{\infty}_{\ell m}(\tau,\infty;\mathfrak{q},\mathfrak{I}_{\ell m}[\psi])\sim &\: \mathfrak{I}_{\ell m}[\psi]\frac{\tau^{-\frac{1}{2}+i\mathfrak{q}Q}}{\log \tau},\quad & (\beta_{\ell}=0),\\
			\label{eq:introasympPsiinfty3}
		\Psi^{\infty}_{\ell m}(\tau,\infty;\mathfrak{q},\mathfrak{I}_{\ell m}[\psi])\sim &\: \mathfrak{I}_{\ell m}[\psi]\tau^{-\frac{1}{2}-\sigma\frac{\beta_{\ell}}{2}+i\mathfrak{q}Q}\sum_{n=0}^{\infty}\frac{\zeta^{\sigma n}\tau^{-\sigma n\beta_{\ell}}}{\Gamma\left(\frac{1}{2}+i\mathfrak{q}Q-(n+\frac{1}{2})\sigma\beta_{\ell}\right)},\quad & (\beta_{\ell}\in i(0,\infty)),\\
			\label{eq:introasympPsiinfty4}
		\Psi^{\infty}_{\ell m}(\tau,r_0;\mathfrak{q},\mathfrak{I}_{\ell m}[\psi])\sim &\:\mathfrak{I}_{\ell m}[\psi]\mathfrak{w}_{\ell}(r_0;\mathfrak{q}Q)\tau^{-1-\beta_{\ell}}, \quad & (\beta_{\ell}\in (0,1)),\\
			\label{eq:introasympPsiinfty5}
		\Psi^{\infty}_{\ell m}(\tau,r_0;\mathfrak{q},\mathfrak{I}_{\ell m}[\psi])\sim &\:\mathfrak{I}_{\ell m}[\psi]\mathfrak{w}_{\ell}(r_0;\mathfrak{q}Q)\frac{\tau^{-1}}{\log^2\tau},\quad & (\beta_{\ell}=0),\\
		\label{eq:introasympPsiinfty6}
			\Psi^{\infty}_{\ell m}(\tau,r_0;\mathfrak{q},\mathfrak{I}_{\ell m}[\psi])\sim &\:\mathfrak{I}_{\ell m}[\psi]\mathfrak{w}_{\ell}(r_0;\mathfrak{q}Q)\tau^{-1-\sigma\beta_{\ell}}\\ \nonumber
			\times &\sum_{n=0}^{\infty}\zeta^{\sigma n}\frac{\tau^{-\sigma n\beta_{\ell}}}{\Gamma(\sigma \beta_{\ell}+1) \Gamma(\frac{1}{2}-\frac{1}{2}\sigma \beta_{\ell}+i\mathfrak{q}Q)\Gamma(-(n+1)\sigma\beta_{\ell})}, & (\beta_{\ell}\in i(0,\infty)).
	\end{align}
	Here,
	\begin{itemize}
	\item $\beta_{\ell}:=\sqrt{(2\ell+1)^2-4\mathfrak{q}^2Q^2}\in [0,1)\cup i(0,\infty)$,
	\item $\sigma=\,\textnormal{sign}\,(\mathfrak{q}Q)$, $\zeta=\zeta(\mathfrak{q}Q,\beta_{\ell})$ is a complex constant (defined in Theorem \ref{thm:mainthmpoint}) and $\Gamma(\cdot)$ is the gamma function,
	\item $\mathfrak{I}_{\ell m}[\psi]$ and $\mathfrak{h}_{\ell m}[\psi]$ are linear functionals of (derivatives of) initial data at $\tau=0$, so that each $\mathfrak{I}_{\ell m}[\psi]$ vanishes only for a codimension-$1$ set of initial data, $\mathfrak{H}_{\ell m}[\psi]\equiv 0$ when $|Q|<M$ and in the case $|Q|=M$, each $\mathfrak{H}_{\ell m}[\psi]$ also vanishes only for a codimension-$1$ set of initial data,
	\item $\mathfrak{w}_{\ell}Y_{\ell m}$ are time-independent solutions to \eqref{eq:CSFintro} that are smooth at $r=r_+$ and satisfy $\mathfrak{w}_{\ell}(r_+;\mathfrak{q}Q)=1$. 
		\end{itemize}
		In the case that $1-\frac{|Q|}{M}\gtrsim 1$ and $|\mathfrak{q}Q|\gtrsim 1$, the above results remain valid under the condition of the validity of mode stability on the real axis.

\label{thm:introinst}
	Under the assumptions of Theorem \ref{thm:introtails}, the following asymptotic instability and non-decay results hold: 
	\begin{enumerate}[label=\emph{(\roman*)}]
	\item For all $k\in \mathbb{N}_0$, there exist constants $\mathfrak{c}_k>0$, such that for all $\ell\in \mathbb{N}_0$ with $\ell(\ell+1)<\mathfrak{q}^2Q^2$ and $m\in \mathbb{Z}$ with $|m|\leq \ell$:
\begin{align}
\label{eq:introlowboundbetanonzeroRNhor}	
		\limsup_{\tau\to \infty}(1+\tau)^{-k-\frac{1}{2}+\frac{\textnormal{Re}\, \beta_{\ell}}{2}}|D_X^{k+1}\psi_{\ell m}|(\tau,r_+)\geq &\:|\mathfrak{c}_k| |\mathfrak{H}_{\ell m}[\psi]| \quad &(|Q|=M,\:\beta_{\ell}\neq 0),\\
		\label{eq:introlowboundzerobetaRNhor}	
		\limsup_{\tau\to \infty}\log(1+\tau)(1+\tau)^{-k-\frac{1}{2}}|D_X^{k+1}\psi_{\ell m}|(\tau,r_+)\geq &\:|\mathfrak{c}_k| |\mathfrak{H}_{\ell m}[\psi]|\quad &(|Q|=M,\:\beta_{\ell}=0),\\
		\label{eq:introlowboundbetanonzeroRNinf}	
		\limsup_{\tau\to \infty}(1+\tau)^{-k-\frac{1}{2}+\frac{\textnormal{Re}\, \beta_{\ell}}{2}}|(r^2D_X)^{k+1}\psi_{\ell m}|(\tau,\infty)\geq &\:|\mathfrak{c}_k| |\mathfrak{I}_{\ell m}[\psi]| \quad &(\beta_{\ell}\neq 0),\\
		\label{eq:introlowboundzerobetaRNinf}	
		\limsup_{\tau\to \infty}\log(1+\tau)(1+\tau)^{-k-\frac{1}{2}}|(r^2D_X)^{k+1}\psi_{\ell m}|(\tau,\infty)\geq &\:|\mathfrak{c}_k| |\mathfrak{I}_{\ell m}[\psi]|\quad &(\beta_{\ell}=0),
		\end{align}
with $X$ a radial vector field tangential to $\Sigma_{\tau}$, the level sets of $\tau$. 
\item When $|\mathfrak{q}Q|>\frac{1}{2}$ ($\beta_0\in i(0,\infty)$), \emph{energy concentration} occurs near $\mathcal{H}^+$ in the case $|Q|=M$ and, with additional $r$-weights, also near $\mathcal{I}^+$ when $|Q|\leq M$, in the following sense: there exists a constant $\mathfrak{c}_{\rm int}>0$, such that for all $r_+\leq r_H<r_I<\infty$:
\begin{align}
\label{eq:introenblowup1}
	\limsup_{\tau\to \infty}\int_{\Sigma_{\tau}\cap\{r\leq r_H\}} \mathbb{T}^{SF}[g_{M,Q},r^{-1}\psi](\mathbf{n}_{\tau},\mathbf{n}_{\tau})\,d\mu_{\Sigma_{\tau}}\geq &\: \mathfrak{c}_{\rm int}\sum_{\substack{\ell\in \mathbb{N}_0\\ \ell+\frac{1}{2}<|\mathfrak{q}Q|}}\sum_{\substack{m\in \mathbb{Z}\\ |m|\leq \ell}}|\mathfrak{H}_{\ell m}[\psi]|^2,\\
	\label{eq:introendecy1}
	\lim_{\tau\to \infty}\int_{\Sigma_{\tau}\cap\{r> r_H\}} \mathbb{T}^{SF}[g_{M,Q},r^{-1}\psi](\mathbf{n}_{\tau},\mathbf{n}_{\tau})\,d\mu_{\Sigma_{\tau}}= &\: 0,\\
	\label{eq:introenblowup2}
\limsup_{\tau\to \infty}\int_{\Sigma_{\tau}\cap \{r\geq r_I\}} r^2|D_{r}\psi|^2\,\sin\theta d\theta d\varphi dr\geq &\: \mathfrak{c}_{\rm int}\sum_{\substack{\ell\in \mathbb{N}_0\\ \ell+\frac{1}{2}<|\mathfrak{q}Q|}}\sum_{\substack{m\in \mathbb{Z}\\ |m|\leq \ell}}|\mathfrak{I}_{\ell m}[\psi]|^2,
\end{align}
with induced volume form $d\mu_{\tau}$ on $\Sigma_{\tau}$ and $\mathbf{n}_{\tau}$ the corresponding future-directed normal. 
\end{enumerate}
In the case that $1-\frac{|Q|}{M}\gtrsim 1$ and $|\mathfrak{q}Q|\gtrsim 1$, the above results remain valid under the condition of the validity of mode stability on the real axis.

\label{lm:metricest}
Applying standard ``Big-O notation'' (see for example \cite{gaj26a}[\S 2.2]), we can estimate: 
	\begin{align*}
	r^{-2}\Omega^2(r(\rho_+))=&\:2\kappa_+ \rho_++(1-6\kappa_+ r_+)\rho_+^2+(-2r_++6\kappa_+ r_+^2)\rho_+^3+r_+^2\left(1-2\kappa_+ r_+\right)\rho_+^4,\\
	r^{-2}\Omega^2(r(\rho_{\infty}))=&\:\rho_{\infty}^2-2(r_+-\kappa_+ r_+^2)\rho_{\infty}^3+r_+^2\left(1-2\kappa_+ r_+\right)\rho_{\infty}^4.
		\end{align*}

\label{prop:mainequations}
Let $\psi$ be a solution to \eqref{eq:rCSF} with $A=\widehat{A}$. Then:
\begin{multline}
\label{eq:maineqradfield}
rG_{\widehat{A}}=X(\Omega^2X\psi)+r^{-2}\slashed{\Delta}_{\mathbb{S}^2}\psi-\mathbbm{h} \widetilde{\mathbbm{h}} T^2\psi-2(1-\mathbbm{h})(T+iq r^{-1})X\psi\\
+\left(\frac{d\mathbbm{h}}{dr}-2i q r^{-1} \mathbbm{h}\widetilde{\mathbbm{h}}\right)T\psi-\left[\frac{d\Omega^2}{dr} r^{-1}-i q r^{-1}\frac{d\mathbbm{h}}{dr}-q^2  \mathbbm{h}\widetilde{\mathbbm{h}}r^{-2}-i q r^{-2}(1-\mathbbm{h})\right]\psi.
\end{multline}
With respect to the coordinate chart $(\tau,\rho_{\infty},\theta,\varphi)$ we moreover obtain:
\begin{multline}
\label{eq:maineqradfieldconf}
r^2(rG_{\widehat{A}})=\partial_{\rho_{\infty}}(\Omega^2r^{-2}\partial_{\rho_{\infty}}\psi)+\slashed{\Delta}_{\mathbb{S}^2}\psi-\rho_{\infty}^{-2}\mathbbm{h} \widetilde{\mathbbm{h}} T^2\psi+2(1-\mathbbm{h})\partial_{\rho_{\infty}}T\psi+2iq(1-\mathbbm{h})\rho_{\infty} \partial_{\rho_{\infty}}\psi\\
+\left(-\frac{d\mathbbm{h}}{d\rho_{\infty}}-2i q \rho_{\infty}^{-1}\mathbbm{h}\widetilde{\mathbbm{h}}\right)T\psi-\left[r\frac{d\Omega^2}{dr} +iq \rho_{\infty}\frac{d\mathbbm{h}}{d\rho_{\infty}}-q^2 \mathbbm{h}\widetilde{\mathbbm{h}}-i q (1-\mathbbm{h})\right]\psi
\end{multline}
and with respect to the coordinate chart $(\tau,\rho_+,\theta,\varphi)$, we obtain:
\begin{multline}
\label{eq:maineqradfieldconfhor}
r^2(rG_{\widehat{A}})=\partial_{\rho_+}(\Omega^2r^{-2}\partial_{\rho_+}\psi)+\slashed{\Delta}_{\mathbb{S}^2}\psi-r^2\mathbbm{h} \widetilde{\mathbbm{h}} K^2\psi-2(1-\mathbbm{h})\partial_{\rho_+}K\psi+ 2iq (1-\mathbbm{h})\rho_+ \partial_{\rho_+}\psi\\
+\left(r^2\frac{d\mathbbm{h}}{dr}+2i q \rho_+ r^2\mathbbm{h}\widetilde{\mathbbm{h}}\right)K\psi-\left[r\frac{d\Omega^2}{dr} +iq  \rho_+r^2 \frac{d\mathbbm{h}}{dr}-q^2 \rho_+^2r^2\mathbbm{h}\widetilde{\mathbbm{h}}-i q (1-\mathbbm{h})\right]\psi.
\end{multline}
In particular, when $\kappa_+=0$, then
\begin{multline}
\label{eq:maineqradfieldhor}
r^2(rG_{\widehat{A}})=\partial_{\rho_{\infty}}(\Omega^2r^{-2}\partial_{\rho_{\infty}}\psi)+\slashed{\Delta}_{\mathbb{S}^2}\psi-\rho_{\infty}^{-2}\mathbbm{h} \widetilde{\mathbbm{h}} T^2\psi+2(1-\mathbbm{h})\partial_{\rho_{\infty}}T\psi+2iq(1-\mathbbm{h})\rho_{\infty} \partial_{\rho_{\infty}}\psi\\
+\left(-\frac{d\mathbbm{h}}{d\rho_{\infty}}-2i q \rho_{\infty}^{-1} \mathbbm{h}\widetilde{\mathbbm{h}}\right)T\psi-\left[2\rho_+\rho_{\infty} +iq \rho_{\infty}\frac{d\mathbbm{h}}{d\rho_{\infty}}-q^2  \mathbbm{h}\widetilde{\mathbbm{h}}-i q (1-\mathbbm{h})\right]\psi\\
=\partial_{\rho_+}(\Omega^2r^{-2}\partial_{\rho_+}\psi)+\slashed{\Delta}_{\mathbb{S}^2}\psi-\rho_+^{-2}\mathbbm{h}^+ \widetilde{\mathbbm{h}}^+ K^2\psi+2(1-\mathbbm{h}^+)\partial_{\rho_+}K\psi+2i(-q)(1-\mathbbm{h}_+)\rho_+ \partial_{\rho_+}\psi\\
+\left(-\frac{d\mathbbm{h}^+}{d\rho_+}-2i (-q) \rho_+^{-1}\mathbbm{h}^+\widetilde{\mathbbm{h}}^+\right)K\psi-\left[2\rho_{\infty}\rho_+  +i(-q) \rho_+ \frac{d\mathbbm{h}^+}{d\rho_+}-(-q)^2  \mathbbm{h}^+\widetilde{\mathbbm{h}}^+-i (-q) (1-\mathbbm{h}^+)\right]\psi.
\end{multline}
Note the symmetry between \eqref{eq:maineqradfieldhor} and \eqref{eq:maineqradfieldconf}: we can obtain the expressions on the very RHS of \eqref{eq:maineqradfieldhor} from the expressions to the right of the first equality in \eqref{eq:maineqradfieldconf} by interchanging $\rho_+$ and $\rho_{\infty}$, replacing $q$ with $-q$, $T$ with $K$, $\mathbbm{h}$ with $\mathbbm{h}_+$ and $\widetilde{\mathbbm{h}}$ with $\widetilde{\mathbbm{h}}_+$.

\mbox{}
\begin{enumerate}[label=\emph{(\roman*)}]
\item\emph{(Poincar\'e inequality on $\mathbb{S}^2$)} Let $f\in H^1(\mathbb{S}^2)$, then:
\begin{equation}
\label{eq:poincares2}
||f_{\geq \ell}||_{L^2(\mathbb{S}^2)}\leq \frac{1}{\sqrt{\ell(\ell+1)}}||f||_{H^1(\mathbb{S}^2)}.
\end{equation}
\item\emph{(Sobolev inequality on $\mathbb{S}^2$)} Let $f\in H^2(\mathbb{S}^2)$. Then there exists a numerical constant $C>0$, such that:
\begin{equation}
\label{eq:poincares2}
||f||_{L^{\infty}(\mathbb{S}^2)}\leq C ||f||_{H^2(\mathbb{S}^2)}\leq C\sum_{\ell\in \mathbb{N}_0}(\ell+1)^2||f_{\ell}||_{L^2(\mathbb{S}^2)}.
\end{equation}
\end{enumerate}
\begin{proof}
A straightforward consequence of the expansion $f=\sum_{\ell\in \mathbb{N}_0}f_{\ell}$.
\end{proof}

(Existence and uniqueness for the charged scalar field equation; \cite{gaj26a}[Theorem 2.5])
\label{thm:gwp}

Let $A\in \Omega^1(\mathcal{M}_{M,Q})$ and $G_A \in C^{\infty}(\mathcal{M}_{M,Q})$. Consider the initial data pair:
\begin{equation*}
(\upphi,T\upphi)\in C_c^{\infty}(\Sigma_0)\times C_c^{\infty}(\Sigma_0).
\end{equation*}
Then there exists a unique solution $\phi\in C^{\infty}(\mathcal{M}_{M,Q})$ to \eqref{eq:CSF} with respect to $A$, such that $(\phi|_{\Sigma_0}, T\phi|_{\Sigma_0})=(\upphi,T\upphi)$.

If we take $A\in \Omega^1(\widehat{\mathcal{M}}_{M,Q})$ and $G_A\in C^{\infty}(\widehat{\mathcal{M}}_{M,Q})$, then $\psi=r\phi\in C^{\infty}(\widehat{\mathcal{M}_{M,Q}})$.

\label{thm:iedpaper1}
Let $\psi$ be a solution to \eqref{eq:rCSF}.  Let $\epsilon,\delta,\eta ,\kappa_0>0$, $N,\ell\in \mathbb{N}_0$ and $r_+<r_H<r_I<\infty$. Consider $1< p<\min\{1+\textnormal{Re}\, \beta_{\ell},2\}+\epsilon$ and let $\upzeta$ be a smooth function satisfying $\upzeta(r)=1$ for $r\notin (r_{\sharp}-2\eta,r_{\sharp}+2\eta)$ and $\upzeta(r)=0$ for $r\in (r_{\sharp}-\eta,r_{\sharp}+\eta)$. 

Assume that $0\leq \kappa_+\leq \kappa_1$ or $|q|\leq q_1$. Then, for suitably small $\kappa_1$ or $q_1$, there exist a constant\\ $C=C(q_1,\epsilon,\delta,\eta, \kappa_1, p, r_H,r_I,\mathbbm{h},N)>0$, such that for any $\tau_1\leq \tau_2$:
\begin{multline}
\label{eq:iedpaper1}
\sup_{\tau\in [\tau_1,\tau_2]}\sum_{k\leq N}\int_{\Sigma_{\tau}} \mathcal{E}_{p-2\epsilon}[D_T^k\psi_{\geq \ell}]\,d\sigma dr+\sum_{k_1+k_2+k_3=k}\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}\cap\{r_H\leq r\leq r_I\}} |D_{\mathbb{S}^2}^{k_1}D_{Y_*}^{k_2+1}D_T^{k_3}\psi_{\geq \ell}|^2+|D_{\mathbb{S}^2}^{k_1}D_{Y_*}^{k_2}D_T^{k_3}\psi_{\geq \ell}|^2\\
+\upzeta(r)(|D_{\mathbb{S}^2}^{k_1}D_{Y_*}^{k_2}D_T^{k_3+1}\psi_{\geq \ell}|^2+|D_{\mathbb{S}^2}^{k_1+1}D_{Y_*}^{k_2}D_T^{k_3}\psi_{\geq \ell}|^2)\,d\sigma dr d\tau\\
+\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}\setminus\{r_H\leq r\leq r_I\}} (\rho_++\kappa_+)r^{-1}(r^{-1}\rho_+)^{2\epsilon}\mathcal{E}_{p}[D_T^k\psi_{\geq \ell}]+(\rho_++\kappa_+)r^{-3}(r^{-1}\Omega)^{\delta-2}|D_T^{k+1}\psi_{\geq \ell}|^2\,d\sigma drd\tau\\
\leq C\sum_{k\leq N}\int_{\Sigma_{\tau_1}} \mathcal{E}_{p}[D_T^k\psi_{\geq \ell}]\,d\sigma dr\\
+\int_{\tau_1}^{\tau_2+r_+}\int_{\Sigma_{\tau}} \max\{(r^{-1}\Omega)^{-p}\rho_+^{1-2\epsilon}r^{-1+2\epsilon},1\}r^{-2}|r^3D_T^k(G_{A})_{\geq \ell}|^2+(1-\upzeta)|D_T^{k+1}(G_A)_{\geq \ell}|^2\,d\sigma dr \,d\tau.
\end{multline}
The estimate \eqref{eq:iedpaper1} remains valid when $\kappa_+>\kappa_1$ and $|q|\geq q_1$ under the assumption of Condition \ref{cond:quantmodestabp2} below.

\label{cond:quantmodestabp2}
Let $\omega_1$ and $\ell_1\in \mathbb{N}_0$ be arbitrary. Let $(\omega,\ell)\in \mathbb{R} \times \mathbb{N}_0$, with $|\omega|\leq \omega_1$ and $\ell\leq \ell_1$. Let $\kappa_+> \kappa_1$, with $\kappa_1$ the constant from Theorem \ref{thm:iedpaper1}.

Consider the ODE:
\begin{equation}
\label{eq:radialODE}
u''(r_*)+(\omega^2-V_{\omega  \ell}(r_*))u(r_*)=0,
\end{equation}
with
\begin{equation*}
	V_{\omega  \ell}(r_*(r))=\ell(\ell+1)\Omega^2(r)r^{-2}-{q}^2\rho_{\infty}^2(r)+2{q} \omega \rho_{\infty}(r)+r^{-1}\Omega^2(r)\frac{d\Omega^2 }{dr}
\end{equation*}
Let $u_+,u_{\infty}$ be solutions to \eqref{eq:radialODE} that are normalized as follows:
\begin{equation*}
\lim_{r_*\to -\infty}e^{i(\omega-q r_+^{-1}) r_*+i q \int_{0}^{r_*}\rho_+(r_*')\,dr_*'}u_+(r_*)=\lim_{r_*\to \infty}e^{-i\omega r_*+i q \int_{0}^{r_*}\rho_{\infty}(r_*')\,dr_*'}u_{\infty}(r_*)=1.
\end{equation*}
and consider their corresponding Wronskian:
\begin{equation*}
\mathfrak{W}(\omega,\ell):=u_{+}(r_*)\frac{du_{\infty}}{dr_*}(r_*)-u_{\infty}(r_*)\frac{du_{+}}{dr_*}(r_*).
\end{equation*}

 Then there exists a constant $K=K(\omega_1,\ell_1,\kappa_1)>0$ such that:
\begin{equation*}
|\mathfrak{W}|^{-1}\leq  K.
\end{equation*}

\label{prop:statsol}
	Let $\ell\in \mathbb{N}_0$, $m\in \mathbb{Z}$ with $|m|\leq \ell$. Fix $r_+=1$. Let $\mathfrak{w}_{\ell }, \mathfrak{w}^{\pm}_{\ell }: [r_+,\infty)\to \mathbb{C}$, such that $\mathfrak{w}_{\ell }Y_{\ell m}$ and $\mathfrak{w}^{\pm}_{\ell }Y_{\ell m}$ are solutions to \eqref{eq:rCSF} with $A=\widehat{A}$ and $G_A=0$. We write $\mathfrak{w}^{\pm}(r;q)$ and  $\mathfrak{w}(r;q)$ when we need to emphasize the value of the corresponding charge parameter $q$.

	Then:
	\begin{enumerate}[label=\emph{(\roman*)}]
	\item We can fix $\mathfrak{w}_{\ell }, \mathfrak{w}^{\pm}_{\ell }$ uniquely by setting:
	\begin{align*}
		\mathfrak{w}_{\ell }(r_+)=&\:1,\\
		\mathfrak{w}^{-}_{\ell }(r)=&\:r^{\frac{1}{2}+iq- \frac{1}{2}\beta_{\ell}}(1+O(r^{-1}))\quad (r>2),\\
		\mathfrak{w}^{+}_{\ell }(r)=&\:r^{\frac{1}{2}+iq+ \frac{1}{2}\beta_{\ell}}(1+O(r^{-1}))\quad (\beta_{\ell}\neq 0)\quad (r>2),\\
		\mathfrak{w}^{+}_{\ell }(r)=&\:r^{\frac{1}{2}+iq}\log r(1+O(r^{-1}))\quad (\beta_{\ell}= 0)\quad (r>2).
	\end{align*}
	\item We can express:
	\begin{equation*}
		\mathfrak{w}_{\ell }={\alpha}_+\mathfrak{w}_{\ell }^++{\alpha}_-\mathfrak{w}_{\ell }^-,
	\end{equation*}
	with ${\alpha}_{\pm}\in \mathbb{C}$, such that in the case $\beta_{\ell}\in i(0,\infty)$:
		\begin{multline}
		\label{eq:alphaminplusratiobetaim}
		\,\textnormal{sign}\,(q)\log\left|\frac{ \alpha_-}{\alpha_+}\right|=-\frac{\pi}{2}\left(\textnormal{Im}\, \beta_{\ell}-\frac{1}{\pi}\log \left(\frac{\cosh (\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh (\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)\right)\\
		+\,\textnormal{sign}\,(q)\frac{\pi}{2}\left( \textnormal{Im}\, \beta_{\ell}-\frac{1}{\pi}\log \left(\frac{\cosh(\pi(\frac{|q|}{2}\frac{r_-+r_+}{r_+^2\kappa_+}+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))\cosh^2(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(\frac{|q|}{2}\frac{r_-+r_+}{r_+^2\kappa_+}-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))\cosh^2(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)\right)\\
		\substack{\kappa_+\downarrow 0\\ \to}-\frac{\pi}{2}\left(\textnormal{Im}\, \beta_{\ell}+\frac{1}{\pi}\log \left(\frac{\cosh (\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh (\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)\right).
	\end{multline}
	\item Denote with $\alpha_{\pm}(\beta_{\ell})$ the values of $\alpha_{\pm}$ when $\beta_{\ell}\neq 0$ and $q$ is fixed. Then $\alpha_-(\beta_{\ell})=\alpha_+(-\beta_{\ell})$ and we have that:
\begin{equation*}
	\lim_{\beta_{\ell}\to 0}\mathfrak{w}_{\ell}(r)=\lim_{\beta_{\ell}\to 0}(\alpha_+\beta_{\ell})r^{\frac{1}{2}+iq}\left[\log r+\frac{d}{d\beta_{\ell}}\bigg|_{\beta_{\ell}=0}\frac{\alpha_{-}(\beta_{\ell})}{\alpha_{+}(\beta_{\ell})}\right].
\end{equation*}
Therefore $\alpha_{\pm}$ take the following values when $\beta_{\ell}=0$:
\begin{align*}
	\alpha_{+}=&\:-\lim_{\beta_{\ell}\to 0}(\alpha_+(\beta_{\ell})\beta_{\ell}),\\
	\alpha_{-}=&\:\alpha_+ \frac{1}{i}\frac{d}{ds}\bigg|_{s=0}\frac{\alpha_{-}(is)}{\alpha_{+}(is)}.
\end{align*}
In particular,
\begin{multline}
\label{eq:alphaminplusratiobetazero}
	\,\textnormal{sign}\,(q)\textnormal{Im}\, \left(\frac{\alpha_-}{\alpha_+}\right)=-\,\textnormal{sign}\,(q)\textnormal{Re}\,\left(\frac{d}{ds}\Big|_{s=0} \left(\frac{\alpha_-(is)}{\alpha_+(is)}\right)\right)=-\,\textnormal{sign}\,(q)\frac{ \pi}{2}(1-\tanh(\pi|q|))\\
	+\frac{\pi}{2}\,\textnormal{sign}\,(q)\left(1 -\tanh\left(\pi \frac{|q|}{2}\frac{r_-+r_+}{r_+^2 \kappa_+}\right)-2\tanh(\pi |q|)\right)\\
	\substack{\kappa_+\downarrow 0\\ \to} -\,\textnormal{sign}\,(q)\frac{ \pi}{2}(1+\tanh(\pi|q|).
\end{multline}
	\item The function $\mathfrak{w}_{\ell }$ is non-vanishing.
	\end{enumerate}

Let
\begin{align*}
	w_{\ell }:=&\:e^{-iq\int_{r^{\sharp}}^{r}r'^{-1}\,dr'+iq\int_{r^{\sharp}}^{r}r'^{-1}\Omega^{-2}(r')(\Omega^2-1+\mathbbm{h})(r')\,dr'}\mathfrak{w}_{\ell },\\
	w_{\ell }^{\pm}:=&\:e^{-iq\int_{r^{\sharp}}^{r}r'^{-1}\,dr'+iq\int_{r^{\sharp}}^{r}r'^{-1}\Omega^{-2}(r')(\Omega^2-1+\mathbbm{h})(r')\,dr'}\mathfrak{w}_{\ell }^{\pm}.
	\end{align*}
	Then $w_{\ell }Y_{\ell m}$ and $w_{\ell m}^{\pm}Y_{\ell m}$ are solutions to \eqref{eq:CSF} with $A=\widetilde{A}$ and $G_A=0$. In other words, they are solutions to \eqref{eq:maineqradfield} with $\widetilde{\mathbbm{h}}=\Omega^{-2}$.


Note that we can equivalently express:
\begin{align*}
	w_{\ell }:=&\:e^{iq r_+^{-1}r_*-iq\int_{r^{\sharp}}^{r}(\Omega^{-2} \rho_+)(r')\,dr'-iq\int_{r_{\sharp}}^{r}r'^{-1}\widetilde{\mathbbm{h}}(r')\,dr'}\mathfrak{w}_{\ell },\\
	w_{\ell }^{\pm}:=&\:e^{iq r_+^{-1}r_*-iq\int_{r^{\sharp}}^{r}(\Omega^{-2} \rho_+)(r')\,dr'-iq\int_{r_{\sharp}}^{r}r'^{-1}\widetilde{\mathbbm{h}}(r')\,dr'}\mathfrak{w}_{\ell }^{\pm}.
	\end{align*}

	 Then \eqref{eq:maineqradfield} with $\widetilde{\mathbbm{h}}=\Omega^{-2}$ is equivalent to:
	\begin{equation}
	\label{eq:relevanteqforstatsoln}
		\frac{d}{dr}\left(\Omega^2 r^2 \frac{d}{dr}(r^{-1}w_{\ell})\right)+\left[q^2 r^2(r^{2}\Omega)^{-2}-\ell(\ell+1)\right]r^{-1}w_{\ell}=0.
	\end{equation}
	Assume for convenience that $r_+=1$. 

	We first consider the case $\kappa_+=0$. By changing variables to $z=\frac{2iq}{r-1}$, we obtain the equation:
	\begin{equation*}
		\frac{d^2(r^{-1}w_{\ell})}{dz^2}+\left[-\frac{1}{4}-\frac{iq}{z}+\frac{q^2-\ell(\ell+1)}{z^2}\right]r^{-1}w_{\ell}=0.
	\end{equation*}
	This is the \emph{Whittaker equation}; see for example \cite{NIST:DLMF}[\S 13.4]. Using the asymptotic properties of Whittaker functions as $|z|\to \infty$, it follows that: we can express:
	\begin{equation*}
		r^{-1}w_{\ell}(r)=c_{q}\cdot W_{-iq,\frac{\beta_{\ell}}{2}}(2iq(r-1)^{-1}),
	\end{equation*}	
	for some constant $c_{q}\in \mathbb{C}\setminus\{0\}$. The Whittaker function $W_{-iq,\frac{\beta_{\ell}}{2}}(2iq(r-1)^{-1})$ has the following asymptotics as $z\to 0$ when $\beta_{\ell}\in i(0,\infty)$ (see \cite{NIST:DLMF}[\S 13.14]):
	\begin{multline*}
		c_{q}^{-1}w_{\ell}(r)=r W_{-iq,\frac{\beta_{\ell}}{2}}(2iq(r-1)^{-1})=\frac{\Gamma(\beta_{\ell})}{\Gamma(\frac{1}{2}+\beta_{\ell}+iq)}(2iq)^{\frac{1}{2}-\frac{\beta_{\ell}}{2}}r^{\frac{1}{2}+\frac{\beta_{\ell}}{2}}(1+O(r^{-1}))\\
		+(2iq)^{\frac{1}{2}+\frac{\beta_{\ell}}{2}}\frac{\Gamma(-\beta_{\ell})}{\Gamma(\frac{1}{2}-\beta_{\ell}+iq)}r^{\frac{1}{2}-\frac{\beta_{\ell}}{2}}(1+O(r^{-1}))\\
		=\frac{\Gamma(\beta_{\ell})}{\Gamma(\frac{1}{2}+\beta_{\ell}+iq)}(2iq)^{\frac{1}{2}}|2q|^{\frac{i}{2}\textnormal{Im}\, \beta_{\ell}}e^{-\frac{\pi}{4}\,\textnormal{sign}\,(q)\textnormal{Im}\, \beta_{\ell}}r^{\frac{1}{2}+\frac{\beta_{\ell}}{2}}(1+O(r^{-1}))\\
		+(2iq)^{\frac{1}{2}}|2q|^{-\frac{i}{2}\textnormal{Im}\, \beta_{\ell}}e^{\frac{\pi}{4}\,\textnormal{sign}\,(q)\textnormal{Im}\, \beta_{\ell}}\frac{\Gamma(-\beta_{\ell})}{\Gamma(\frac{1}{2}-\beta_{\ell}+iq)}r^{\frac{1}{2}-\frac{\beta_{\ell}}{2}}(1+O(r^{-1})).
	\end{multline*}
	We therefore conclude that
	\begin{equation*}
		\frac{\alpha_-}{\alpha_+}=|2q|^{-i\textnormal{Im}\, \beta_{\ell}}\frac{\Gamma(-\beta_{\ell})}{\Gamma(\beta_{\ell})}\frac{\Gamma(\frac{1}{2}+\beta_{\ell}+iq)}{\Gamma(\frac{1}{2}-\beta_{\ell}+iq)}e^{-\frac{\pi}{2}\,\textnormal{sign}\,(q).\textnormal{Im}\, \beta_{\ell}}
	\end{equation*}

	From this, it follows that:
		\begin{multline*}
		\log\left|\frac{ \alpha_-}{\alpha_+}\right|=-\frac{\pi}{2}\,\textnormal{sign}\,(q)\textnormal{Im}\, \beta_{\ell}+\frac{1}{2}\log \left|\frac{\Gamma(-\beta_{\ell})}{\Gamma(+\beta_{\ell})}\right|^2+\frac{1}{2}\log \left|\frac{\Gamma(\frac{1}{2}+\frac{1}{2}\beta_{\ell}+iq)}{\Gamma(\frac{1}{2}-\frac{1}{2}\beta_{\ell}+iq)}\right|^2\\
		=-\frac{\pi}{2}\,\textnormal{sign}\,(q)\textnormal{Im}\, \beta_{\ell}+\frac{1}{2}\,\textnormal{sign}\,(q)\log \left(\frac{\cosh(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right).
	\end{multline*}


	Now consider the case $\kappa_+>0$. Fix $r_+=1$. Write $2\kappa_+:=r_+-r_-$. Then we introduce the following change of variable and rescalings:
	\begin{align*}
		z=&\:\frac{r-r_+}{r-r_-},\\
		r^{-1}w_{\ell}(r(z))=&\:z^{i\frac{q}{2} \kappa_+^{-1}}(1-z)^{\frac{1}{2}-\beta_{\ell}}F(z).
	\end{align*}
to obtain from \eqref{eq:relevanteqforstatsoln} the following equation for $F$:
\begin{equation*}
	z(1-z)\frac{d^2F}{dz^2}+(c-(a+b+1)z)\frac{dF}{dz}-abF=0,
\end{equation*}
with $a=i\frac{q}{2}\kappa_+^{-1}(1-r_-)+\frac{1-\beta_{\ell}}{2}$, $b=i\frac{q}{2}\kappa_+^{-1}(1+r_-)+\frac{1-\beta_{\ell}}{2}$, $c=1+iq\kappa_+^{-1}$. The above ODE is a hypergeometric equation, see \cite{NIST:DLMF}[\S 15.10], and we can therefore write:
\begin{equation*}
	r^{-1}w_{\ell}(r)=c_{q,\kappa_+}\left(\frac{r-1}{r-r_-}\right)^{i\frac{q}{2} \kappa_+^{-1}}\left(\frac{1-r_-}{r-r_-}\right)^{\frac{1}{2}-\beta_{\ell}} {}_2\mathbf{F}_1\left(a,b,c\; \frac{r-1}{r-r_-}\right),
\end{equation*}
with ${}_2\mathbf{F}_1\left(a,b,c\; \frac{r-r_+}{r-r_-}\right)$ the regularized Gauss hypergeometric function. It is straightforward to verify that $\mathfrak{w}_{\ell}$ is smooth at $r=1$.

Furthermore, by applying \cite{NIST:DLMF}[\S 15.8.4] we obtain the following large-$r$ asymptotics ($z\uparrow 1$) :
\begin{multline*}
	\pi(\sin(\pi \beta_{\ell}))^{-1}c_{q,\kappa_+}^{-1}w_{\ell}(r)=\frac{r\left(\frac{r-r_-}{1-r_-}\right)^{-\frac{1}{2}+\frac{\beta_{\ell}}{2}}}{\Gamma(\frac{1}{2}+\frac{\beta_{\ell}}{2}+i\frac{q}{2}(1+r_-)\kappa_+^{-1})\Gamma(\frac{1}{2}+\frac{\beta_{\ell}}{2}+iq)\Gamma(1-\beta_{\ell})}(1+O(r^{-1}))\\
	-\frac{r\left(\frac{r-r_-}{1-r_-}\right)^{-\frac{1}{2}-\frac{\beta_{\ell}}{2}}}{\Gamma(\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq)\Gamma(\frac{1}{2}-\frac{\beta_{\ell}}{2}+i\frac{q}{2} (1+r_-)\kappa_+^{-1})\Gamma(1+\beta_{\ell})}(1+O(r^{-1})).
\end{multline*}
We therefore conclude that:
\begin{equation*}
	\frac{\alpha_-}{\alpha_+}=(1-r_-)^{\beta_{\ell}}\frac{\Gamma(1-\beta_{\ell})}{\Gamma(1+\beta_{\ell})}\frac{\Gamma(\frac{1}{2}+\frac{\beta_{\ell}}{2}+iq)}{\Gamma(\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq)}\frac{\Gamma(\frac{1}{2}+\frac{\beta_{\ell}}{2}+i\frac{q}{2}(1+r_-)\kappa_+^{-1})}{\Gamma(\frac{1}{2}-\frac{\beta_{\ell}}{2}+i\frac{q}{2}(1+r_-)\kappa_+^{-1})}
\end{equation*}
	From this, it follows that for $\beta_{\ell}\in i(0,\infty)$:
		\begin{multline*}
		\log\left|\frac{ \alpha_-}{\alpha_+}\right|=\frac{1}{2}\log \left|\frac{\Gamma(1-\beta_{\ell})}{\Gamma(1+\beta_{\ell})}\right|^2+\frac{1}{2}\log \left|\frac{\Gamma(\frac{1}{2}+\frac{1}{2}\beta_{\ell}+iq)}{\Gamma(\frac{1}{2}-\frac{1}{2}\beta_{\ell}+iq)}\right|^2+\frac{1}{2}\log \left|\frac{\Gamma(\frac{1}{2}+\frac{1}{2}\beta_{\ell}+i\frac{q}{2}(1+r_-)\kappa_+^{-1})}{\Gamma(\frac{1}{2}-\frac{1}{2}\beta_{\ell}+i\frac{q}{2}(1+r_-)\kappa_+^{-1})}\right|^2\\
		=\frac{1}{2}\,\textnormal{sign}\,(q)\log \left(\frac{\cosh(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)+\,\textnormal{sign}\,(q)\frac{1}{2}\log \left(\frac{\cosh(\pi(\frac{|q|}{2}\frac{r_-+1}{\kappa_+}-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(\frac{|q|}{2}\frac{r_-+1}{\kappa_+}+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)\\
		=-\frac{\pi}{2}\,\textnormal{sign}\,(q)\textnormal{Im}\, \beta_{\ell}-\frac{1}{2}\,\textnormal{sign}\,(q)\log \left(\frac{\cosh(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)\\
		+\frac{1}{2}\,\textnormal{sign}\,(q)\left(\pi \textnormal{Im}\, \beta_{\ell}-\log \left(\frac{\cosh(\pi(\frac{|q|}{2}\frac{r_-+1}{\kappa_+}+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))\cosh^2(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(\frac{|q|}{2}\frac{r_-+1}{\kappa_+}-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))\cosh^2(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)\right).
	\end{multline*}
	Note that the last term vanishes in the extremal limit $\kappa_+\to 1$.

Now consider (iii). We apply Taylor's theorem to obtain:
\begin{equation*}
	\frac{1}{2}\log \left(\frac{\cosh(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)=-\frac{\pi}{2} \tanh(\pi |q|)\textnormal{Im}\, \beta_{\ell}+O(|\beta|^2).
\end{equation*}
	Therefore,
	\begin{multline*}
		\textnormal{Re}\,\left(\frac{d}{ds}\Big|_{s=0} \left(\frac{\alpha_-(is)}{\alpha_+(is)}\right)\right)=-\textnormal{Re}\,\left(\frac{d}{ds}\Big|_{s=0}\log \left(\frac{\alpha_-(is)}{\alpha_+(is)}\right)\right)=-	\frac{d}{ds}\Big|_{s=0}\log \left|\frac{\alpha_-(is)}{\alpha_+(is)}\right|\\
		=+\frac{\pi}{2}\,\textnormal{sign}\,(q)-\pi \,\textnormal{sign}\,(q)\tanh(\pi |q|)+\frac{1}{2}\pi\,\textnormal{sign}\,(q)\left(1 -2\tanh\left(\pi \frac{|q|}{2}\frac{r_-+1}{\kappa_+}\right)-4\tanh(\pi |q|)\right).
	\end{multline*}

	We now rewrite for $s=\textnormal{Im}\, \beta_{\ell}$:
\begin{multline*}
	\mathfrak{w}_{\ell}(r)=\frac{1}{i}\alpha_+(is) s r^{\frac{1}{2}+iq}\left[\frac{1}{s}e^{\frac{is}{2}\log r}+\frac{1}{s}\frac{\alpha_-(is)}{\alpha_+(is)}e^{-i\frac{s}{2}\log r }\right]\\
	=\frac{1}{i}\alpha_+(is)s r^{\frac{1}{2}+iq}e^{i\frac{s}{2}\log r}\left[\frac{1}{s}(e^{+i\frac{s}{2}\log r }-1)-\frac{1}{s}(e^{-i\frac{s}{2}\log r }-1)+\frac{1}{s}\left(\frac{\alpha_-(is)}{\alpha_+(is)}-(-1)\right)e^{-i\frac{s}{2}\log r }\right]
\end{multline*}
	By (ii), we have that $\lim_{\beta_{\ell}\to 0}\beta_{\ell}\alpha_+(\beta_{\ell})=-\lim_{\beta_{\ell}\to 0}\beta_{\ell}\alpha_-(\beta_{\ell})$ is well-defined, so after taking the limit $s \downarrow 0$, we obtain:
	\begin{equation*}
	\lim_{s\to 0}\mathfrak{w}_{\ell}(r)=-\lim_{s\to 0}(\alpha_+(is)is)r^{\frac{1}{2}+iq}\left[\log r+\frac{1}{i}\frac{d}{ds}\bigg|_{s=0}\frac{\alpha_{-}(is)}{\alpha_{+}(is)}\right].
\end{equation*}
Since this limit must correspond to a stationary solution in the $\beta_{\ell}=0$ case, we conclude the identities for $\alpha_{\pm}$ when $\beta_{\ell}=0$.

	Finally, we turn to (iv). Write $w=w_{\ell }$. Then for $(\cdot)':=\frac{d}{dr_*}$, we have that $w''(r_*)=V_{\ell }(r(r_*))w(r_*)$, with
	\begin{equation*}
	V_{\ell}(r)=\ell(\ell+1)\Omega^2r^{-2}-{q}^2r^{-2}+\Omega^2r^{-1}\frac{d\Omega^2 }{dr}.
	\end{equation*}
	This follows by \cite{gaj26a}[Proposition 5.1]. Since $V_{\ell}$ is real-valued, we obtain $\textnormal{Re}\,(i\overline{w} w'')=0$, so:
	\begin{equation*}
	\frac{d}{dr_*}\textnormal{Re}\,\left(i\overline{w}w'\right)=0.
	\end{equation*}
	Then 
	\begin{equation*}
	\lim_{r_*\to- \infty}\textnormal{Re}\,\left(i\overline{w}w'\right)(r_*)=-q r_+^{-1}|w|(-\infty)=-q r_+^{-1}.
	\end{equation*} 
	Hence, $\textnormal{Re}\,\left(i\overline{w}w'\right)(r_*)=qr_+^{-1}\neq 0$ for all $r_*\in \mathbb{R}$, which implies that $\mathfrak{w}_{\ell}$ is non-vanishing.

\label{cor:kappanotsmallstatsoln}
When $\beta_{\ell}\in i[0,\infty)$, the following estimates hold for all $\kappa_+\geq 0$: there exists an $\eta_0>0$, such that:
\begin{align}
\label{eq:condimagbeta}
\,\textnormal{sign}\,(q) \log \left|\frac{\alpha_-}{\alpha_+}\right|\leq&-\frac{\pi}{2}\textnormal{Im}\, \beta_{\ell}-\eta_0 \textnormal{Im}\, \beta_{\ell}-\frac{1}{2}\log \left(\left|\frac{\cosh(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell})}{\cosh(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell})}\right|\right)\quad &(\beta_{\ell}\in i(0,\infty)),\\
\label{eq:condzerobeta}
	\,\textnormal{sign}\,(q) \textnormal{Im}\, \left(\frac{\alpha_-}{\alpha_+}\right)\leq &-\frac{\pi}{2}\left(1-\tanh(\pi |q|)\right)+\eta_0 \quad &(\beta_{\ell}=0).
\end{align}

Consider \eqref{eq:alphaminplusratiobetazero}. Using the monotonicity of $\tanh$ and the fact that $|q|\geq \frac{1}{2}$, we obtain the desired inequality by using that:
	\begin{equation*}
		1-3\tanh\left(\frac{\pi}{2}\right)=\frac{2(2-e^{\pi})}{e^{\pi}+1}<0,
	\end{equation*}
	using that $e^{\pi}>e^3>e^{\log 2}$.

	Now consider \eqref{eq:alphaminplusratiobetaim}. Write $\beta_{\ell}=is$. Note that:
	\begin{multline*}
	\textnormal{Im}\, \beta_{\ell}-\frac{1}{\pi}\log \left(\frac{\cosh(\pi(|q|\frac{r_-+1}{1-r_-}+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))\cosh^2(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(|q|\frac{r_-+1}{1-r_-}-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))\cosh^2(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right) \leq  \textnormal{Im}\, \beta_{\ell}-\frac{3}{\pi}\log\left(\frac{\cosh(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}{\cosh(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell}))}\right)\\
	\to 0 \quad \textnormal{Im}\, \beta_{\ell}\to 0.
