			\leq 1-3 \tanh(\pi |q|)\leq 1-3 \tanh(\frac{\pi}{2})<0,
		\end{multline*}
		where we used that $2|q|-|\textnormal{Im}\, \beta_{\ell}|>0$ when $\textnormal{Im}\, \beta_{\ell}\neq 0$ to arrive at the first inequality above.
		Hence,
		\begin{equation*}
			\left(\textnormal{Im}\, \beta_{\ell}-\frac{3}{\pi}\log\left(\frac{\cosh(\pi(|q|+\frac{1}{2} \beta_{\ell}))}{\cosh(\pi(|q|-\frac{1}{2} \beta_{\ell}))}\right)\right)<0. \qedhere
		\end{equation*}

