\begin{multline}
\label{eq:horpest}
\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau_2}} \mathcal{E}_{p-2\epsilon}[\mathbf{Z}^{\gamma}\psi_{\geq \ell}]\,d\sigma dr+\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}\cap \{r_H\leq r\leq r_I\}}  \upzeta \mathcal{E}_p[\mathbf{Z}^{\gamma}\psi_{\geq \ell}]+|\mathbf{Z}^{\gamma}\psi_{\geq \ell}|^2\,d\sigma dr d\tau\\
+\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}\setminus \{r_H\leq r\leq r_I\}} (\rho_++\kappa_+)r^{-1}(r^{-1}\rho_+)^{2\epsilon}\mathcal{E}_{p}[\mathbf{Z}^{\gamma}\psi_{\geq \ell}]+(\rho_++\kappa_+)r^{-3}(r^{-1}\Omega)^{\epsilon-2}|D_T\mathbf{Z}^{\gamma}\psi_{\geq \ell}|^2\,d\sigma dr d\tau\\
\leq C\sum_{|\gamma|\leq N}\sum_{n\leq N}\int_{\Sigma_{\tau_1}} \mathcal{E}_{p-2\epsilon}[\mathbf{Z}^{\gamma}\psi_{\geq \ell}]\,d\sigma dr+C\sum_{n_1+n_2=n}\int_{\Sigma_{\tau_1}} \mathcal{E}_{p}[\slashed{\nabla}_{\mathbb{S}^2}^{n_1}T^{n_2}\psi_{\geq \ell}]\,d\sigma dr\\
+C\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}}(r^{-1}\Omega)^{-p+2\epsilon}r^{-1}\rho_+r^{-2}|\mathbf{Z}^{\gamma}( r^3G_{\widehat{A}})_{\geq \ell} |^2\,d\sigma dr d\tau\\
+C\sum_{n_1+n_2=n}\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}} \max\{(r^{-1}\Omega)^{-p}\rho_+^{1-2\epsilon}r^{-1+2\epsilon},1\}r^{-2}|\slashed{\nabla}_{\mathbb{S}^2}^{n_1}T^{n_2}(r^3G_{\widehat{A}})_{\geq \ell}|^2+\Omega^2r^{-2}(1-\upzeta) |\slashed{\nabla}_{\mathbb{S}^2}^{n_1}T^{n_2+1}( r^3G_{\widehat{A}})_{\geq \ell} |^2\,d\sigma dr d\tau.
\end{multline}

Let $\gamma\in \mathbb{N}_0$ and $\epsilon>0$. Let $1< p<\min\{1+\textnormal{Re}\, \beta_{\ell},2\}+\epsilon$. Then
\begin{multline}
\label{eq:horpestrmin1pest}
\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau_2}} \mathcal{E}_{p-2\epsilon}[\mathbf{Z}^{\gamma}\psi_{\geq \ell}]\,d\sigma dr+\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}\cap \{r_H\leq r\leq r_I\}}  \upzeta \mathcal{E}_p[\mathbf{Z}^{\gamma}\psi_{\geq \ell}]+|\mathbf{Z}^{\gamma}\psi_{\geq \ell}|^2\,d\sigma dr d\tau\\
+\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}\setminus \{r_H\leq r\leq r_I\}} (\rho_++\kappa_+)r^{-1}(r^{-1}\rho_+)^{2\epsilon}\mathcal{E}_{p}[\mathbf{Z}^{\gamma}\psi_{\geq \ell}]+(\rho_++\kappa_+)r^{-3}(r^{-1}\Omega)^{\epsilon-2}|D_T\mathbf{Z}^{\gamma}\psi_{\geq \ell}|^2\,d\sigma dr d\tau\\
\leq C\sum_{|\gamma|\leq N}\sum_{n\leq N}\int_{\Sigma_{\tau_1}} \mathcal{E}_{p}[\mathbf{Z}^{\gamma}\psi_{\geq \ell}]\,d\sigma dr\\
+C\int_{\tau_1}^{\tau_2}\int_{\Sigma_{\tau}} \max\{(r^{-1}\Omega)^{-p}\rho_+^{1-2\epsilon}r^{-1+2\epsilon},1\}r^{-2}|\mathbf{Z}^{\gamma}(r^3G_{\widehat{A}})_{\geq \ell}|^2+\Omega^2r^{-2}(1-\upzeta) |\mathbf{Z}^{\gamma}T( r^3G_{\widehat{A}})_{\geq \ell} |^2\,d\sigma dr d\tau.
\end{multline}

\label{prop:edecay}
Let $N_1\in \mathbb{N}_1$, $N_2\in \mathbb{N}_0$ and $q_1\in [0,\infty)$. Let $\psi$ be a solution to \eqref{eq:rCSF} with $A=\widehat{A}$ and $|q|\leq q_1$. For all $\nu>0$, there exists an $\epsilon_0>0$, such that for all $0\leq \epsilon\leq \epsilon_0$ and $1+\epsilon\leq p\leq 1+\textnormal{Re}\,\sqrt{1-4q_1^2}+\epsilon$, there exists a constant $C=C(\mathbbm{h},\nu,\epsilon_0,p, N_1,N_2,q_1)>0$ such that:
\begin{multline}
\label{eq:energydecay}
(1+\tau)^{2N_1-\nu}\int_{\Sigma_{\tau}}\sum_{|\gamma|\leq N_2}\mathcal{E}_{p}[\mathbf{Z}^{\gamma}(TK)^{N_1}\psi]\,d\sigma dr \\
\leq C\sum_{m\leq N_1}\sum_{|\gamma|+m\leq N_1+N_2}\sum_{j\leq 2N_1}\int_{\Sigma_{0}} \mathcal{E}_{p}[\mathbf{Z}^{\gamma}(TK)^mT^j\psi]\,d\sigma dr\\
+\sup_{\tau\in [0,\infty)}\int_{\Sigma_{\tau}} (1+\tau)^{2-\epsilon+2\max\{m-1,0\}}(\Omega r^{-1})^{2-p}r^{-2}|r^3\mathbf{Z}^{\gamma}T^j(TK)^{\max\{m-1,0\}}G_{\widehat{A}}|^2\,d\sigma dr d\tau\\
+\int_{0}^{\infty} \int_{\Sigma_{\tau}} (1+\tau)^{2m}\Big[\max\{(r^{-1}\Omega)^{-p}\rho_+^{1-2\epsilon}r^{-1+2\epsilon},1\}r^{-2}|r^3\mathbf{Z}^{\gamma}T^j(TK)^mG_{\widehat{A}}|^2\\
+\Omega^2(1-\upzeta)|r\mathbf{Z}^{\gamma}T^{j+1}(TK)^mG_{\widehat{A}}|^2\Bigg]\,d\sigma dr d\tau.
\end{multline}

We set $A=\widehat{A}$. For the sake of notational convenience, we write $G=G_{\widehat{A}}$. We first consider the case $N_2=0$ and $N_1=1$. Let $0\leq \sigma<1$ and define $\mathcal{D}_{\sigma,\tau_A}:=\{\rho_+\leq \frac{1}{2}(1+\tau_A)^{- \sigma}\}\cap \{r\geq 4(1+\tau_A)^{\sigma}\}$. Let $\epsilon'>0$. Then we can split the following integral:
\begin{multline*}
\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau=\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau} \cap \mathcal{D}_{\sigma,\tau_A} }\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau+\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}\setminus \mathcal{D}_{\sigma,\tau_A}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\\
\lesssim \overbrace{\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}\cap \mathcal{D}_{\sigma,\tau_A}}(\Omega r^{-1})^{2-p'}r^2|XTK\psi|^2\,d\sigma dr d\tau}^{=:J_1}+\overbrace{\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}\cap \mathcal{D}_{\sigma,\tau_A} }|TTK\psi|^2+|\slashed{\nabla}_{\mathbb{S}^2}TK\psi|^2+|TK\psi|^2\,d\sigma dr d\tau}^{=:J_2}\\
+\overbrace{\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau} \setminus  (\mathcal{D}_{\sigma,\tau_A}\cup \{r^{\sharp}-\eta\leq r\leq r^{\sharp}+\eta\} ) }\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau}^{=:J_3}+\overbrace{\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau} \cap \{r_{\sharp}-\eta\leq r\leq r_{\sharp}+\eta\}  }\mathcal{E}_{0}[TK\psi]\,d\sigma dr d\tau}^{=:J_4}.
\end{multline*}
We will estimate each of the terms $J_i$ separately.

Take $1+\epsilon'\leq p'\leq 1+\textnormal{Re}\, \sqrt{1-4q^2}+\epsilon'$, where $\epsilon'>0$ will be chosen suitably small.

To estimate $J_1$, we use that by \eqref{eq:maineqradfield} and \eqref{eq:maineqradfieldconfhor}
\begin{equation}
\label{eq:TKvsZ}
r^2|XTK\psi|^2\lesssim \sum_{|\gamma|\leq 1} \mathcal{E}_{0}[\mathbf{Z}^{\gamma}T\psi]+\mathcal{E}_{0}[\mathbf{Z}^{\gamma}\psi]+ r^{-2}|r^3TG|^2+r^{-2}|r^3G|^2.
\end{equation}
Hence,
\begin{multline*}
J_1\lesssim \sum_{|\gamma|\leq 1}\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}\cap \mathcal{D}_{\sigma,\tau_A}} (\Omega r^{-1})^{2-p'}\left[\mathcal{E}_{0}[\mathbf{Z}^{\gamma}T\psi]+\mathcal{E}_{0}[\mathbf{Z}^{\gamma}\psi]\right]\,d\sigma dr d\tau\\
+\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}} (\Omega r^{-1})^{2-p'}r^{-2}(|r^3TG|^2+|r^3G|^2)\,d\sigma dr d\tau\\
\lesssim (1+\tau_A)^{-\sigma(1+p-2\epsilon-p')} \sum_{|\gamma|\leq 1}\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}\cap \mathcal{D}_{\sigma,\tau_A}} (\Omega r^{-1})^{1-p+2\epsilon}\left[\mathcal{E}_{0}[\mathbf{Z}^{\gamma}T\psi]+\mathcal{E}_{0}[\mathbf{Z}^{\gamma}\psi]\right]\,d\sigma dr d\tau\\
+ (1+\tau_A)^{-\sigma(1+p-p')} \int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}} (1+\tau)^{\sigma(1+p-p')} (\Omega r^{-1})^{2-p'}(|rTG|^2+|rG|^2)\,d\sigma dr d\tau\\
\lesssim (1+\tau_A)^{-\sigma(1+p-2\epsilon-p')} \sum_{|\gamma|\leq 1}\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}\cap \mathcal{D}_{\sigma,\tau_A}} \mathcal{E}_{p-1-2\epsilon}[\mathbf{Z}^{\gamma}T\psi]+\mathcal{E}_{p-1+2\epsilon}[\mathbf{Z}^{\gamma}\psi]\,d\sigma dr d\tau\\
+ (1+\tau_A)^{-\sigma(1+p-2\epsilon-p')} \int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}} (1+\tau)^{\sigma(1+p-p'-2\epsilon)} (\Omega r^{-1})^{2-p'}r^{-2}(|r^3TG|^2+|r^3G|^2)\,d\sigma dr
\end{multline*}
We now apply \eqref{eq:horpestrmin1pest} with $p=p'$, $\epsilon=2\epsilon'$ and $|\gamma|=1$ to obtain:
\begin{multline*}
J_1\lesssim  (1+\tau_A)^{-\sigma(1-4\epsilon')}\sum_{|\gamma|\leq 1}\int_{\Sigma_{\tau_A}} \mathcal{E}_{p' }[\mathbf{Z}^{\gamma}\psi]+\mathcal{E}_{p'}[\mathbf{Z}^{\gamma}T\psi]\,d\sigma dr\\
+ (1+\tau_A)^{-\sigma(1-4\epsilon')}\sum_{|\gamma|\leq 1}\int_{\tau_A}^{\tau_B} \int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}r^{-2}(|\mathbf{Z}^{\gamma}( r^3G) |^2+|\mathbf{Z}^{\gamma}( r^3TG) |^2)\\
+(1-\upzeta)\Omega^2r^{-2}|\mathbf{Z}^{\gamma}T^{2}( r^3G) |^2\,d\sigma dr d\tau\\
+ (1+\tau_A)^{-\sigma(1-4\epsilon') } \int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}} (1+\tau)^{\sigma(1-4\epsilon') }  (\Omega r^{-1})^{2-p'}r^{-2}(|r^3TG|^2+|r^3G|^2)\,d\sigma dr.
\end{multline*}

We can estimate $J_2$ as follows:
\begin{multline*}
J_2\lesssim (1+\tau_A)^{-\sigma(1-2\epsilon)}\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}\cap \mathcal{D}_{\sigma,\tau_A} } (\Omega r^{-1})^{-1+2\epsilon}\left[|TTK\psi|^2+|\slashed{\nabla}_{\mathbb{S}^2}TK\psi|^2+|TK\psi|^2\right]\,d\sigma dr d\tau\\
\lesssim (1+\tau_A)^{-\sigma(1-2\epsilon)}\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}\cap \mathcal{D}_{\sigma,\tau_A} }(r^{-1}\Omega)^{-1+2\epsilon}(|D_TT^2\psi|^2+|\slashed{\nabla}_{\mathbb{S}^2}D_TT\psi|^2+|D_TT\psi|^2)\\
+(r^{-1}\Omega)^{-1+2\epsilon}\rho_+^{2}(|T\psi|^2+|\slashed{\nabla}_{\mathbb{S}^2}T\psi|^2+|T^2\psi|^2)\,d\sigma dr d\tau.
\end{multline*}
We apply \eqref{eq:horpest} with $|\gamma|=0$, $p=p'$, $\epsilon=2\epsilon'$, to $T\psi$ and $T^2\psi$ to obtain:
\begin{multline*}
J_2\lesssim C (1+\tau_A)^{-\sigma(1-4\epsilon')}\int_{\Sigma_{\tau_A}} \mathcal{E}_{p' }[T\psi]+\mathcal{E}_{p'}[T^2\psi]\,d\sigma dr\\
+C(1+\tau_A)^{-\sigma(1-4\epsilon')}\int_{\tau_A}^{\tau_B} \int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}r^{-2}(| r^3TG |^2+| r^3T^2G |^2)\\
+(1-\upzeta)\Omega^2r^{-2}|T^{3}( r^3G) |^2\,d\sigma dr d\tau.
\end{multline*}

We estimate $J_3$:
\begin{equation*}
J_3\lesssim (1+\tau_A)^{\sigma(1+4\epsilon')}\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau} \setminus  \{r_{\sharp}-\eta\leq r\leq r_{\sharp}+\eta\}  }\mathcal{E}_{p'-1-4\epsilon'}[TK\psi]\,d\sigma dr d\tau.
\end{equation*}
We apply \eqref{eq:horpest} with $|\gamma|=0$, $p=p'$ and $\epsilon=2\epsilon'$ to $TK\psi$ to obtain:
\begin{multline*}
J_3\lesssim  C (1+\tau_A)^{\sigma(1+4\epsilon')}\int_{\Sigma_{\tau_A}} \mathcal{E}_{p'}[TK\psi]\,d\sigma dr\\
+C(1+\tau_A)^{\sigma(1+4\epsilon')}\sum_{j=0}^1\int_{\tau_A}^{\tau_B} \int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}r^{-2}| r^3T^jTKG |^2+(1-\upzeta)\Omega^2r^{-2}| r^3T^{j+1}TKG |^2\,d\sigma dr d\tau.
\end{multline*}
Finally, we can estimate $J_4$ by directly applying \eqref{eq:horpestrmin1pest} with $|\gamma|=0$, $p=1+\epsilon'$ and $\epsilon=2\epsilon'$ to obtain:
\begin{multline*}
J_4\lesssim C \int_{\Sigma_{\tau_A}} \mathcal{E}_{1+\epsilon'}[TK\psi]+ \mathcal{E}_{1+\epsilon'}[T^2K\psi]\,d\sigma dr\\
+C\int_{\tau_A}^{\tau_B} \int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-1-\epsilon'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}r^{-2}| r^3TKG |^2+(1-\upzeta)\Omega^2r^{-2}|T( r^3TKG) |^2\,d\sigma dr d\tau.
\end{multline*}

We conclude that:
\begin{multline}
\label{eq:mainestedecay}
\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim  (1+\tau_A)^{\sigma(1+4\epsilon')}\int_{\Sigma_{\tau_A}} \mathcal{E}_{p'}[TK\psi]\,d\sigma dr+ \int_{\Sigma_{\tau_A}} \mathcal{E}_{p'}[TK\psi]+ \mathcal{E}_{p'}[T^2K\psi]\,d\sigma dr\\
+(1+\tau_A)^{-\sigma(1-4\epsilon')}\sum_{|\gamma|\leq 1}\int_{\Sigma_{\tau_A}} \mathcal{E}_{p'}[\mathbf{Z}^{\gamma}\psi]+\mathcal{E}_{p'}[\mathbf{Z}^{\gamma}T\psi]\,d\sigma dr\\
+(1+\tau_A)^{-\sigma(1-4\epsilon')}\int_{\tau_A}^{\tau_B} \sum_{j=0}^1\int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}(1+\tau)^{2\sigma(1-4\epsilon')}r^{-2}| r^3T^jTKG |^2\\
+(1-\upzeta)\Omega^2r^{-2}(1+\tau)^{2\sigma(1-4\epsilon')}| r^3T^{j+1}TKG |^2\,d\sigma dr d\tau\\
+ (1+\tau_A)^{-\sigma(1-4\epsilon')}\sum_{|\gamma|\leq 1}\int_{\tau_A}^{\tau_B} \int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}r^{-2}(|\mathbf{Z}^{\gamma}( r^3G) |^2+|\mathbf{Z}^{\gamma}( r^3TG) |^2)\\
+(1-\upzeta)\Omega^2r^{-2}|\mathbf{Z}T^{2}( r^3G) |^2\,d\sigma dr d\tau\\
+ (1+\tau_A)^{-\sigma (1-4\epsilon')} \int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}} (1+\tau)^{\sigma(1-4\epsilon') }  (\Omega r^{-1})^{2-p'}r^{-2}(|r^3TG|^2+|r^3G|^2)\,d\sigma dr\\
\leq (1+\tau_A)^{\sigma(1+4\epsilon')}\int_{\Sigma_{\tau_A}} \mathcal{E}_{p'}[TK\psi]\,d\sigma dr+ \int_{\Sigma_{\tau_A}} \mathcal{E}_{p'}[TK\psi]+ \mathcal{E}_{p'}[T^2K\psi]\,d\sigma dr\\
+(1+\tau_A)^{-\sigma(1-4\epsilon')}\sum_{|\gamma|\leq 1}\int_{\Sigma_{\tau_A}} \mathcal{E}_{p'}[\mathbf{Z}^{\gamma}\psi]+\mathcal{E}_{p'}[\mathbf{Z}^{\gamma}T\psi]\,d\sigma dr+(1+\tau_A)^{-\sigma(1-4\epsilon')}\mathcal{G}[G],
\end{multline}
with
\begin{multline*}
	\mathcal{G}[G]:=\sum_{j\leq 1}\int_{0}^{\infty} \int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}(1+\tau)^{2\sigma(1-4\epsilon')}r^{-2}| r^3T^jTKG |^2\\
	+(1-\upzeta)\Omega^2r^{-2}(1+\tau)^{2\sigma(1-4\epsilon')}| r^3T^{j+1}TKG |^2\,d\sigma dr d\tau\\
+ \sum_{|\gamma|\leq 1}\int_{0}^{\infty} \int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}r^{-2}|(\mathbf{Z}^{\gamma}( r^3G) |^2+|\mathbf{Z}^{\gamma}( r^3TG) |^2)+(1-\upzeta)\Omega^2r^{-2}|\mathbf{Z}^{\gamma}T^{2}( r^3G) |^2\,d\sigma dr d\tau\\
+  \sup_{\tau\in[0,\infty)}\int_{\Sigma_{\tau}} (1+\tau)^{\sigma(1-4\epsilon')+1+\epsilon'}  (\Omega r^{-1})^{2-p'}r^{-2}(|r^3TG|^2+|r^3G|^2)\,d\sigma dr.
\end{multline*}

\paragraph{\underline{Step 1: $\tau^{-1+2\epsilon'}$ }}
Let $\{\tau_j^{(1)}\}$ be a dyadic sequence. Taking $\sigma=0$, $\tau_A=\tau_j^{(1)}$ and $\tau_{B}=\tau_{j+1}^{(1)}$ in \eqref{eq:mainestedecay} and applying the mean-value theorem (``pigeonhole principle''), we obtain along a dyadic subsequence  $\{\tau_j^{(2)}\}$ of $\{\tau_j^{(1)}\}$:
\begin{multline}
\label{eq:firstedecayest}
(1+\tau_j^{(2)})\int_{\Sigma_{\tau_j^{(2)}}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim  \int_{\Sigma_{0}} \mathcal{E}_{p'}[TK\psi]\,d\sigma dr+ \int_{\Sigma_{0}}   \mathcal{E}_{p'}[TK\psi]+ \mathcal{E}_{p'}[T^2K\psi]\,d\sigma dr\\
+\sum_{|\gamma|\leq 1}\int_{\Sigma_{0}}  \mathcal{E}_{p'}[\mathbf{Z}^{\gamma}\psi]+\mathcal{E}_{p'}[\mathbf{Z}^{\gamma}T\psi]\,d\sigma dr+\mathcal{G}[G]=:D_{0,p',\epsilon'}[\psi].
\end{multline}
Applying \eqref{eq:horpestrmin1pest} with $|\gamma|=0$, $p=p'$ and $\epsilon=2\epsilon'$, we in fact obtain for all $\tau\geq 0$:
\begin{equation*}
\int_{\Sigma_{\tau}}\mathcal{E}_{p'-4\epsilon'}[TK\psi]\,d\sigma dr d\tau\lesssim (1+\tau)^{-1}D_{0,p',\epsilon'}[\psi].
\end{equation*}
Now we apply an interpolation argument. We split
\begin{multline*}
\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim \int_{\Sigma_{\tau}}(\Omega r^{-1})^{2-p'}r^2|XTK\psi|^2\,d\sigma dr d\tau+ \int_{\Sigma_{\tau}}\mathcal{E}_{p'-4\epsilon'}[TK\psi]\,d\sigma dr d\tau\\
=\int_{\Sigma_{\tau}\cap\{r^{-1}\rho_+\leq (1+\tau)^{-1}\}}(\Omega r^{-1})^{2-p'}r^2|XTK\psi|^2\,d\sigma dr d\tau+\int_{\Sigma_{\tau}\cap\{r^{-1}\rho_+\geq (1+\tau)^{-1}\}}(\Omega r^{-1})^{2-p'}r^2|XTK\psi|^2\,d\sigma dr d\tau\\
+ \int_{\Sigma_{\tau}}\mathcal{E}_{p'-4\epsilon'}[TK\psi]\,d\sigma dr d\tau
\end{multline*}
and then apply \eqref{eq:TKvsZ} to further estimate the second term on the RHS, so that we obtain:
\begin{multline*}
\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim (1+\tau)^{4\epsilon'} \int_{\Sigma_{\tau}}\mathcal{E}_{p'-4\epsilon'}[TK\psi]\,d\sigma dr d\tau\\
+(1+\tau)^{-1+4\epsilon'}\sum_{|\gamma|\leq 1}\int_{\Sigma_{\tau}} \mathcal{E}_{p'-4\epsilon'}[\mathbf{Z}^{\gamma}T\psi]+\mathcal{E}_{p'-4\epsilon'}[\mathbf{Z}^{\gamma}\psi]\,d\sigma dr d\tau\\
+ (1+\tau)^{-1+4\epsilon'}\int_{\Sigma_{\tau}}(1+\tau)^{1-4\epsilon'}(\Omega r^{-1})^{2-p'}r^{-2}(|r^3TG|^2+|r^3G|^2)\,d\sigma dr.
\end{multline*}
By applying \eqref{eq:horpest} with $|\gamma|=1$ to $\psi$ and $T\psi$, $p=p'$ and $\epsilon=2\epsilon'$ once more, we conclude the first global-in-$\tau$ decay result:
\begin{equation}
\label{eq:firstedecayestpart2}
\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim (1+\tau)^{-1+4\epsilon'}D_{0,p',\epsilon'}[\psi].
\end{equation}
Note that the above interpolation argument can also be used to conclude the $N_1=0$ case of the theorem.\\
\\

\paragraph{\underline{Step 2: $\tau^{-\frac{3}{2}}$ decay}}
We will now improve the decay rate. We apply \eqref{eq:mainestedecay} again and we moreover apply \eqref{eq:firstedecayestpart2} to estimate the first two integrals on the RHS. We obtain:
\begin{multline}
\label{eq:edecaystep2}
\int_{\tau_A}^{\tau_B}\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim  (1+\tau_A)^{\sigma-1+4\epsilon'}D_{0,p',\epsilon'}[\psi]+(1+\tau_A)^{-1+4\epsilon'}D_{0,p',\epsilon'}[T\psi]\\
+(1+\tau_A)^{-\sigma(1-4\epsilon')}\sum_{|\gamma|\leq 1}\int_{\Sigma_{\tau_A}} \mathcal{E}_{p'}[\mathbf{Z}^{\gamma}\psi]+\mathcal{E}_{p'}[\mathbf{Z}^{\gamma}T\psi]\,d\sigma dr+(1+\tau_A)^{-\sigma(1-4\epsilon')}\mathcal{G}[G].
\end{multline}
Let $\{\tau_j^{(1)}\}$ be a dyadic sequence. Taking $\sigma=\frac{1}{2}$, $\tau_A=\tau_j^{(1)}$ and $\tau_{B}=\tau_{j+1}^{(1)}$ in \eqref{eq:edecaystep2} and applying the mean-value theorem, we obtain along a dyadic subsequence  $\{\tau_j^{(2)}\}$ of $\{\tau_j^{(1)}\}$:
\begin{multline}
\label{eq:edecaystep2b}
(1+\tau_j^{(2)})^{\frac{3}{2}-4\epsilon'}\int_{\Sigma_{\tau_j^{(2)}}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim  D_{0,p',\epsilon'}[\psi]+(1+\tau_j^{(2)})^{-\frac{1}{2}}D_{0,p',\epsilon'}[T\psi]\\
+\sum_{|\gamma|\leq 1}\int_{\Sigma_{0}} \mathcal{E}_{p'}[\mathbf{Z}^{\gamma}\psi]+\mathcal{E}_{p'}[\mathbf{Z}^{\gamma}T\psi]\,d\sigma dr+\mathcal{G}[G]\\
=:D_{1,p',\epsilon'}[\psi]+(1+\tau_j^{(2)})^{-\frac{1}{2}}D_{0,p',\epsilon'}[T\psi].
\end{multline}
We repeat the interpolation argument at the end of Step 1 by considering $\{r^{-1}\rho_+\leq (1+\tau)^{-\frac{3}{2}}\}$ and $\{r^{-1}\rho_+\geq (1+\tau)^{-\frac{3}{2}}\}$ to conclude that
\begin{equation*}
\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr \lesssim \tilde{D}_{1,p',\epsilon'}[\psi](1+\tau)^{-\frac{3}{2}+8\epsilon'},
\end{equation*}
with
\begin{equation*}
\tilde{D}_{1,p',\epsilon'}[\psi]:=D_{1,p,\epsilon'}[\psi]+D_{0,p',\epsilon'}[T\psi].
\end{equation*}

\paragraph{\underline{Step 3: $\tau^{-2+\nu}$ decay}}
Note that the only term that does not decay at least like $\tau^{-1+4\epsilon'}$ on the RHS of \eqref{eq:edecaystep2} when $\sigma=1$ is $(1+\tau_A)^{\sigma-1+4\epsilon'}D_{0,p',\epsilon'}[\psi]$.

By Step 2, we have that \eqref{eq:edecaystep2} still holds with $(1+\tau_A)^{\sigma-1+4\epsilon'}D_{0,p',\epsilon'}[\psi]$ replaced by\\ $(1+\tau_A)^{\sigma-\frac{3}{2}+4\epsilon'}\tilde{D}_{1, p',\epsilon'}[\psi]$.

We can therefore take $\sigma=\frac{3}{4}$ and conclude that:
\begin{equation*}
\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim \tilde{D}_{1,p',\epsilon'}[\psi](1+\tau)^{-\frac{7}{4}+12\epsilon'}.
\end{equation*}
Continuing this procedure iteratively, taking $\sigma =1-\frac{1}{2^k}$, we can show:
\begin{equation*}
\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim \tilde{D}_{1,p',\epsilon'}[\psi](1+\tau)^{2-\frac{1}{2k}+4k\epsilon'}.
\end{equation*}

We conclude that for all $\nu>0$, there exists a suitably small $\epsilon'>0$, such that for $1+\epsilon'\leq p'\leq 1+\textnormal{Re}\,\sqrt{1-4q^2}+\epsilon'$:
\begin{multline*}
(1+\tau)^{2-\nu}\int_{\Sigma_{\tau}}\mathcal{E}_{p'}[TK\psi]\,d\sigma dr d\tau\lesssim \sum_{|\gamma|+m\leq 1}\sum_{j\leq 2}\int_{\Sigma_{0}} \mathcal{E}_{p'}[\mathbf{Z}^{\gamma}(TK)^mT^j\psi]\,d\sigma dr\\
+\sum_{j=0}^2\int_{0}^{\infty} \int_{\Sigma_{\tau}}(1+\tau)^{2-4\epsilon'}\left[\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}r^{-2}| r^3T^j(TK)G |^2+(1-\upzeta)\Omega^2r^{-2}| r^3T^{1+j}
TKG |^2\right]\,d\sigma dr d\tau\\
+ \sum_{|\gamma|\leq 1}\sum_{j=0}^1\int_{0}^{\infty} \int_{\Sigma_{\tau}}\max\{(r^{-1}\Omega)^{-p'}\rho_+^{1-4\epsilon'}r^{-1+4\epsilon'},1\}r^{-2}(|\mathbf{Z}^{\gamma}( r^3T^jG) |^2+|\mathbf{Z}^{\gamma}( r^3T^{j+1}G) |^2)\\
+(1-\upzeta)\Omega^2r^{-2}|\mathbf{Z}^{\gamma}T^{2+j}( r^3G) |^2\,d\sigma dr d\tau\\
+  \sum_{j=0}^1\sup_{\tau\in[0,\infty)}\int_{\Sigma_{\tau}} (1+\tau)^{2-2\epsilon'}  (\Omega r^{-1})^{2-p'}r^{-2}(|r^3T^{j+1}G|^2+|r^3T^jG|^2)\,d\sigma dr.
\end{multline*}

\paragraph{\underline{Step 4: general $N_1,N_2$}}
Now we consider the general $N_1\in \mathbb{N}_1$, $N_2\in \mathbb{N}_0$ case. We repeat Steps 1 and 2 above but we generalize \eqref{eq:TKvsZ} as follows:
\begin{equation*}
\sum_{|\gamma|\leq N-1}r^2|XTK\mathbf{Z}^{\gamma}\psi|^2\lesssim \sum_{|\gamma|\leq N} \mathcal{E}_{0}[\mathbf{Z}^{\gamma}T\psi]+\mathcal{E}_{0}[\mathbf{Z}^{\gamma}\psi]+r^{-2}\sum_{|\gamma|\leq N-1} |r^3\mathbf{Z}^{\gamma}TG|^2+|r^3\mathbf{Z}^{\gamma}G|^2.
\end{equation*}
We apply the above inequality $N_1$ times.

\label{prop:edecaygeneralp}           
Let $N_1\in \mathbb{N}_1$, $N_2\in \mathbb{N}_0$ and $q_1\in [0,\infty)$. Let $|q|\leq q_1$. Let $1+\textnormal{Re}\, \sqrt{1-4q_1^2}< p<2+\textnormal{Re}\, \sqrt{1-4q_1^2}$. For all $\nu>0$ and $0<\epsilon<p-1-\textnormal{Re}\, \sqrt{1-4q_1^2}<1$, there exists a constant\\ $C=C(\mathbbm{h},\nu,\epsilon, N_1,N_2,p,q_1)>0$ such that:
\begin{multline}
\label{eq:energydecayp}
(1+\tau)^{1+\textnormal{Re}\,\sqrt{1-4\tilde{q}^2}-p+\epsilon-\nu+2N_1}\int_{\Sigma_{\tau}}\sum_{|\gamma|\leq N_2}\mathcal{E}_{p}[\mathbf{Z}^{\gamma}(TK)^{N_1}\psi]\,d\sigma dr \\
\leq C\sum_{m\leq N_1}\sum_{|\gamma|+m\leq N_1+N_2}\sum_{j\leq 2N_1}\int_{\Sigma_{0}} \mathcal{E}_{1+\textnormal{Re}\, \sqrt{1-4\tilde{q}^2}+\epsilon}[\mathbf{Z}^{\gamma}(TK)^mT^j\psi]\,d\sigma dr\\
+\sup_{\tau\in [0,\infty)}\int_{\Sigma_{\tau}} (1+\tau)^{2-\epsilon+2\max\{m-1,0\}}(\Omega r^{-1})^{2-p}r^{-2}|r^3\mathbf{Z}^{\gamma}T^j(TK)^{\max\{m-1,0\}}G_{\widehat{A}}|^2\,d\sigma dr d\tau\\
+\int_{0}^{\infty} \int_{\Sigma_{\tau}} (1+\tau)^{2m}\Big[\max\{(r^{-1}\Omega)^{-1-\textnormal{Re}\, \sqrt{1-4\tilde{q}^2}-\epsilon}\rho_+^{1-2\epsilon}r^{-1+2\epsilon},1\}r^{-2}|r^3\mathbf{Z}^{\gamma}T^j(TK)^mG_{\widehat{A}}|^2\\
+\Omega^2(1-\upzeta)|r\mathbf{Z}^{\gamma}T^{j+1}(TK)^mG_{\widehat{A}}|^2\Big]\,d\sigma dr d\tau.
\end{multline}

We will prove the case $N_1=1$, $N_2=0$. The general case proceeds entirely analogously. We apply an interpolation argument. Split:
\begin{multline*}
\int_{\Sigma_{\tau}}\mathcal{E}_{p}[TK\psi]\,d\sigma dr=\int_{ \Sigma_{\tau}\cap\{r^{-1}\rho_+\leq (1+\tau)^{-1}\}}\mathcal{E}_{p}[TK\psi]\,d\sigma dr\\
+\int_{ \Sigma_{\tau}\cap\{r^{-1}\rho_+> (1+\tau)^{-1}\}}\mathcal{E}_{p}TK\psi]\,d\sigma dr\\
\lesssim  \int_{ \Sigma_{\tau}\cap\{r^{-1}\rho_+\leq (1+\tau)^{-1}\}}(r^{-1}\Omega)^{2-p}r^2|XTK\psi|^2\,d\sigma dr\\
+(1+\tau)^{p-(1+\textnormal{Re}\, \sqrt{1-4\tilde{q}^2} +\epsilon)}\int_{\Sigma_{\tau}}\mathcal{E}_{1+\textnormal{Re}\, \sqrt{1-4\tilde{q}^2}+\epsilon}[\mathbf{Z}^{\gamma}(TK)^{N_1}\psi]\,d\sigma dr.
\end{multline*}
We use that by \eqref{eq:maineqradfield} and \eqref{eq:maineqradfieldconfhor}:
\begin{equation}
\label{eq:TKvsZv2}
r^2|XTK\psi|^2\lesssim \sum_{|\gamma|\leq 1} \mathcal{E}_{0}[\mathbf{Z}^{\gamma}T\psi]+\mathcal{E}_{0}[\mathbf{Z}^{\gamma}\psi]+ |rTG|^2+|rG|^2
\end{equation}
to estimate:
\begin{multline*}
 \int_{ \Sigma_{\tau}\cap\{r^{-1}\rho_+\leq (1+\tau)^{-1}\}}(r^{-1}\Omega)^{2-p}r^2|XTK\psi|^2\,d\sigma dr\\
 \lesssim (1+\tau)^{-3-\sqrt{1-4\tilde{q}^2}+\epsilon+\nu+p}\sum_{|\gamma|\leq 1}\sum_{j\leq 1}\int_{\Sigma_{\tau}}\mathcal{E}_{1+\sqrt{1-4\tilde{q}^2}-\epsilon-\nu}[\mathbf{Z}^{\gamma}T^j\psi]\,d\sigma dr\\
 +(1+\tau)^{-2+\epsilon}\sum_{j\leq 1}\int_{\Sigma_{\tau}} (1+\tau)^{2-\epsilon}(r^{-1}\Omega)^{2-p}[|rTG|^2+|rG|^2]\,d\sigma dr.
\end{multline*}
The first integral on the RHS above can then be estimated by \eqref{eq:horpestrmin1pest} applied to $\psi$ and $T\psi$.

\label{prop:estinhomG}
Fix $r_+=1$. Let $n_1,n_2\in \mathbb{N}_0$. Then there exists a constant $C=C(n_1,n_2,\widetilde{\mathbbm{h}})>0$ such that:
\begin{equation}
\label{eq:erroresteqforPsiinf}
\left|r^3((r-1)X)^{n_1}((\tau+1)T)^{n_2}G[\Psi^{\infty}]\right|(\tau,r,\theta,\varphi)\leq 
C ((\tau+1)r^{-1}+2)^{-\frac{1}{2}-\frac{1}{2}\textnormal{Re}\, \beta_{\ell}}(\tau+1)^{-\frac{3}{2}-\frac{1}{2}\textnormal{Re}\, \beta_{\ell}}.
\end{equation}
and
\begin{equation}
\label{eq:erroresteqforPsihor}
\left|r^3((r-1)X)^{n_1}((\tau+1)K)^{n_2}G[\Psi^{+}]\right|(\tau,r,\theta,\varphi)\leq C ( (\tau+1)(1-r^{-1})+2)^{-\frac{1}{2}-\frac{1}{2}\textnormal{Re}\, \beta_{\ell}}(\tau+1)^{-\frac{3}{2}-\frac{1}{2}\textnormal{Re}\, \beta_{\ell}}.
\end{equation}

Let $r_+=1$ and $s_+=(r-1)^{-1}$. The following constants are well-defined:
\begin{align}
\label{eq:defBinf}
	B_{\infty,\ell m}:=&\int_1^{\infty}\mathfrak{w}_{\ell}(r;q)e^{2iq\int_{r_{\sharp}}^rr'^{-1}\Omega^{-2}(r')(1-\mathbbm{h}(r'))\,dr'}\Bigg[ rT^{-1}(G_{\ell m}[\Psi^{\infty}])(0,r)\\ \nonumber
+&\left(2(1-\mathbbm{h})X \Psi^{\infty}_{\ell m}+\mathbbm{h} \widetilde{\mathbbm{h}} T\Psi^{\infty}_{\ell m}-\left(\frac{d\mathbbm{h}}{dr}-2i q r^{-1} \mathbbm{h}\widetilde{\mathbbm{h}}\right)\Psi^{\infty}_{\ell m}\right)(0,r)\Bigg]\,dr,\\
\label{eq:defBhor}
B_{+,\ell m}:=&\int_0^{\infty}\mathfrak{w}_{\ell}(s_++1;-q)e^{-2iq\int_{1}^{s_+}(s'+1)^{-1}\Omega^{-2}(s'+1)(1-\mathbbm{h}^+(s'+1))\,ds'}\Bigg[ rK^{-1}(G_{\ell m}[\Psi^{+}])(0,s_+)\\ \nonumber
+&\left(2(1-\mathbbm{h}^+)\partial_{s_+}\Psi^{+}_{\ell m}+\mathbbm{h}^+ \widetilde{\mathbbm{h}}^+ K\Psi^{+}_{\ell m}-\left(\frac{d\mathbbm{h}^+}{ds_+}-2i q (s_++1)^{-1} \mathbbm{h}^+\widetilde{\mathbbm{h}}^+\right)\Psi^{+}_{\ell m}\right)(0,s_+)\Bigg]\,ds_+.
\end{align}

\label{prop:timeinvffixedmodeconstr}
Fix $r_+=1$. Suppose that $B_{\infty,\ell m}\neq 0$ and fix the constants $\mathfrak{I}_{\ell m}[\psi]$ appearing in the definition of $\Psi^{\infty}$ as follows:
\begin{multline*}
	\mathfrak{I}_{\ell m}[\psi]:=B_{\infty,\ell m}^{-1}\int_{1}^{\infty}\mathfrak{w}_{\ell}(r;q)e^{-2iq\int_{r_{\sharp}}^rr'^{-1}\Omega^{-2}(r')(1-\mathbbm{h}(r'))\,dr'}\\
	\times \left[2(1-\mathbbm{h})X {\psi}_{\ell}+\mathbbm{h} \widetilde{\mathbbm{h}} T{\psi}_{\ell}-\left(\frac{d\mathbbm{h}}{dr}-2i q r^{-1} \mathbbm{h}\widetilde{\mathbbm{h}}\right){\psi}_{\ell}\right](0,r)\,dr.
\end{multline*}
Then there exists a unique solution $T^{-1}(\psi_{\ell m}-\Psi^{\infty}_{\ell m})|_{\Sigma_0}\in C^{\infty}([r_+,\infty))$ to \eqref{eq:maineqcheckpsi0} such that
\begin{align*}
\Omega^2XT^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell})|_{\Sigma_0}(r_+,\cdot)\equiv &\:0,\\
\lim_{r\to \infty}\mathfrak{w}_{\ell}^{-1}(r;q)T^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell})|_{\Sigma_0}(r,\theta,\varphi)=&\: 0.
\end{align*}
We denote with
\begin{equation*}
	T^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell})
\end{equation*}
the solution to \eqref{eq:CSF} with $A=\widehat{A}$ and $G=G[\Psi^{\infty}]$, arising from the initial data:
\begin{equation*}
	\left(T^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell})|_{\Sigma_0}, (\psi_{\ell}-\Psi^{\infty}_{\ell})|_{\Sigma_0}\right).
\end{equation*}
	Then $T(T^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell}))=\psi_{\ell}-\Psi^{\infty}_{\ell}$.

For the sake of notational convenience, we will drop the $m$ in the subscripts $\psi_{\ell m}$. We can write \eqref{eq:maineqcheckpsi} as follows:
\begin{equation}
\label{eq:maineqcheckpsi1}
X(\Omega^2\mathfrak{w}_{\ell}^2 e^{-2iq\int_{r_{\sharp}}^rr'^{-1}\Omega^{-2}(r')(1-\mathbbm{h}(r'))\,dr'}XT^{-1}\widecheck{\psi}_{\ell})(0,r)=r\widetilde{G}_{\ell},
\end{equation}
with
\begin{multline*}
r\widetilde{G}_{\ell}:=-\mathfrak{w}_{\ell}e^{-2iq\int_{r_{\sharp}}^rr'^{-1}\Omega^{-2}(r')(1-\mathbbm{h}(r'))\,dr'}rT^{-1}(G_{\ell m}[\Psi^{\infty}])(0,\cdot)\\
+\mathfrak{w}_{\ell}e^{-2iq\int_{r_{\sharp}}^rr'^{-1}\Omega^{-2}(r')(1-\mathbbm{h}(r'))\,dr'}\left[2(1-\mathbbm{h})X \widehat{\psi}_{\ell}+\mathbbm{h} \widetilde{\mathbbm{h}} T\widehat{\psi}_{\ell}-\left(\frac{d\mathbbm{h}}{dr}-2i q r^{-1} \mathbbm{h}\widetilde{\mathbbm{h}}\right)\widehat{\psi}_{\ell}\right].
\end{multline*}
Since \eqref{eq:maineqcheckpsi1} is a second-order ODE, we need to impose two boundary conditions to obtain a unique solution. We take as our first boundary condition $(\Omega^2XT^{-1}\widecheck{\psi}_{\ell})(1)=0$, which together with the boundedness of $\mathfrak{w}_{\ell}$ at $r=1$ implies that:
\begin{equation*}
XT^{-1}\widecheck{\psi}_{\ell}(r)= e^{2iq\int_{r_{\sharp}}^rr'^{-1}\Omega^{-2}(r')(1-\mathbbm{h}(r'))\,dr'}\Omega^{-2}(r)\mathfrak{w}_{\ell}^{-2}(r)\int_1^rr \widetilde{G}_{\ell}(r')\,dr'.
\end{equation*}
Since $\mathfrak{w}_{\ell}$ is non-vanishing, the above expression is well-defined for all $r>1$.

Note that for $r\leq 2$ and $\delta>0$, we can estimate:
\begin{align*}
|XT^{-1}\widecheck{\psi}_{\ell}(r)|^2\lesssim &\: \Omega^{-3-\delta}(r-1) \int_{1}^r \Omega^{-1+\delta}|r\widetilde{G}_{\ell}(r')|^2\,dr',\\
|T^{-1}\widecheck{\psi}_{\ell}(r)|^2\lesssim &\: (r-1)^{-\delta} \int_{1}^r \Omega^{-1+\delta}|r\widetilde{G}_{\ell}(r')|^2\,dr'+|T^{-1}\widecheck{\psi}_{\ell}(2)|^2.
\end{align*}

The second boundary condition is $\lim_{r\to \infty}T^{-1}\widecheck{\psi}_{\ell}(r)=0$, which implies that
\begin{equation*}
T^{-1}\widecheck{\psi}_{\ell}(r)= -\int_{r}^{\infty}e^{2iq\int_{r_0}^{r'}r''^{-1}\Omega^{-2}(r'')(1-\mathbbm{h}(r''))\,dr''}\Omega^{-2}(r')\mathfrak{w}_{\ell}^{-2}(r')\int_1^{r'} r\widetilde{G}_{\ell}(r'')\,dr''dr'.
\end{equation*}

For $\textnormal{Re}\, \beta_{\ell}< 1$, $r\widetilde{G}_{\ell}$ is integrable for suitably decaying ${\psi}_{\ell}$ so we can choose $\mathfrak{I}_{\ell m}[\psi]$ such that
\begin{equation}
\label{eq:vanishingtildeG}
\int_1^{\infty} r\widetilde{G}_{\ell}(r')\,dr'=0.
\end{equation}
We can guarantee \eqref{eq:vanishingtildeG} by taking:
\begin{multline*}
	\mathfrak{I}_{\ell m}[\psi]=B_{\infty,\ell m}^{-1}\int_{1}^{\infty}\mathfrak{w}_{\ell}e^{-2iq\int_{r_{\sharp}}^rr'^{-1}\Omega^{-2}(r')(1-\mathbbm{h}(r'))\,dr'}\\
	\times \left[2(1-\mathbbm{h})X {\psi}_{\ell}+\mathbbm{h} \widetilde{\mathbbm{h}} T{\psi}_{\ell}-\left(\frac{d\mathbbm{h}}{dr}-2i q r^{-1} \mathbbm{h}\widetilde{\mathbbm{h}}\right){\psi}_{\ell}\right](0,r)\,dr,
\end{multline*}
where we made use of the fact that $B_{\infty,\ell m}\neq 0$.

In that case, we obtain:
\begin{equation*}
T^{-1}\widecheck{\psi}_{\ell}(r)= \int_{r}^{\infty}e^{2iq\int_{r_{\sharp}}^{r'}r''^{-1}\Omega^{-2}(r'')(1-\mathbbm{h}(r''))\,dr''}\Omega^{-2}(r')\mathfrak{w}_{\ell}^{-2}(r')\int_{r'}^{\infty} r\widetilde{G}_{\ell}(r'')\,dr''dr'
\end{equation*}
Hence, by applying Cauchy--Schwarz and taking $0<\delta<1-\textnormal{Re}\, \beta_{\ell}$, we obtain in the case $\beta_{\ell}\neq 0$:
\begin{multline*}
|T^{-1}\widecheck{\psi}_{\ell}(r)|\lesssim  \int_r^{\infty}r'^{-1-\textnormal{Re}\, \beta_{\ell}}\cdot r'^{-\frac{1}{2}+\frac{\textnormal{Re}\, \beta_{\ell}}{2}+\frac{\delta}{2}}\sqrt{\int_{r'}^{\infty}r''^{2-\textnormal{Re}\, \beta_{\ell}-\delta}|r\widetilde{G}_{\ell}|^2(r'')\,dr''}\\
\lesssim r^{-\frac{1}{2}-\frac{\textnormal{Re}\, \beta_{\ell}}{2}+\frac{\delta}{2}}\sqrt{\int_{r}^{\infty}r''^{2-\textnormal{Re}\, \beta_{\ell}-\delta}|r\widetilde{G}_{\ell}|^2(r'')\,dr''}.
\end{multline*}
In the case $\beta_{\ell}=0$, we obtain instead:
\begin{multline*}
|T^{-1}\widecheck{\psi}_{\ell}(r)|\lesssim  \int_r^{\infty}r'^{-1}\cdot (\log (r'+1))^{-2}r'^{-\frac{1}{2}+\frac{\delta}{2}}\sqrt{\int_{r'}^{\infty}r''^{2-\delta}  |r\widetilde{G}_{\ell}|^2(r'')\,dr''}\\
\lesssim r^{-\frac{1}{2}+\frac{\delta}{2}}(\log (r+1))^{-1}\sqrt{\int_{r}^{\infty}r''^{2-\delta}|r\widetilde{G}_{\ell}|^2(r'')\,dr''}
\end{multline*}

Hence, 
\begin{align*}
|T^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell m})|_{\Sigma_0}|^2(r)\lesssim r^{\delta}\int_{r}^{\infty}r'^{2-\textnormal{Re}\, \beta_{\ell}-\delta}|r\widetilde{G}_{\ell}|^2(r')\,dr',\\
|XT^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell m})|_{\Sigma_0}|^2(r)\lesssim  r^{-2+\delta}\int_{r}^{\infty}r'^{2-\textnormal{Re}\, \beta_{\ell}-\delta}|r\widetilde{G}_{\ell}|^2(r')\,dr'.
\end{align*}

Now suppose that $\textnormal{Re}\, \beta_{\ell}>1$. Then we estimate instead in the region $\{r\geq 2\}$:
\begin{multline*}
|T^{-1}\widecheck{\psi}_{\ell}(r)|\lesssim  \int_r^{\infty}r'^{-1-\textnormal{Re}\, \beta_{\ell}}\int_{1}^{r'}  \left|r\tilde{G}_{\ell}(r'')\right|\,dr''\lesssim\int_r^{\infty}r'^{-1+\delta-\textnormal{Re}\, \beta_{\ell}}\sqrt{\int_{1}^{r'} r''^{1-\delta} \left|r\tilde{G}_{\ell}(r'')\right|^2\,dr''} \,dr'\\
\lesssim r^{-\textnormal{Re}\, \beta_{\ell}+\delta}\sqrt{\int_{1}^{\infty} r'^{1-\delta} \left|r\tilde{G}_{\ell}(r')\right|^2\,dr'}.
\end{multline*}
Hence, we can estimate for $r\geq 2$:
\begin{align*}
|T^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell m})|_{\Sigma_0}|^2(r)\lesssim  &\:  r^{1-\textnormal{Re}\,\beta_{\ell}+\delta} \int_{1}^{\infty}r'^{1-\delta}|r'\widetilde{G}_{\ell}|^2(r')\,dr',\\
|XT^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell m})|_{\Sigma_0}|^2(r)\lesssim &\: r^{-1-\textnormal{Re}\,\beta_{\ell}+\delta}\int_{1}^{\infty}r'^{1-\delta}|r'\widetilde{G}_{\ell}|^2(r')\,dr'. \qedhere
\end{align*}

\label{cor:timeinvffixedmodeconstrhor}
Let $|Q|=M$. Fix $r_+=1$. Suppose that $B_{+,\ell m}\neq 0$ and fix:
\begin{multline*}
	\mathfrak{H}_{\ell m}[\psi]:=B_{+,\ell m}^{-1}\int_{0}^{\infty}\mathfrak{w}_{\ell}(1+s_+;-q)e^{2iq\int_{r_{\sharp}+1}^{s_+}(s'+1)^{-1}\Omega^{-2}(s'+1)(1-\mathbbm{h}^+(s'+1))\,ds'}\\
	\times \left[2(1-\mathbbm{h}^+)\partial_{s_+} {\psi}_{\ell}+\mathbbm{h}^+ \widetilde{\mathbbm{h}}^+ K{\psi}_{\ell}-\left(\frac{d\mathbbm{h}^+}{dr}+2i q (s_++1)^{-1} \mathbbm{h}^+\widetilde{\mathbbm{h}}^+\right){\psi}_{\ell}\right](0,s_+)\,ds_+.
\end{multline*}
Then there exists a unique solution $K^{-1}(\psi_{\ell}-\Psi^{+}_{\ell})|_{\Sigma_0}\in C^{\infty}([0,r_+^{-1})_{\rho_{\infty}})$ to \eqref{eq:maineqcheckpsi0} such that
\begin{align*}
\lim_{r\to \infty}XK^{-1}(\psi_{\ell}-\Psi^{+}_{\ell})|_{\Sigma_0}(r,\theta,\varphi)\equiv &\:0,\\
\mathfrak{w}_{\ell}^{-1}\left(1+\frac{1}{r-1};-q\right)K^{-1}(\psi_{\ell}-\Psi^{+}_{\ell})|_{\Sigma_0}(r_+,\cdot)\equiv &\: 0.
\end{align*}
We denote with
\begin{equation*}
	K^{-1}(\psi_{\ell}-\Psi^{+}_{\ell})
\end{equation*}
the solution to \eqref{eq:CSF} with $A=\widehat{A}$ and $G=G[\Psi^{+}]$, arising from the initial data:
\begin{equation*}
	\left(K^{-1}(\psi_{\ell}-\Psi^{+}_{\ell})|_{\Sigma_0}, (\psi_{\ell}-\Psi^{+}_{\ell})|_{\Sigma_0}-iq K^{-1}(\psi_{\ell}-\Psi^{+}_{\ell})|_{\Sigma_0}\right).
\end{equation*}
	Then $K(K^{-1}(\psi_{\ell}-\Psi^{\infty}_{\ell}))=\psi_{\ell}-\Psi^{+}_{\ell}$.

\label{prop:ellipticesthighfreq}
Let $L_0\in \mathbb{N}_0$, $\tau\geq 0$ and let $\phi$ be a solution to \eqref{eq:CSF} with $A=\widehat{A}$ and $G_A\equiv 0$. Let $1<p< 3$. Then for suitable large $L_0>0$, depending on $q$ and $p$, there exists a constant $C=C(p,q,L_0)>0$ such that for all $\tau\geq 0$:
\begin{align}
\label{eq:ellipticenergy1}
\int_{\Sigma_{\tau}} \mathcal{E}_{p-2}[\psi_{\geq L_0}]\,d\sigma dr\leq &\: C\int_{\Sigma_{\tau}} \mathcal{E}_{p}[T\psi_{\geq L_0}]\,d\sigma dr, \\
\label{eq:ellipticenergy2}
\int_{\Sigma_{\tau}} \mathcal{E}_{p-2}[\psi_{\geq L_0}]\,d\sigma dr\leq &\: C\int_{\Sigma_{\tau}} \mathcal{E}_{p}[K\psi_{\geq L_0}]\,d\sigma dr\quad \textnormal{if $|Q|=M$}.
\end{align}

Restrict to $\psi_{\ell}$, with $\ell\geq L_0$, where  $L_0>0$ will be chosen suitably large. Without loss of generality, we may assume that $\psi$ is smooth any compactly supported. The more general case follows from a standard density argument. For the sake of notational convenience, we drop the subscript $\geq L_0$ in $\psi_{\geq L_0}$ in the estimates below. Rearranging \eqref{eq:maineqradfield} then gives:
 \begin{multline}
 \label{eq:degelliptic}
X(\Omega^2X\psi)+r^{-2}\slashed{\Delta}_{\mathbb{S}^2}\psi-\frac{d\Omega^2}{dr} r^{-1}\psi+2i q(1-\mathbbm{h})r^{-1}X\psi+\left[-iqr^{-1}\frac{d\mathbbm{h}}{dr}+q^2  \mathbbm{h}\widetilde{\mathbbm{h}}r^{-2}+i q r^{-2}(1-\mathbbm{h})\right]\psi\\
=2(1-\mathbbm{h})XT\psi-\mathbbm{h} \widetilde{\mathbbm{h}} T^2\psi-\left(\frac{d\mathbbm{h}}{dr}-2i q r^{-1} \mathbbm{h}\widetilde{\mathbbm{h}}\right)T\psi=: r\tilde{G}[T\psi].
\end{multline}
We use that
\begin{equation*}
rX(\Omega^2X\psi)+r^{-1}\slashed{\Delta}_{\mathbb{S}^2}\psi-r\frac{d\Omega^2}{dr} r^{-1}\psi=X(r^2\Omega^2X\phi)+\slashed{\Delta}_{\mathbb{S}^2}\phi
\end{equation*}
and rearrange \eqref{eq:degelliptic} further:
\begin{equation}
 \label{eq:degelliptic2}
X(r^2\Omega^2X\phi)+\slashed{\Delta}_{\mathbb{S}^2}\phi=-2i q(1-\mathbbm{h})rX\phi+\left[-iq r\frac{d\mathbbm{h}}{dr}-q^2  \mathbbm{h}\widetilde{\mathbbm{h}}-3i q (1-\mathbbm{h})\right]\phi+r^2\tilde{G}[T\psi].
\end{equation}



Multiplying both sides of \eqref{eq:degelliptic2} with $r^{-s}(r^{-1}\Omega)^{p'}X\phi$, taking the real parts of the products and applying the Leibniz rule, we obtain;
 \begin{multline*}
\frac{1}{2}r^{4-s}(r^{-1}\Omega)^{p'+2}X(|X\phi|^2)+2(r^{-1}\Omega)^{p'}r^{-s}\frac{d}{dr}(r^2\Omega^2)|X\phi|^2+\textnormal{Re}\,(r^{-s}(r^{-1}\Omega)^{p'} \overline{X\phi}\cdot \slashed{\Delta}_{\mathbb{S}^2}\phi)\\
+r^{-s}(r^{-1}\Omega)^{p'}\textnormal{Re}\,\left(\overline{X\phi}\cdot \left[iq r\frac{d\mathbbm{h}}{dr}+q^2  \mathbbm{h}\widetilde{\mathbbm{h}}+3i q (1-\mathbbm{h})\right]\phi\right)\\
=r^{-s}(r^{-1}\Omega)^{p'}\textnormal{Re}\, \left( \overline{X\phi}\cdot r^2\tilde{G}[T\psi]\right).
\end{multline*}
We can further write:
\begin{multline*}
\frac{1}{2}r^{4-s}(r^{-1}\Omega)^{p'+2}X(|X\phi|^2)+2r^{-s}(r^{-1}\Omega)^{p'}\frac{d}{dr}(r^2\Omega^2)|X\phi|^2\\
=X\left(\frac{1}{2}r^{4-s}(r^{-1}\Omega)^{p'+2}|X\phi|^2\right)+\left[2r^{-s}\frac{d}{dr}(r^2\Omega^2)-\frac{1}{2}\frac{d}{dr}(r^{4-s}(r^{-1}\Omega)^{p'+2})\right]|X\phi|^2\\
=X\left(\frac{1}{2}r^4(r^{-1}\Omega)^{p'+2}|X\phi|^2\right)+\left[\left(3-\frac{p'}{2}\right)(r-M)+\left(p'+\frac{s}{2}\right)r\Omega^2\right]r^{-s}(r^{-1}\Omega)^{p'}|X\phi|^2.
\end{multline*}
Furthermore,
\begin{multline*}
\textnormal{Re}\,(r^{-s}(r^{-1}\Omega)^{p'} \overline{X\phi}\cdot \slashed{\Delta}_{\mathbb{S}^2}\phi)=-\ell(\ell+1)\textnormal{Re}\,(r^{-s}(r^{-1}\Omega)^{p'} \overline{X\phi}\cdot \phi)=-\frac{1}{2}\ell(\ell+1) X(r^{-s}(r^{-1}\Omega)^{p'}|\phi|^2)\\
+\frac{1}{4}\left[p'\frac{d}{dr}(\Omega^2r^{-2})-2sr^{-3}\Omega^2\right] \ell(\ell+1)r^{-s}(r^{-1}\Omega)^{p'-2}|\phi|^2\\
=-\frac{1}{2}\ell(\ell+1) X(r^{-s}(r^{-1}\Omega)^{p'}|\phi|^2)\\
+\frac{1}{4}\left[2p'(r-M)+2(- s-2p')(r-2M+r^{-1}e^2)\right] \ell(\ell+1)r^{-s-4}(r^{-1}\Omega)^{p'-2}|\phi|^2.
\end{multline*}
Combining the above estimates and integrating over $\mathbb{S}^2$, we therefore obtain:
 \begin{multline}
  \label{eq:degelliptic3}
\int_{\mathbb{S}^2}\left[\left(3-\frac{p'}{2}\right)(r-M)+\left(p'+\frac{s}{2}\right)r\Omega^2\right]r^{-s}(r^{-1}\Omega)^{p'}|X\phi|^2\\
+\frac{1}{2}\left[(-s-p')(r-M)+(2p'+s)(M-r^{-1}Q^2)\right]r^{-s-4}(r^{-1}\Omega)^{p'-2}|\slashed{\nabla}_{\mathbb{S}^2}\phi|^2\,d\sigma\\
= X\left[\int_{\mathbb{S}^2 }\frac{1}{2}r^{-s}(r^{-1}\Omega)^{p'}(\Omega^2r^2|X\phi|^2-|\slashed{\nabla}_{\mathbb{S}^2}\phi|^2)\,d\sigma \right]\\
-\int_{\mathbb{S}^2}r^{-s}(r^{-1}\Omega)^{p'}\textnormal{Re}\,\left(\overline{X\phi}\cdot \left[-iqr \frac{d\mathbbm{h}}{dr}+q^2  \mathbbm{h}\widetilde{\mathbbm{h}}+3i q (1-\mathbbm{h})\right]\phi\right)\\
-r^{-s}(r^{-1}\Omega)^{p'}\textnormal{Re}\, \left( \overline{X\phi}\cdot r^2\tilde{G}[T\psi]\right)\,d\sigma.
\end{multline}
The terms on the very LHS are non-negative definite if $p'>0$, $s\leq 0$ and $p'<|s|<2p'$ and $p'< 6$.
By Young's inequality, we can estimate:
\begin{multline*}
\left|r^{-s}(r^{-1}\Omega)^{p'}\textnormal{Re}\,\left(\overline{X\phi}\cdot \left[-iqr\frac{d\mathbbm{h}}{dr}+q^2  \mathbbm{h}\widetilde{\mathbbm{h}}+3i q (1-\mathbbm{h})\right]\phi\right)\right|\leq \delta r^{-s}(r^{-1}\Omega)^{p'} (r-M)|X\phi|^2\\
+\frac{C q^2}{4\delta} r^{-s}(r^{-1}\Omega)^{p'} (r-M)^{-1}|\phi|^2
\end{multline*}

Note that
\begin{multline*}
	\int_{\mathbb{S}^2}(r-M)r^{-s-4}(r^{-1}\Omega)^{p'-2}|\slashed{\nabla}_{\mathbb{S}^2}\phi|^2\,d\sigma\\
	\geq L_0(L_0+1)\int_{\mathbb{S}^2}\frac{(r-M)^2}{(r-M)^2-(M^2-Q^2)}(r-M)^{-1}r^{-s}(r^{-1}\Omega)^{p'}|\phi|^2\,d\sigma\\
	\geq L_0(L_0+1)\int_{\mathbb{S}^2}r^{-s}(r^{-1}\Omega)^{p'} (r-M)^{-1}|\phi|^2\,d\sigma.
\end{multline*}

We apply Young's inequality again to estimate:
\begin{equation*}
\left|r^{-s}(r^{-1}\Omega)^{p'}\textnormal{Re}\, \left( \overline{X\phi}\cdot r^2\tilde{G}[T\psi]\right)\right|\lesssim  \delta r^{-s}(r^{-1}\Omega)^{p'} (r-M)|X\phi|^2+ \frac{ 1}{4\delta} r^{-s}(r^{-1}\Omega)^{p'}r^2 (r-M)^{-1}|r\tilde{G}[T\phi]|^2.
\end{equation*}
Finally, we integrate \eqref{eq:degelliptic3} in $r$ and observe that the boundary terms vanish by the boundary assumptions in the proposition and we take $L_0(L_0+1)\geq Cq^2 \delta^{-1}$ to obtain:
\begin{multline}
\label{eq:ellipticpart1}
\int_1^{\infty}\int_{\mathbb{S}^2}\left[\left(3-\frac{p'}{2}-2\delta\right)(r-M)+\left(p'+\frac{s}{2}\right)r\Omega^2\right]r^{-s}(r^{-1}\Omega)^{p'}|X\phi|^2\\
+\frac{1}{4}\left[(-s-p')(r-M)+(2p'+s)(M-r^{-1}Q^2)\right]r^{-s-4}(r^{-1}\Omega)^{p'-2}|\slashed{\nabla}_{\mathbb{S}^2}\phi|^2\,d\sigma dr\\
\leq C\int_1^{\infty}\int_{\mathbb{S}^2}r^{-s}(r^{-1}\Omega)^{p'}r^2 (r-M)^{-1}|r\tilde{G}[T\phi]|^2\,d\sigma dr\\
\leq C\int_1^{\infty}\int_{\mathbb{S}^2}r^{-s}(r^{-1}\Omega)^{p'-1} (|XT\psi|^2+r^{-4}|T^2\psi|^2+r^{-6}|T\psi|^2)\,d\sigma dr.
\end{multline}
Now \eqref{eq:ellipticenergy1} follows by applying \eqref{eq:ellipticpart1} with the choices $p'=3-p$ and $s= 1-p'-p=-2$, which implies that $1<p<3$.

In the case $|Q|=M$, \eqref{eq:ellipticenergy2} simply follows by repeating the above argument with $T$ replaced by $K$, $q$ replaced by $-q$ and $r$ replaced by $s_++1$.

\label{cor:elliptichighfreq}
Let $L_0,N\in \mathbb{N}_0$. Let $\tau\geq 0$ and let $\phi$ be a solution to \eqref{eq:CSF} with $G\equiv 0$.

Let $1<p<3$. Then, for suitably large $L_0>0$ depending on $q$ and $p$, there exists a constant $C=C(p,q,L_0,N)>0$ such that for all $\tau\geq 0$:
\begin{align}
\label{eq:ellipticenergy1ho}
\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau}} \mathcal{E}_{p-2}[\mathbf{Z}^{\gamma}\psi_{\geq L_0}]\,d\sigma dr\leq &\: C\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau}} \mathcal{E}_{p}[\mathbf{Z}^{\gamma}T\psi_{\geq L_0}]\,d\sigma dr, \\
\label{eq:ellipticenergy2ho}
\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau}} \mathcal{E}_{p-2}[\mathbf{Z}^{\gamma}\psi_{\geq L_0}]\,d\sigma dr\leq &\: C\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau}} \mathcal{E}_{p}[\mathbf{Z}^{\gamma}K\psi_{\geq L_0}]\,d\sigma dr\quad \textnormal{if $|Q|=M$}.
\end{align}

Let $r>1$, $\delta>0$ and $N\in \mathbb{N}_0$. Then
\begin{equation*}
\widehat{\psi}^{(1)}|_{\Sigma_0}(r,\cdot)=\sum_{\ell\in \mathbb{N}_0} \widehat{\psi}^{(1)}_{\ell}(r,\cdot)
\end{equation*}
is well-defined as an element of the Sobolev space $H^N(\mathbb{S}^2)$, provided
\begin{equation*}
\int_{\Sigma_{0}}\mathcal{E}_{2}[\psi]+ \mathcal{E}_{2}[\slashed{\nabla}_{\mathbb{S}^2}^{N}\psi]\,d\sigma dr<\infty.
\end{equation*}

We first recall that
\begin{equation*}
\widehat{\psi}^{(1)}_{\ell}=-\frac{1}{iq}\left( K^{-1}\widehat{\psi}_{\ell}-T^{-1}\widehat{\psi}_{\ell}\right).
\end{equation*}
Hence, we can apply \eqref{eq:ellipticenergy1ho} and \eqref{eq:ellipticenergy2ho} with $\tau=0$, $\gamma_1=N$, $\gamma_2=\gamma_3=0$ and $p=2$ to conclude that for all $\ell\geq L$:
\begin{equation*}
\int_{\Sigma_{0}} \mathcal{E}_{0}[\slashed{\nabla}_{\mathbb{S}^2}^{k}\widehat{\psi}^{(1)}_{\ell}]\,d\sigma dr\leq 2 q^{-2}\int_{\Sigma_{0}} \mathcal{E}_{0}[\slashed{\nabla}_{\mathbb{S}^2}^{k}T^{-1}\widehat{\psi}_{\ell}]+\mathcal{E}_{0}[\slashed{\nabla}_{\mathbb{S}^2}^{k}K^{-1}\widehat{\psi}_{\ell}]\,d\sigma dr\\
\leq C \int_{\Sigma_{0}} \mathcal{E}_{2}[\slashed{\nabla}_{\mathbb{S}^2}^{k}\widehat{\psi}_{\ell}]\,d\sigma dr,
\end{equation*}
where $C>0$ is uniform in $\ell$. 

By the fundamental theorem of calculus in the $r$-direction and a Poincar\'e inequality on $\mathbb{S}^2$, it then follows that for all $r>1$:
\begin{equation*}
||\widehat{\psi}^{(1)}_{\ell}||^2_{H^N(\mathbb{S}^2)}\leq C  \int_{\Sigma_{0}} \mathcal{E}_{0}[\slashed{\nabla}_{\mathbb{S}^2}^{N}\widehat{\psi}_{\ell}]+ \mathcal{E}_{0}[\slashed{\nabla}_{\mathbb{S}^2}^{N}\widehat{\psi}_{\ell}]\,d\sigma dr.
\end{equation*}
Convergence of the sum over $\ell$ then follows by showing that the sums $\sum_{\ell=L}^{M} \widehat{\psi}^{(1)}_{\ell}(r,\cdot)$ are Cauchy sequences in $M$, which in turn follows from the above uniform estimate and the convergence of the sum $\sum_{\ell\in \mathbb{N}_0} \int_{\Sigma_{0}} \mathcal{E}_{0}[\slashed{\nabla}_{\mathbb{S}^2}^{N}\widehat{\psi}_{\ell}]+ \mathcal{E}_{0}[\slashed{\nabla}_{\mathbb{S}^2}^{N}\widehat{\psi}_{\ell}]\,d\sigma dr$, which we assumed.

\label{prop:boundedangelliptic}
Let $N,L_0\in \mathbb{N}_0$. Let $\tau\geq 0$ and let $\phi$ be a solution to \eqref{eq:CSF}. Let $2-\textnormal{Re}\, \sqrt{1-4q^2}<p<3$ and $\epsilon>0$. Then there exists a constant $C=C(p,q,L_0,\epsilon)>0$ such that for all $\tau\geq 0$:
\begin{align}
\label{eq:ellipticenergy1boundl}
\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau}} \mathcal{E}_{p-2-\epsilon}[\mathbf{Z}^{\gamma}\widehat{\psi}_{\leq L_0 -1}]\,d\sigma dr\leq &\: C\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau}}\mathcal{E}_{p}[\mathbf{Z}^{\gamma}T\widehat{\psi}_{\leq L_0 -1}]+(r^{-1}\Omega)^{-p+2}|\mathbf{Z}^{\gamma}(G_{\widehat{A}})_{\leq L_0-1}|^2\,d\sigma dr, \\
\label{eq:ellipticenergy2boundl}
\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau}} \mathcal{E}_{p-2-\epsilon}[\mathbf{Z}^{\gamma}\widehat{\psi}_{\leq L_0 -1}]\,d\sigma dr\leq &\: C\sum_{|\gamma|\leq N}\int_{\Sigma_{\tau}} \mathcal{E}_{p}[\mathbf{Z}^{\gamma}K\widehat{\psi}_{\leq L_0 -1}]+(r^{-1}\Omega)^{-p+2}|\mathbf{Z}^{\gamma}(G_{\widehat{A}})_{\leq L_0-1}|^2\,d\sigma dr,
\end{align}
where \eqref{eq:ellipticenergy2boundl} only holds for $|Q|=M$.

Suppose first that $N=0$. We apply the estimates in the proof of Proposition \ref{prop:timeinvffixedmodeconstr} with $T^{-1}(\psi_{\ell m}-\Psi^{\infty}_{\ell m})|_{\Sigma_0}$ replaced by $\psi|_{\Sigma_{\tau}}$ and with $\delta=3-p$ to obtain in the case $\beta_{\ell}\neq 0$:
\begin{align*}
|\widehat{\psi}_{\ell}|^2(\tau, r)\leq &\: (r^{-1}\Omega)^{p-3} \int_{\Sigma_{\tau}} \mathcal{E}_{p}[T\widehat{\psi}_{\leq L-1}]+(r'^{-1}\Omega )^{2-p+2}|(G_{\widehat{A}})_{\leq L-1}|^2\,d\sigma dr',\\
|X\widehat{\psi}_{\ell}|^2(\tau, r)\leq &\:\Omega^{p-6}(r-1)r^{-p} \int_{\Sigma_{\tau}} \mathcal{E}_{p}[T\widehat{\psi}_{\leq L-1}]+(r'^{-1}\Omega )^{2-p+2}|(G_{\widehat{A}})_{\leq L-1}|^2\,d\sigma dr'.
\end{align*}
The condition $0<\delta<1+\textnormal{Re}\, \beta_{\ell}$ from the proof of Proposition \ref{prop:timeinvffixedmodeconstr} then implies that $2-\textnormal{Re}\, \beta_{\ell}<p<3$.

In the $\beta_{\ell}=0$ case, we see an additional logarithmic term inside the integrand on the RHS, due to the estimate $|\mathfrak{w}_{\ell}(r)|^2\leq (\log(1+r))^2 r$ in this case.

The estimate \eqref{eq:ellipticenergy1boundl} then follows by integrating  
\begin{equation*}
(r^{-1}\Omega)^{-(p'-2)}r^{-2}|\widehat{\psi}_{\ell}|^2+(r^{-1}\Omega)^{-(p'-2)}\Omega^2|X\widehat{\psi}_{\ell}|^2
\end{equation*}
and taking $p'<p$ to ensure convergence of the integrals. The derivation of \eqref{eq:ellipticenergy2boundl} proceeds entirely analogously, with the roles of $r-1$ and $(r-1)^{-1}$ reversed, applying Corollary \ref{cor:timeinvffixedmodeconstrhor} instead of Proposition \ref{prop:timeinvffixedmodeconstr}.

The case $N= 1$ then follows by applying the elliptic estimates in Proposition \ref{prop:ellipticesthighfreq} and using \eqref{eq:ellipticenergy1boundl} and \eqref{eq:ellipticenergy1boundl} with $N=0$ to control the lower-order orders, instead of the assumption $\ell\geq L_0$. The general $N\geq 1$ case can similarly be estimated inductively.

\label{prop:energydecayptieminv}
Let $N_1\in \mathbb{N}_0$, $N_2\in \mathbb{N}_0$. Let $1< p<2$. For all $\nu>0$ and $\epsilon>0$ suitably small, there exists a constant $C=C(\nu,\epsilon, N_1,N_2,p)>0$ such that:
\begin{multline}
\label{eq:energydecayptieminv}
(1+\tau)^{3-p+2N_1-2\epsilon-\nu}\sum_{|\gamma|\leq N_2}\int_{\Sigma_{\tau}}\mathcal{E}_{p-3\epsilon}[\mathbf{Z}^{\gamma}(TK)^{N_1}\widehat{\psi}]\,d\sigma dr \\
\leq C\sum_{m\leq N_1+1}\sum_{|\gamma|+m\leq N_1+N_2+1}\sum_{j\leq 2(N_1+1)}\int_{\Sigma_{0}} \mathcal{E}_{3-\frac{\epsilon}{2}}[\mathbf{Z}^{\gamma}(TK)^mT^j\widehat{\psi}]\,d\sigma dr+C(|\mathfrak{I}[\psi]|^2+|\mathfrak{H}[\psi]|^2)\\
=: CE_{N_1,N_2,\epsilon}[\psi]
\end{multline}
and additionally,
\begin{equation}
\label{eq:energydecayptieminvmin1}
(1+\tau)^{-2\epsilon}\sum_{|\gamma|\leq N_2}\int_{\Sigma_{\tau}} \mathcal{E}_{1-5\epsilon}[\mathbf{Z}^{\gamma}T^{-1}\widehat{\psi}]\,d\sigma dr\leq CE_{-1,N_2,\epsilon}[\psi].
\end{equation}
Furthermore, for $N_1\in \mathbb{N}_0\cup\{-1\}$, $N_2\in \mathbb{N}_0$:
\begin{align}
\label{eq:energydecayptieminvfaster}
(1+\tau)^{3+\textnormal{Re}\,\sqrt{1-4q^2}+2N_1-8\epsilon-\nu}\int_{\Sigma_{\tau}}\sum_{|\gamma|\leq N_2}\mathcal{E}_{\epsilon-\textnormal{Re}\,\sqrt{1-4q^2}}[\mathbf{Z}^{\gamma}(TK)^{N_1}\widehat{\psi}]\,d\sigma dr\leq &\:C E_{N_1+1,N_2+1,\epsilon}[\psi],\\
\label{eq:energydecayptieminvfasterDT}
(1+\tau)^{3+\textnormal{Re}\,\sqrt{1-4q^2}+2N_1-8\epsilon-\nu}\int_{\Sigma_{\tau}}\sum_{|\gamma|\leq N_2}\mathcal{E}_{2+\epsilon-\textnormal{Re}\,\sqrt{1-4q^2}}[D_T\mathbf{Z}^{\gamma}(TK)^{N_1}\widehat{\psi}]\,d\sigma dr\leq &\: C E_{N_1+1,N_2+2,\epsilon}[\psi].
\end{align}

\label{prop:tails}
Let $N_1\in \mathbb{N}_0\cup\{-1\}$, $N_2\in \mathbb{N}_0$. Let $l\in\{0,1\}$. For arbitrarily small $\nu>0$ and $\epsilon>0$, there exists a constant $C=C(\nu,\epsilon, N_1,N_2,p)>0$ such that:
\begin{multline}
\label{eq:mainpointwisedecay}
\sum_{|\gamma|\leq N_2}||D_T^l\mathbf{Z}^{\gamma}(TK)^{N_1}(\psi-\Psi)||_{L^{\infty}}\\
\leq C  \sum_{k\leq 2}\sqrt{E_{N_1+1,N_2+1+l,\epsilon}[\slashed{\nabla}_{\mathbb{S}^2}^k\psi]}(\tau+1)^{-1+\frac{1}{2}\nu+4\epsilon-N_1-\frac{l}{2}}(r^{-1}\Omega\tau+1)^{-\frac{1}{2}-\frac{1}{2}\textnormal{Re}\, \beta_{0}}.
\end{multline}
If $|Q|<M$, we moreover have for all $l\in \mathbb{N}_0$:
\begin{multline}
\label{eq:mainpointwisedecaysubext}
\sum_{|\gamma|\leq N_2}||X^l\mathbf{Z}^{\gamma}(TK)^{N_1}(\psi-\Psi^{\infty})||_{L^{\infty}}\\
\leq C \kappa_+^{-\frac{1}{2}} \sum_{k\leq 2}\sqrt{E_{N_1+1,N_2+l+1,\epsilon}[\slashed{\nabla}_{\mathbb{S}^2}^k\psi]}(\tau+1)^{-1+\frac{1}{2}\nu+4\epsilon-N_1}r ^{\frac{1}{2}+\frac{1}{2}\textnormal{Re}\,\beta_0}(r^{-1}\tau+1)^{-\frac{1}{2}-\frac{1}{2}\textnormal{Re}\, \beta_{0}}\\
+Ce^{-c\kappa_+\tau}\sum_{|\gamma|\leq N_2}\sqrt{\int_{\Sigma_{0}\cap \{r\leq r_H\}}\mathcal{E}_2[\slashed{\nabla}_{\mathbb{S}^2}^kX^l\mathbf{Z}^{\gamma}(TK)^{N_1}\psi]\,d\sigma dr}.
\end{multline}

We will derive $L^{\infty}$-estimates for $\widehat{\psi}$ by using the energy estimates of Proposition \ref{prop:energydecayptieminv}.

	Consider first the region $\{r\geq r_H\}$ with $r_H>r_+$. Then we can estimate via the fundamental theorem of calculus:
	\begin{equation*}
	\int_{\mathbb{S}^2}r^{-1}|\widehat{\psi}|^2(\tau,r,\cdot),d\sigma\lesssim \int_{\Sigma\cap\{r\geq r_H\}}\mathcal{E}_{0}[\widehat{\psi}]\,d\sigma dr.
	\end{equation*}
	Furthermore, for all $r\geq r_H$, we have:
\begin{equation*}
		\int_{\mathbb{S}^2} |\widehat{\psi}|^2(\tau,r,\cdot),d\sigma\lesssim \int_{\Sigma_{\tau}\cap\{r\geq r_H\}}\mathcal{E}_{1+\delta}[\widehat{\psi}]\,d\sigma dr+\int_{\mathbb{S}^2}|\widehat{\psi}|^2(\tau,r_H,\cdot),d\sigma.
		\end{equation*}
From \eqref{eq:energydecayptieminv}, it then follows that for $r\geq r_+$ and arbitrarily small $\nu$:
\begin{equation*}
	\int_{\mathbb{S}^2}|\widehat{\psi}|^2(\tau,r,\cdot)\lesssim C(1+\tau)^{-2+\delta+5\epsilon+\nu}E_{0,0,\epsilon}[\psi].
\end{equation*}
We moreover that by the fundamental theorem of calculus:
\begin{equation*}
		\int_{\mathbb{S}^2}(r^{-1}\Omega)^{\textnormal{Re}\, \beta_0+1}|\widehat{\psi}|^2(\tau,r,\cdot),d\sigma\leq \int_{\Sigma_{\tau}}\mathcal{E}_{\epsilon-\textnormal{Re}\, \beta_0}[\widehat{\psi}]\,d\sigma dr.
	\end{equation*}
We then apply \eqref{eq:energydecayptieminvfaster} to conclude that:
\begin{equation}
\label{eq:auxpointwest}
	\int_{\mathbb{S}^2}(r^{-1}\Omega)^{\textnormal{Re}\, \beta_0+1}|\widehat{\psi}|^2(\tau,r,\cdot)\lesssim C(1+\tau)^{-3-\textnormal{Re}\, \beta_0+8\epsilon+\nu}E_{1,1,\epsilon}[\psi].
\end{equation}
To obtain an estimate for $D_T\psi$, we instead apply \eqref{eq:energydecayptieminvfasterDT}.
We combine the above estimates and apply a standard Sobolev inequality on $\mathbb{S}^2$ to conclude \eqref{eq:mainpointwisedecay} with $N_1=N_2=0$. The general $N_1$ and $N_2$ cases follows entirely analogously.

In the $|Q|<M$ case, we can improve the above estimates by removing the factor $\Omega$ in \eqref{eq:auxpointwest} and by making use of the red-shift effect.

From a standard red-shift energy estimate in $\{r\leq r_H\}$ with $r_H-r_+>0$ suitably small, see for example \cite{lecturesMD}[\S 7] for a general analysis and \cite{gaj22a}[Proposition 6.7], it follows that there exists a numerical constant $c>0$, such that:
\begin{multline*}
	c \kappa_+ \int_{\tau}^{\infty}\int_{\Sigma_{\tau'}\cap \{r\leq r_H\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma drd\tau'-\int_{\Sigma_{\tau}\cap \{r\leq r_H\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma dr\\
	\leq C \int_{\tau}^{\infty}\int_{\Sigma_{\tau'}\cap\{r_H\leq r\leq r_H+\frac{1}{2}(r_H-r_+)\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma drd\tau'+C\int_{\tau}^{\infty}\int_{\Sigma_{\tau'}\cap \{r\leq r_H+\frac{1}{2}(r_H-r_+)\}}|G_{\widehat{A}}[\widehat{\psi}]|^2\,d\sigma drd\tau'.
\end{multline*}
Let $f(\tau):=\int_{\Sigma_{\tau}\cap \{r\leq r_H\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma dr$, then this implies that:
\begin{multline*}
	\frac{d}{d\tau}\left[e^{c\kappa_+\tau}f(\tau)\right]\leq C e^{c\kappa_+\tau}\int_{\Sigma_{\tau'}\cap\{r_H\leq r\leq r_H+\frac{1}{2}(r_H-r_+)\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma drd\tau'\\
+Ce^{c\kappa_+\tau}\int_{\Sigma_{\tau}\cap \{r\leq r_H+\frac{1}{2}(r_H-r_+)\}}|G_{\widehat{A}}[[\Psi]|^2\,d\sigma drd\tau'
\end{multline*}
Hence,
\begin{multline*}
	f(\tau)\leq Ce^{-c\kappa_+\tau}\int_{\Sigma_{0}\cap \{r\leq r_H\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma dr+C \kappa_+^{-1}\int_{\Sigma_{\tau'}\cap\{r_H\leq r\leq r_H+\frac{1}{2}(r_H-r_+)\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma drd\tau'\\
	+C\kappa_+^{-1}\int_{\Sigma_{\tau}\cap \{r\leq r_H+\frac{1}{2}(r_H-r_+)\}}|G_{\widehat{A}}[[\Psi]|^2\,d\sigma drd\tau'.
\end{multline*}
By \eqref{eq:energydecayptieminvfaster}, we therefore have that:
\begin{equation*}
	\int_{\Sigma_{\tau}\cap \{r\leq r_H\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma dr\leq C\kappa_+^{-1}(1+\tau)^{-3-\textnormal{Re}\, \beta_0+\epsilon+\nu}E_{1,1,\epsilon}[\psi]+Ce^{-c\kappa_+\tau}\int_{\Sigma_{0}\cap \{r\leq r_H\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma dr.
\end{equation*}
Then we can apply the fundamental theorem of calculus in $\{r\leq r_H\}$ to conclude that:
\begin{equation*}
	\int_{\mathbb{S}^2}r^{-\textnormal{Re}\, \beta_0-1+\epsilon}|\widehat{\psi}|^2(\tau,r,\cdot)\lesssim C\kappa_+^{-1}(1+\tau)^{-3-\textnormal{Re}\, \beta_0+\epsilon+\nu}E_{1,1,\epsilon}[\psi]+Ce^{-c\kappa_+\tau}\int_{\Sigma_{0}\cap \{r\leq r_H\}}\mathcal{E}_2[\widehat{\psi}]\,d\sigma dr.
\end{equation*}
 The above improvement applies also after commuting the above estimates with $\mathbf{Z}^{\gamma}(TK)^{N_1}$ as well as $X^{l}$ and we conclude \eqref{eq:mainpointwisedecaysubext} after applying a standard Sobolev inequality on $\mathbb{S}^2$.

\label{prop:transinstb}
	Let $\psi$ be a solution to \eqref{eq:CSF} with $G_A=0$ and $A=-\frac{Q}{r}d\tau$ and $\kappa_+>0$. Let $k\in \mathbb{N}_0$. Fix the initial data for $\psi$ independently of $\kappa_+$. Let $\psi_M$ be a solution arising from the same data, but with $\kappa_+=0$. Then, there exists  suitably small $0<\delta_1<\delta_2$, depending only on the initial data for $\psi$ and on $k$, such that for $r_+\kappa_+\leq \delta_1$ and $\ell(\ell+1)<q^2$:
	\begin{align*}
		\sup_{\delta_1 \kappa_+^{-1}\leq \tau\leq \delta_2 \kappa_+^{-1}}(\tau+1)^{-\frac{1}{2}-k+\frac{1}{2}\textnormal{Re}\,\beta_0}|X^{k+1}\psi_{\ell m}|(\tau,r_+)\geq&\:  \frac{|\mathfrak{c}_k|}{2}|\mathfrak{H}_{\ell m}[\psi_M]|\quad &(\beta_{0}\neq 0),\\
		\sup_{\delta_1 \kappa_+^{-1}\leq \tau\leq \delta_2 \kappa_+^{-1}}\log(1+\tau)\tau^{-\frac{1}{2}-k}|X^{k+1}\psi_{\ell m}|(\tau,r_+)\geq&\:  \frac{|\mathfrak{c}_k|}{2}|\mathfrak{H}_{\ell m}[\psi_M]|\quad &(\beta_{0}= 0).
	\end{align*}

Fix $Q$ and let $\psi^M$ denote a solution to \eqref{eq:CSF} with $G_A=0$ and $M=|Q|$, such that $(\psi^M|_{\Sigma_0},\partial_{\tau}\psi^M|_{\Sigma_0})=(\psi|_{\Sigma_0},\partial_{\tau}\psi|_{\Sigma_0})$. Then
\begin{multline*}
	(g^{-1}_{M,M})^{\mu\nu}(^{\widehat{A}}D)_{\mu}(^{\widehat{A}}D)_{\nu}(r^{-1}(\psi-\psi^M))=(r_--r_+)X((r-r_+)r^{-2}X\psi)+2(Q^2-M^2)r^{-4}\psi=:F_{M,Q}.
\end{multline*}
Then we can estimate: $|F_{M,Q}|^2\leq \kappa_+^2r^{-6}\sum_{|\gamma|=1}\mathcal{E}_2[\mathbf{Z}^{\gamma}\psi]$, so by standard local energy estimates, we obtain:
\begin{multline*}
	\sup_{\tau'\in [0,\tau]}\int_{\Sigma_{\tau'}}\mathcal{E}_2[\psi-\psi^M]\,d\sigma dr\leq C\kappa_+\sum_{|\gamma|=1}\int_0^{\tau}\int_{\Sigma_{\tau'}}\sqrt{\mathcal{E}_2[\psi-\psi^M]}\sqrt{\mathcal{E}_2[\mathbf{Z}	^{\gamma}\psi]}\,d\sigma drd\tau'\\
	\leq C\kappa_+ \sqrt{\int_0^{\tau}\int_{\Sigma_{\tau'}}\mathcal{E}_2[\psi-\psi^M]\,d\sigma drd\tau'}\sqrt{\sum_{|\gamma|=1}\int_0^{\tau}\int_{\Sigma_{\tau'}}\mathcal{E}_2[\mathbf{Z}	^{\gamma}\psi]\,d\sigma drd\tau'}\\
	\leq \frac{1}{2}\sup_{\tau'\in [0,\tau]}\int_{\Sigma_{\tau'}}\mathcal{E}_2[\psi-\psi^M]\,d\sigma dr+\frac{C^2}{2}(\kappa_+\tau)^2\sum_{|\gamma|=1}\sup_{\tau'\in [0,\tau]}\int_{\Sigma_{\tau'}}\mathcal{E}_2[\mathbf{Z}	^{\gamma}\psi]\,d\sigma dr.
\end{multline*}
By applying Theorem \ref{thm:mainthmenergy}, we therefore have that for $\epsilon>0$ arbitrarily small:
\begin{equation*}
	\int_{\Sigma_{\tau}}\mathcal{E}_2[\psi-\psi^M]\,d\sigma dr\leq C(\kappa_+\tau)^{2} E_{0,3,\epsilon}[\psi](1+\tau)^{-2\textnormal{Re}\, \beta_0}.
\end{equation*}

 We now apply the fundamental theorem of calculus in the $r$-direction together with Theorem \ref{thm:mainthmenergy} to estimate:
 \begin{multline*}
 	\int_{\mathbb{S}^2}|\psi-\psi_M|^2(\tau,r_+,\cdot)\,d\sigma\leq C\sqrt{\int_{\Sigma_{\tau}\cap\{r\leq r_H\}}\mathcal{E}_2[\psi-\psi_M]\,d\sigma dr}\sqrt{\int_{\Sigma_{\tau}\cap\{r\leq r_I\}}\mathcal{E}_0[\psi-\psi_M]\,d\sigma dr}\\
 	\leq C(\kappa_+\tau)E_{1,3,\epsilon}[\psi](1+\tau)^{-1-\textnormal{Re}\,\beta_0}.	
 \end{multline*}
In particular, we obtain:
 \begin{equation*}
 |(\psi_{\ell m}-(\psi_M)_{\ell m})(\tau,r_+)|\\
 	\leq C(\kappa_+\tau)^{\frac{1}{2}}\sqrt{\sum_{k=0}^2E_{1,3,\epsilon}[\slashed{\nabla}_{\mathbb{S}^2}^k\psi]}(1+\tau)^{-\frac{1}{2}(1+\textnormal{Re}\,\beta_0)}.
 \end{equation*}
Now let $k=0$. From \eqref{eq:decayr2Xhpsi}, it follows in particular that:
	\begin{equation*}
		|(r^2X((\psi_M)_{\ell m}-\Psi^+_{\ell m}))(\tau,r_+)|\leq C\sqrt{E_{1,1,\epsilon}[\psi]}(\tau+1)^{\frac{1}{2}\nu+4\epsilon}.
	\end{equation*}

We apply \eqref{eq:maineqradfieldconfhor} with $\widetilde{\mathbbm{h}}=0$ in $r\leq r_H$ to obtain:
\begin{equation*}
		2T(r^2X(\psi-\psi_M))(\tau,r_+,\cdot)=\kappa_+r^2X\psi(\tau,r_+)+(\slashed{\Delta}_{\mathbb{S}^2}-iq) (\psi-\psi_M).
	\end{equation*}
We can rewrite the above as follows:
\begin{equation*}
		2T(e^{\kappa_+ \tau}r^2X(\psi-\psi_M))(\tau,r_+,\cdot)=\kappa_+e^{\kappa_+ \tau}r^2X\psi_M(\tau,r_+)+e^{\kappa_+ \tau}(\slashed{\Delta}_{\mathbb{S}^2}-iq) (\psi-\psi_M).
	\end{equation*}
Integrating the above therefore gives for $\kappa_+\tau<1$:
\begin{equation*}
		2|r^2X(\psi-\psi_M)_{\ell m}|(\tau,r_+,\cdot)\leq C(\kappa_+ \tau)^{\frac{1}{2}}\sqrt{E_{1,3,\epsilon}[\psi]}(1+\tau)^{\frac{1}{2}(1-\textnormal{Re}\,\beta_0)}
	\end{equation*}
and hence, we obtain:
\begin{equation*}
		2|r^2X(\psi-\Psi^+)_{\ell m}|(\tau,r_+,\cdot)\leq C(\kappa_+ \tau)^{\frac{1}{2}}\sqrt{E_{1,3,\epsilon}[\psi]}(1+\tau)^{\frac{1}{2}(1-\textnormal{Re}\,\beta_0)}+C\sqrt{E_{1,1,\epsilon}[\psi]}(1+\tau)^{\frac{1}{2}\nu+4\epsilon}
	\end{equation*}

	Now, let $\delta_2>0$ be suitably small, so that for $r_+ \delta_2^{-1}\leq \tau\leq \delta_2 \kappa_+^{-1}$:
	\begin{equation*}
		(1+\tau)^{-\frac{1}{2}+\frac{\textnormal{Re}\, \beta_0}{2}}|r^2X(\psi-\Psi^+)_{\ell m}|(\tau,r_+)\leq \frac{|\mathfrak{c}_0|}{4}|\mathfrak{H}_{\ell m}[\psi_M]|.
	\end{equation*}
	If $\beta_0\in [0,\infty)$, we have that
	\begin{equation*}
		(1+\tau)^{-\frac{1}{2}+\frac{\textnormal{Re}\, \beta_0}{2}}(1+\delta_{\beta_0 0}\log (1+\tau))|r^2X\Psi^+_{\ell m}|(\tau,r_+)\geq |\mathfrak{c}_0||\mathfrak{H}_{\ell m}[\psi_M]|,
	\end{equation*}
	so the stated estimates follow immediately.

	Suppose that $\beta_0\in i(0,\infty)$. Note that for $\sigma=\textnormal{Im}\, \beta_{\ell} \log(r_++\tau)$, we have by the mean value theorem that for $\delta_1<\delta_0$:
	\begin{multline*}
		\sup_{\delta_1 \kappa_+^{-1}\leq \tau \leq \delta_2 \kappa_+^{-1}}(r_++\tau)^{-1}|r^2X\Psi^+_{\ell m}|^2(\tau,r_+)\\
		\geq \frac{1}{\textnormal{Im}\, \beta_{\ell}}\frac{1}{\log(\frac{r_++\delta_2 \kappa_+^{-1}}{r_++\delta_1 \kappa_+^{-1}})}\int_{\textnormal{Im}\, \beta_{\ell}\log(r_++\delta_1 \kappa_+^{-1})}^{\textnormal{Im}\, \beta_{\ell}\log(r_++\delta_2 \kappa_+^{-1})}(r_++\tau(\sigma))^{-1}|r^2X\Psi^+_{\ell m}|^2(\tau(\sigma),r_+)\,d\sigma\\
		\geq \mathfrak{c}_0^2 |\mathfrak{H}_{\ell m}[\psi_M]|^2-C|\mathfrak{H}_{\ell m}[\psi_M]|^2\frac{1}{\textnormal{Im}\, \beta_{\ell}}\frac{1}{\log(1+\frac{\frac{\delta_2}{\delta_1}-1}{1 +\delta_1^{-1}\kappa_+ r_+})}\geq \frac{9}{16}\mathfrak{c}_0^2 |\mathfrak{H}_{\ell m}[\psi_M]|^2,
	\end{multline*}
	where we applied \eqref{eq:expvaluePsi0infest} to arrive at the second inequality above and we assumed that $\frac{\delta_2}{\delta_1}$ is suitably large and $\kappa_+\delta_1^{-1}\leq r_+^{-1}$ to arrive at the last inequality.

	We conclude that there exist $0<\delta_1<\delta_2$ suitably small with $\kappa_+\leq \delta_1r_+^{-1}$, such that:
	\begin{equation*}
		\sup_{\delta_1 \kappa_+^{-1}\leq \tau \leq \delta_2 \kappa_+^{-1}}(1+\tau)^{-\frac{1}{2}}|r^2X\psi_{\ell m}|(\tau,r_+)\geq \frac{|\mathfrak{c}_0|}{2}|\mathfrak{H}_{\ell m}[\psi_M]|.
	\end{equation*}
	To obtain the the desired estimates for $k'\geq 1$, we proceed by induction: we commute \eqref{eq:maineqradfieldconfhor} with $\partial_{\rho_+}^{k'}$ and then integrate in $\tau$, applying the estimates for $k\leq k'-1$.

\label{lm:solnminkhypg}
\begin{enumerate}[label=\emph{(\roman*)}]\mbox{}
	\item Let $s\in \mathbb{C}\setminus  \mathbb{Z}$. The function $(\tau+1)^{s}F(\varrho)Y_{\ell m}(\theta,\varphi)$ is a solution to \eqref{eq:CSFmink} with $A=\widehat{A}$ and $\mathbbm{h}=0$ that is smooth in $\varrho$ at $\varrho=0$ if and only if
	\begin{equation*}
		F(\varrho)= B\cdot  {}_2\mathbf{F}_1(a,b,c;-\varrho),
	\end{equation*}
	with ${}_2\mathbf{F}_1(a,b,c;\cdot)$ the regularized Gauss hypergeometric function, $B\in \mathbb{C}$ and
	\begin{align*}
		a=&\:\frac{1}{2}\pm \frac{\beta_{\ell}}{2}+iq,\\
		b=&\:\frac{1}{2}\mp \frac{\beta_{\ell}}{2}+iq,\\
		c=&\: s+1.
	\end{align*}
	In particular, we obtain the following simplifications for particular choices of $s$: let $a=\frac{1}{2}+ \frac{\beta_{\ell}}{2}+iq$, then
	\begin{align*}
		(\tau+1)^sF(\varrho)=&\:B(1+\tau)^{-\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq}(1+\varrho)^{-\frac{1}{2}-\frac{\beta_{\ell}}{2}-iq}\quad (s=b-1),\\
				(\tau+1)^sF(\varrho)=&\:B(1+\tau)^{-\frac{1}{2}+\frac{\beta_{\ell}}{2}+iq}(1+\varrho)^{-\frac{1}{2}+\frac{\beta_{\ell}}{2}-iq}\quad (s=a-1).
	\end{align*}
	\item Let $\beta_{\ell}=0$ and define
	\begin{equation*}
		H(\tau,\varrho):=(\tau+1)^{-\frac{1}{2}+iq}(1+\varrho)^{-\frac{1}{2}-iq}(\log(\varrho+1)+\log (\tau+1)).
	\end{equation*}
	Then $H(\tau,\varrho)Y_{\ell m}(\theta,\varphi)$ is a solution to \eqref{eq:CSFmink} with $A=\widehat{A}$ and $\mathbbm{h}=0$ that is smooth in $\varrho$ at $\varrho=0$.
	\end{enumerate}

Let $\psi$ be a solution to \eqref{eq:CSFmink} with $A=\widehat{A}$ and $\mathbbm{h}=0$ and with $\slashed{\Delta}_{\mathbb{S}^2}\psi=-\ell(\ell+1)\psi$. Then:
\begin{multline*}
	0=X^2\psi-2(T+iq r^{-1})X\psi+(iq-\ell(\ell+))r^{-2}\psi\\
	=4\varrho^3(\varrho+1)(\tau+1)^{-2}\mathfrak{X}^2\psi+4\varrho^2(\tau+1)^{-1}\mathfrak{T}\mathfrak{X}\psi+4\varrho^2(\tau+1)^{-2}(2(1+iq)\varrho+1)\mathfrak{X}\psi+(iq-\ell(\ell+1))4\varrho^2(\tau+1)^{-2}\psi.
\end{multline*}	
Equivalently,
\begin{equation}
\label{eq:CSFminkrhotau}
	0= \varrho(\varrho+1)\mathfrak{X}^2\psi+(\tau+1)\mathfrak{T}\mathfrak{X}\psi+(2(1+iq)\varrho+1)\mathfrak{X}\psi+(iq-\ell(\ell+1))\psi.
\end{equation}
Now let $\psi=(\tau+1)^s F(\varrho)$. Then $F$ satisfies the following ODE:
\begin{equation*}
	\varrho(\varrho+1)\frac{d^2F}{d\varrho^2}+((2+2iq)\varrho+1+s)\frac{dF}{d\varrho}+(iq-\ell(\ell+1))F=0.
\end{equation*}
By taking $z=-\varrho$ we obtain a hypergeometric equation:
\begin{equation*}
	z(1-z)\frac{d^2F}{dz^2}+(-(2+2iq)z+1+s)\frac{dF}{dz}-(iq-\ell(\ell+1))F=0.
\end{equation*}
The corresponding solutions that are smooth at $z=0$ for non-integer $c$ are multiples of regularized Gauss hypergeometric functions ${}_2\mathbf{F}_1(a,b,c;-\varrho)$ with
\begin{align*}
		a+b+1=&\:2+2iq,\\
		ab=&\:iq-\ell(\ell+1),\\
		c=&\: s+1,
	\end{align*}
see for example \cite{NIST:DLMF}[\S 15.10]. We can easily solve for $a$ and $b$ to obtain the expressions in the statement of the theorem.

The simplifications in the cases $s=a-1$ and $s=b-1$ follow from \cite{NIST:DLMF}[\S 15.4]. 


Finally, it can easily be verified that $H(\tau,\varrho)$ solves \eqref{eq:CSFminkrhotau}. Alternatively, we can take the $s$-derivative of $(\tau+1)^{s}{}_2\mathbf{F}_1(a,a,s+1;-\varrho)$ evaluate at $s=a-1$ and add a constant multiple of $(1+\tau)^{-\frac{1}{2}+iq}(1+\varrho)^{-\frac{1}{2}-iq}$ to obtain $H(\tau,\varrho)$. Indeed, $\frac{d}{ds}((\tau+1)^{s}{}_2\mathbf{F}_1(a,a,s+1;-\varrho))$ must be a solution since the equation \eqref{eq:CSFminkrhotau} does not depend on $s$, the corresponding difference quotient is a solution, and ${}_2\mathbf{F}_1(a,a,a;-\varrho)=\frac{1}{\Gamma(a)}(1+\varrho)^{-a}$.

\label{prop:hypgeomrealbeta}
	Let $\beta_{\ell}\in (0,1)$ and $\alpha_+,\alpha_-\in \mathbb{C}$. Let $\mathfrak{w}_{\ell}^0(r)=\alpha_+ r^{\frac{1}{2}+\frac{\beta_{\ell}}{2}+iq}+\alpha_-r^{\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq}$ and let $r\geq R$, so that $\mathfrak{w}_0(r)\neq 0$. Let $N_{\beta_{\ell}}\in \mathbb{N}_0$, such that $N_{\beta_{\ell}}\beta_{\ell}>1$. 



	Define
	\begin{equation}
