		\zeta=&\: -\frac{2^{\beta_{\ell}}\Gamma(-\beta_{\ell}+1)\Gamma(a)}{\Gamma(\beta_{\ell}+1) \Gamma(b)}\frac{\alpha_-}{\alpha_+}.
	\end{align*}
	Then $\Psi^{\infty}_0=(\Psi^{\infty}_0)_{\ell m}Y_{\ell m}$ is smooth with respect to the coordinate chart $(\tau,\varrho_{\infty},\theta,\varphi)$ (where $\varrho_{\infty}=\frac{1}{r}$) and it is a solution to \eqref{eq:CSFmink} with $A=\widehat{A}$ and $\mathbbm{h}=0$.

	Furthermore, $f(\tau,r):=(\mathfrak{w}^0_{\ell})^{-1}(r)(\Psi^{\infty}_0)_{\ell m}(\tau,r)$ satisfies: for all $k,l\leq N$
	\begin{align}
	\label{eq:divisionwimproveddec0}
		|(rX)^k ((\tau+1)T)^l f|\leq &\: C_N (\tau+1)^{-\frac{1}{2}-\frac{1}{2}\beta_{\ell}}(\tau+1+2r)^{-\frac{1}{2}-\frac{1}{2}\beta_{\ell}},\\
	\label{eq:divisionwimproveddec1}
		|(rX)^k ((\tau+1)T)^l Tf|\leq &\: C_N (\tau+1)^{-\frac{3}{2}-\frac{1}{2}\beta_{\ell}}(\tau+1+2r)^{-\frac{1}{2}-\frac{1}{2}\beta_{\ell}},\\
			\label{eq:divisionwimproveddec2}
		|(rX)^k ((\tau+1)T)^l Xf|\leq &\: C_N (\tau+1)^{-\frac{3}{2}-\frac{1}{2}\beta_{\ell}}(\tau+1+2r)^{-\frac{1}{2}-\frac{1}{2}\beta_{\ell}}.
