Note first of all that by Lemma 	\ref{lm:solnminkhypg} and linearity of \eqref{eq:CSFmink}, $\Psi^{\infty}_0$ is a solution to \eqref{eq:CSFmink} with $A=\widehat{A}$ and $\mathbbm{h}=0$ . Furthermore, $T^{m_1}(r^2X)^{m_2}\Psi^{\infty}_0$ is well-defined for all $m_1,m_2\in \mathbb{N}_0$.

Let $\varrho_0>0$ be arbitrarily large and suppose that $\varrho\leq \varrho_0$. Then \eqref{eq:divisionwimproveddec0} --\eqref{eq:divisionwimproveddec2} follow immediately, using that the decay rates of $(\Psi^{\infty}_0)_{\ell m}(\tau,r(\tau,\varrho))$ are preserved under commutation with $(\tau+1)\mathfrak{T}$ and $\varrho \partial_{\varrho}$.

Now suppose that $\varrho>\varrho_0$. The hypergeometric functions ${}_2\mathbf{F}_1(a,b,2-b-n\beta_{\ell};-\varrho)$ satisfy the following asymptotics when $\varrho\to \infty$ (combine example \cite{NIST:DLMF}[\S 15.8] with \cite{NIST:DLMF}[\S 15.2]): for $n\geq 1$:
\begin{multline}
\label{eq:hypgeomasymp}
	\frac{-\sin (\pi \beta_{\ell})}{\pi}{}_2\mathbf{F}_1(a,b,1-a+2iq-n\beta_{\ell};-\varrho)=\frac{\varrho^{-a}}{\Gamma(\beta_{\ell}+1)\Gamma(b)\Gamma(-(n+1)\beta_{\ell})}(1+O_{\infty}(\varrho^{-1}))\\
	-\frac{\varrho^{-b}}{\Gamma(-\beta_{\ell}+1)\Gamma(a)\Gamma(-n\beta_{\ell})}(1+O_{\infty}(\varrho^{-1}))
\end{multline}
On the other hand, we obtain for $n=0$:
\begin{multline}
\label{eq:hypgeomasymp2}
	\frac{-\sin (\pi \beta_{\ell})}{\pi}{}_2\mathbf{F}_1(a,b,1-a+2iq;-\varrho)=	\frac{-\sin (\pi \beta_{\ell})}{\pi}{}_2\mathbf{F}_1(a,b,b;-\varrho)=\frac{-\sin (\pi \beta_{\ell})}{\pi \Gamma(b)}(1+\varrho)^{-a}\\
=\frac{(1+\varrho)^{-a}}{\Gamma(b)\Gamma(\beta_{\ell}+1)\Gamma(-\beta_{\ell})},
	\end{multline}
	where we applied Euler's reflection formula to arrive at the last equality.

From the above, it follows that \eqref{eq:divisionwimproveddec0} and \eqref{eq:divisionwimproveddec1} hold, since decay rates are preserved under commutation with $(\tau+1)T$ and $\varrho \partial_{\varrho}$ and $T\mathfrak{w}_0^{-1}=0$.

In order to conclude \eqref{eq:divisionwimproveddec2}, we will need to choose the constant $\zeta$ appropriately, since $X\mathfrak{w}_0^{-1}\neq 0$.


Consider \eqref{eq:hypgeomasymp}. Note that we can rewrite the terms with a factor $\varrho^{-b}$ as follows:
\begin{multline*}
	- \frac{\varrho^{-b}(1+\tau)^{-a+2iq}}{\Gamma(-\beta_{\ell}+1)\Gamma(a)}\sum_{n=1}^{N_{\beta_{\ell}}}\zeta^n \frac{(1+\tau)^{-n\beta_{\ell}}}{\Gamma(-n\beta_{\ell})}\\
=- \zeta \frac{(2r)^{b}(1+\tau)^{-a+2iq}(1+\tau)^{-b}}{\Gamma(-\beta_{\ell}+1)\Gamma(a)}\sum_{m=0}^{N_{\beta_{\ell}}+1}\zeta^m \frac{(1+\tau)^{-(m+1)\beta_{\ell}}}{\Gamma(-(m+1)\beta_{\ell})}\\
= -\zeta\frac{\Gamma(\beta_{\ell}+1) \Gamma(b)}{\Gamma(-\beta_{\ell}+1)\Gamma(a)}(2r)^b \left[(1+\tau)^{-a}\sum_{m=0}^{N_{\beta_{\ell}}+1}\zeta^m \frac{(1+\tau)^{-a+2iq-m\beta_{\ell}}}{\Gamma(\beta_{\ell}+1) \Gamma(b)\Gamma(-(m+1)\beta_{\ell})}\right].
\end{multline*}
Hence, using that $N_{\beta_{\ell}} \beta_{\ell}>1$, we obtain:
\begin{multline*}
	2^{-a}\frac{-\sin (\pi \beta_{\ell})}{\pi}\sum_{n=0}^{N_{\beta_{\ell}}}\zeta^n(1+\tau)^{-a+2iq-n\beta_{\ell}}{}_2\mathbf{F}_1(a,b,1-a+2iq-n\beta_{\ell};-\varrho)\\
	=\left[r^a-\zeta\frac{\Gamma(\beta_{\ell}+1) \Gamma(b)}{2^{\beta}\Gamma(-\beta_{\ell}+1)\Gamma(a)}r^b\right]\cdot \left[\sum_{m=0}^{N_{\beta_{\ell}}}\zeta^m \frac{(1+\tau)^{-1-(m+1)\beta_{\ell}}}{\Gamma(\beta_{\ell}+1) \Gamma(b)\Gamma(-(m+1)\beta_{\ell})}\right]\\
	+(\tau+1)^{-\frac{1}{2}-\frac{\beta_{\ell}}{2}}O_{\infty}(\varrho^{-\frac{3}{2}-\frac{\beta_{\ell}}{2}}).
	\end{multline*}
Now choose $\zeta$ so that
\begin{equation*}
\zeta\frac{\Gamma(\beta_{\ell}+1) \Gamma(b)}{2^{\beta}\Gamma(-\beta_{\ell}+1)\Gamma(a)}=-\frac{\alpha_-}{\alpha+}.
\end{equation*}
Then
\begin{multline*}
	2^{-a}\alpha_+\frac{-\sin (\pi \beta_{\ell})}{\pi \beta_{\ell}}(\Psi^{\infty}_0)_{\ell m}(\tau,r)=\mathfrak{w}_0(r)\cdot \left[\sum_{m=0}^{N_{\beta_{\ell}}}\zeta^m \frac{(1+\tau)^{-1-(m+1)\beta_{\ell}}}{\Gamma(\beta_{\ell}+1) \Gamma(b)\Gamma(-(m+1)\beta_{\ell})}\right]\\
	+(\tau+1)^{-\frac{1}{2}-\frac{\beta_{\ell}}{2}}O_{\infty}\left(\left(\frac{\tau}{2r}\right)^{-\frac{3}{2}-\frac{\beta_{\ell}}{2}}\right).
	\end{multline*}
	Finally, we divide the above expression by $\mathfrak{w}_0$ and apply $X$ to conclude that \eqref{eq:divisionwimproveddec2} holds.

\label{lm:unifomestnhypgeom}
	Let $\beta \in i[0,\infty), q\in \mathbb{R}$ and $x\in (0,\infty)$. Define $F_x(\varrho;\beta):={}_2\mathbf{F}_1(\frac{1}{2}+ \frac{\beta}{2}+iq,\frac{1}{2}- \frac{\beta}{2}+iq,\frac{1}{2}-\frac{\beta}{2}+i(q+x);-\varrho)$. 
	\begin{enumerate}[label=\emph{(\roman*)}]
	\item Let $\varrho_0>0$. Then for all $N\in \mathbb{N}_0$, there exists a constant $C_{N,\varrho_0,q}>0$, such that for all $0\leq m\leq N$ :
\begin{equation}
\label{eq:boundedrhoFnestho}
\left|((\varrho\partial_{\varrho})^m \left(\Gamma\left(\frac{1}{2}-\frac{\beta}{2}+iq-ix\right)F_x(\varrho;x)-(1+\varrho)^{-a}\right)\right|\leq C_{q,\varrho_0, N} \varrho(1+\varrho)^{-\frac{3}{2}},
\end{equation}
with
\begin{equation}
\label{eq:boundedrhoFnesthoplus}
	\left|\frac{1}{e^{\frac{\pi}{2}x}|\Gamma(\frac{1}{2}-\frac{\beta}{2}+iq-ix)|}+1\right|\leq C_{q,\beta,N} (x+1)^{-2}e^{-\frac{\pi}{2}x}.
\end{equation}
\item Let $\varrho\geq \varrho_0$ and let $\epsilon>0$ be arbitrarily small. Then for $\varrho_0$ suitably small and for all $N\in \mathbb{N}_0$, there exists a constant $C_{N,q,\varrho_0,\epsilon}>0$, such that for all $0\leq m,l\leq N$ :
\begin{align}
\label{eq:largerhoFnestho1}
		\Bigg|(x\partial_{x})^l(\varrho\partial_{\varrho})^m&\left(\frac{\sin (\pi \textnormal{Im}\, \beta)}{\pi}F(\varrho;x)-\frac{\varrho^{-a}}{\Gamma(b)\Gamma(c_x-a)}+\frac{\varrho^{-b}}{\Gamma(a)\Gamma(c_x-b)}\right)\Bigg|\\  \nonumber
		\leq &\: C_{N,q, \varrho_0,\epsilon} \varrho^{-1} e^{(\frac{\pi}{2}+\epsilon) x}\quad(\beta\in i(0,\infty)),\\
		\label{eq:largerhoFnestho2}
		\Bigg|(x\partial_{x})^l(\varrho\partial_{\varrho})^m&\left(F(\varrho;x)-\frac{\varrho^{-a}}{\Gamma(a)\Gamma(c_x-a)}\left(\log \varrho+2\gamma_{\rm Euler}-\frac{\Gamma'(a)}{\Gamma(a)}-\frac{\Gamma'(c_x-a)}{\Gamma(c_x-a)}\right)\right)\Bigg|\\ \nonumber
		\leq &\: C_{N,q, \varrho_0,\epsilon} \varrho^{-1}\log \varrho e^{(\frac{\pi}{2}+\epsilon) x}\quad  (\beta=0).
