Let $c_x:=	\frac{1}{2}-\frac{\beta}{2}+iq-i x$, $a=\frac{1}{2}+ \frac{\beta}{2}+iq$ and $b=\frac{1}{2}- \frac{\beta}{2}+iq$. Note that $\textnormal{Re}\, a=\textnormal{Re}\, b=\textnormal{Re}\, c_x=\frac{1}{2}$. Note that $c_x-b=-ix$.

We can express:
\begin{multline*}
	F(\varrho;x)=(1+\varrho)^{-a}{}_2\mathbf{F}_1\left(a,c_x-b,c_x;\frac{\varrho}{1+\varrho}\right)\\
	=\frac{(1+\varrho)^{-a}}{\Gamma(c_x)}\left(1+\frac{\Gamma(c_x)}{\Gamma(a)\Gamma(c_x-b)}\sum_{k=1}^{\infty}\frac{\Gamma(a+k)\Gamma(c_x+k-b)}{\Gamma(c_x+k)\Gamma(k+1)}\left(\frac{\varrho}{1+\varrho}\right)^k\right),
\end{multline*}
see for example \cite{NIST:DLMF}[\S 15.8.1].

By the Stirling approximation formula, we can alternatively estimate for $z\in \mathbb{C}$, with $z=re^{i\theta}$, with $r> 0$ and $\theta=\arg(z)\in (-\pi+\epsilon_0,\pi-\epsilon_0)$ for some $\epsilon_0>0$:
\begin{multline*}
	\log \Gamma(z)=z\log z-z+\frac{1}{2}\log(2\pi z^{-1})+O_{\infty}(z^{-1})\\
	=\left[(\textnormal{Re}\, z) (\log r-1)-\theta \textnormal{Im}\, z+\frac{1}{2}\log (2\pi r^{-1})\right] +i(\textnormal{Im}\, z \log r+\theta \textnormal{Re}\, z-\frac{\theta}{2})+O_{\infty}(z^{-1})
\end{multline*}
Hence, for $z=c_x+k-b$, $\textnormal{Re}\, z= k$, $\textnormal{Im}\, z=-x$, $r=(k^2+x^2)^{\frac{1}{2}}$ and $\theta=-\arctan (x k^{-1}):=\theta_k$, so
\begin{multline*}
	\textnormal{Re}\, \log \Gamma(c_x+k-b)=\frac{k}{2} \left(\log (k^2+x^2)-2\right)+\theta_k x-\frac{1}{4}\log (4\pi^2 (k^2+x^2))+O_{\infty}((x^2+k^2)^{-\frac{1}{2}}).
\end{multline*}
On the other hand, for $z=c_k+k$, we have $\textnormal{Re}\, z=k+\frac{1}{2}$, $\textnormal{Im}\, z=-x+q-\frac{1}{2}\textnormal{Im}\, \beta$, $r=((k+\frac{1}{2})^2+(x+\frac{1}{2}\textnormal{Im}\, \beta-q)^2)^{\frac{1}{2}}$ and $\theta=-\arctan ((x+\frac{1}{2}\textnormal{Im}\, \beta-q) (k+\frac{1}{2})^{-1}):=\tilde{\theta}_k$, so
\begin{multline*}
	\textnormal{Re}\, \log \Gamma(c_x+k)=\frac{k+\frac{1}{2}}{2} \left(\log \left((k+\frac{1}{2})^2+(x+\frac{1}{2}\textnormal{Im}\, \beta-q)^2\right)-2\right)+\tilde{\theta}_k (x+\frac{1}{2}\textnormal{Im}\, \beta-q)\\
	-\frac{1}{4}\log (4\pi^2 ((k+\frac{1}{2})^2+(x+\frac{1}{2}\textnormal{Im}\, \beta-q)^2)+O_{\infty}((x^2+k^2)^{-\frac{1}{2}}).
\end{multline*}
We therefore obtain:
\begin{multline*}
\textnormal{Re}\, \log \Gamma(c_x+k-b)-\textnormal{Re}\, \log \Gamma(c_x-b)-\textnormal{Re}\, \log \Gamma(c_x+k)=\left(\theta_k-\tilde{\theta}_k+\frac{\pi}{2}\right) x+\frac{k}{2} \log (1+O((k^2+x^2)^{-\frac{1}{2}}))\\
	-\frac{1}{4}\log \left((x^{-2}k^2+1)(1+O((k^2+x^2)^{-\frac{1}{2}}))\right)+\frac{1}{4}\log \left(1+O((k^2+x^2)^{-\frac{1}{2}}\right)+O_{\infty}(1)\\
	=\left(\theta_k-\tilde{\theta}_k+\frac{\pi}{2}\right) x-\frac{1}{4}\log(x^{-2}k^2+1)+O_{\infty}(1)
\end{multline*}

Furthermore,
\begin{multline*}
	-\log \Gamma(c_x)=-\frac{1}{4} \left(\log \left(\frac{1}{4}+(x+\textnormal{Im}\, \beta-q)^2\right)-2\right)+ (x+\textnormal{Im}\, \beta-q)\arctan (4(x+\textnormal{Im}\, \beta-q))\\
	+\frac{1}{4}\log \left(4\pi^2 \left(\frac{1}{4}+(x+\textnormal{Im}\, \beta-q)^2\right)\right)-i\left(-(x+\textnormal{Im}\, \beta)\log x-\frac{1}{2}\arctan (4(x+\textnormal{Im}\, \beta-q))\right)\\
	+O_{\infty}(x^{-1}),
\end{multline*}
so
\begin{equation*}
	\frac{1}{\Gamma(c_x)}=-e^{\frac{1}{2}(\textnormal{Im}\, \beta-q-1)}e^{\frac{\pi}{2}x(1+O_{\infty}(x^{-2}))}e^{+i(x+\textnormal{Im}\, \beta)\log x}.
\end{equation*}


Finally, we can estimate as above the following $x$-independent factor:
\begin{equation*}
	\left|\frac{\Gamma(a+k)}{\Gamma(k+1)}\right|\lesssim e^{\frac{k}{2}\log \left(\frac{(k+1)^2+(\textnormal{Im}\, a)^2}{(k+1)^2}\right)}(k+1)^{-\frac{1}{2}}\lesssim (k+1)^{-\frac{1}{2}}.
\end{equation*}

Putting the above together, we obtain the following estimate, which is uniform in $k,n$:
\begin{equation*}
\left|\frac{\Gamma(c_x)}{\Gamma(a)\Gamma(c_x-b)}\frac{\Gamma(a+k)\Gamma(c_x+k-b)}{\Gamma(c_x+k)\Gamma(k+1)}\right|\leq C_{q} (k+1)^{-\frac{1}{2}}.
\end{equation*}
Hence, for $\varrho\leq \varrho_0$:
\begin{equation*}
	\left|\Gamma(c_x)F(\varrho;x)-(1+\varrho)^{-a}\right|\leq C_{q,\varrho_0}\varrho(1+\varrho)^{-\frac{1}{2}-1}.
\end{equation*}
It is straightforward to commute the above estimates with $(\varrho\partial_{\varrho})^m$, which introduces harmless polynomial factors in $k$, in order to conclude \eqref{eq:boundedrhoFnestho}.


Now consider the region $\varrho\geq \varrho_0$. First, consider the case $\beta\in i(0,\infty)$.

Then we instead apply \cite{NIST:DLMF}[\S 15.8.2] to express:
\begin{equation*}
	-\frac{\sin (\pi \textnormal{Im}\, \beta)}{\pi}F(\varrho;x)=\varrho^{-a}\frac{{}_2\mathbf{F}_1(a,a-c_x+1,a-b+1;-\varrho^{-1})}{\Gamma(b)\Gamma(c_x-a)}-\varrho^{-b}\frac{{}_2\mathbf{F}_1(b,b-c_x+1,b-a+1;-\varrho^{-1})}{\Gamma(a)\Gamma(c_x-b)}.
\end{equation*}
We can write:
\begin{multline*}
	\frac{{}_2\mathbf{F}_1(a,a-c_x+1,a-b+1;-\varrho^{-1})}{\Gamma(b)\Gamma(c_x-a)}=\frac{1}{\Gamma(b)\Gamma(c_x-a)\Gamma(a)\Gamma(a-c_x+1)}\sum_{k=0}^{\infty}\frac{\Gamma(a+k)\Gamma(a-c_x+1+k)}{\Gamma(a-b+1+k)\Gamma(k+1)}(-\varrho)^{-k}\\
	=\frac{-i \sinh(\pi (x+\textnormal{Im}\, \beta_{\ell}))}{\pi}\frac{1}{\Gamma(b)\Gamma(a)}\sum_{k=0}^{\infty}\frac{\Gamma(a+k)\Gamma(a-c_x+1+k)}{\Gamma(a-b+1+k)\Gamma(k+1)}(-\varrho)^{-k},
\end{multline*}
where we applied Euler's reflection formula to arrive at the last equality.

We apply Stirling's formula, as above, to obtain:
\begin{multline*}
	\left|\frac{\Gamma(a-c_x+1+k)}{\Gamma(a-b+1+k)}\right|\lesssim e^{\frac{1}{2}(k+\frac{1}{2})\log [\frac{(x+\textnormal{Im}\,\beta-q)^2+(k+1)^2}{(\textnormal{Im}\,\beta)^2+(k+1)^2}] }e^{-(x+\textnormal{Im}\,\beta-q)\arctan(\frac{x+\textnormal{Im}\,\beta-q}{k+1})}\\
	= e^{\frac{x}{2}\frac{k+\frac{1}{2}}{x}\log [\frac{(x+\textnormal{Im}\,\beta-q)^2+(k+1)^2}{(\textnormal{Im}\,\beta)^2+(k+1)^2}] }e^{-(x+\textnormal{Im}\,\beta-q)\arctan(\frac{x+\textnormal{Im}\,\beta-q}{k+1})}.
\end{multline*}
Suppose that $k+1\leq \delta x$ for $\delta>0$. Then using that for $x\leq \delta$, $x\log (1+x^{-1})\leq \delta \log(1+\delta^{-1})$, we obtain for $\delta$ suitably small:
\begin{equation*}
	\sinh(\pi (x+\textnormal{Im}\, \beta_{\ell}))\left|\frac{\Gamma(a-c_x+1+k)}{\Gamma(a-b+1+k)}\right|\lesssim e^{C \delta x}e^{\frac{\pi}{2} x}e^{-\frac{\pi}{2}(1-C\delta)x}\leq e^{C\delta x}.
\end{equation*}
Now suppose that $k+1> \delta x$. Then
\begin{equation*}
	\sinh(\pi (x+\textnormal{Im}\, \beta_{\ell}))\left|\frac{\Gamma(a-c_x+1+k)}{\Gamma(a-b+1+k)}\right|\lesssim e^{\frac{\pi}{2}x}e^{C k}\leq e^{C\delta^{-1}k}.
	\end{equation*}
	By repeating the above estimates with the roles of $a$ and $b$ reversed and taking $\varrho_0$ suitably large, depending on $\delta$, we obtain:
		\begin{equation*}
		\Bigg|\frac{\sin (\pi \textnormal{Im}\, \beta)}{\pi}F(\varrho;x)-\frac{\varrho^{-a}}{\Gamma(b)\Gamma(c_x-a)}+\frac{\varrho^{-b}}{\Gamma(a)\Gamma(c_x-b)}\Bigg|\leq C_{\epsilon,q} \varrho^{-1} e^{(\frac{\pi}{2}+\epsilon) x}.
	\end{equation*}
	It is straightforward to apply $(\varrho\partial_{\varrho})^m$ and $(x\partial_{x})^l$ to the above estimates to conclude \eqref{eq:largerhoFnestho1}.


Now consider the case $\beta=0$. We apply \cite{NIST:DLMF}[\S 15.8.8] together with Euler's reflection formula to express:
\begin{multline*}
	F(\varrho;x)=\frac{1}{\Gamma(a)^2}\varrho^{-1}\sum_{k=0}^{\infty}\frac{\Gamma(a+k)}{\Gamma(k+1)^2\Gamma(c_x-a-k)}\varrho^{-k}\left(\log \varrho+2\frac{\Gamma'(k+1)}{\Gamma(k+1)}-\frac{\Gamma'(a+k)}{\Gamma(a+k)}-\frac{\Gamma'(c_x-a-k)}{\Gamma(c_x-a-k)}\right)\\
	=-i\frac{\pi\sinh(\pi x)}{\Gamma(a)^2}\varrho^{-1}\sum_{k=0}^{\infty}\frac{\Gamma(a+k)\Gamma(a-c_x+k+1)}{\Gamma(k+1)^2}(-\varrho)^{-k}\left(\log \varrho+2\frac{\Gamma'(k+1)}{\Gamma(k+1)}-\frac{\Gamma'(a+k)}{\Gamma(a+k)}-\frac{\Gamma'(c_x-a-k)}{\Gamma(c_x-a-k)}\right).
\end{multline*}
The terms in the $k$-sum can be estimated as in the $\textnormal{Im}\, \beta>0$ case above to conclude:
\begin{equation*}
		\Bigg|F(\varrho;x)-\frac{\varrho^{-a}}{\Gamma(a)\Gamma(c_x-a)}\left(\log \varrho+2\gamma_{\rm Euler}-\frac{\Gamma'(a)}{\Gamma(a)}-\frac{\Gamma'(c_x-a)}{\Gamma(c_x-a)}\right)\Bigg|\leq C_{\epsilon,q} \varrho^{-1} \log \varrho e^{(\frac{\pi}{2}+\epsilon) x}.
	\end{equation*}
	It is straightforward to apply $(\varrho\partial_{\varrho})^m$ and $(x\partial_{x})^l$ to the above estimates to conclude \eqref{eq:largerhoFnestho2}.

\label{prop:imaginarybetatail}
	Let $\beta_{\ell}\in i(0,\infty)$ and $\mathfrak{w}_{\ell}^0(r)=\alpha_+ (\beta_{\ell})r^{\frac{1}{2}+\frac{\beta_{\ell}}{2}+iq}+\alpha_-(\beta_{\ell})r^{\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq}$, with $\alpha_{\pm}(is)\in \mathbb{C}$ for $s\in \mathbb{R}$ satisfying $\alpha_-(is)=\alpha_+(-is)$.

	Define
	\begin{equation*}
		\zeta(\beta_{\ell}):= -\frac{2^{\beta_{\ell}}\Gamma(-\beta_{\ell}+1)\Gamma(\frac{1}{2}+ \frac{\beta_{\ell}}{2}+iq)}{\Gamma(\beta_{\ell}+1) \Gamma(\frac{1}{2}- \frac{\beta_{\ell}}{2}+iq)}\frac{\alpha_-(\beta_{\ell})}{\alpha_+(\beta_{\ell})},
	\end{equation*}
	so that $\zeta(-\beta_{\ell})=\frac{1}{\zeta(\beta_{\ell})}$, and assume that there exists a $\eta_0=\eta(|q|)>0$, such that
	\begin{equation}
	\label{eq:condzeta}
		\,\textnormal{sign}\,(q) \log \left|\frac{\alpha_-(\beta_{\ell})}{\alpha_+(\beta_{\ell})}\right|\leq-\frac{\pi}{2}\textnormal{Im}\, \beta_{\ell}-\eta_0 \textnormal{Im}\, \beta_{\ell}+\frac{1}{2}\log \left(\left|\frac{\cosh(\pi(|q|-\frac{1}{2}\textnormal{Im}\, \beta_{\ell})}{\cosh(\pi(|q|+\frac{1}{2}\textnormal{Im}\, \beta_{\ell})}\right|^2\right).
	\end{equation}
Then the following sum is a well-defined smooth function with respect to $(\tau,\varrho_{\infty},\theta,\varphi)$:	
\begin{multline}
\label{eq:psiinftyimbetapos}
		(\Psi^{\infty}_0)_{\ell m}(\tau,r(\tau,\varrho)):=\,\textnormal{sign}\,(q)\beta_{\ell}\sum_{n=0}^{\infty}(\zeta(\,\textnormal{sign}\,(q)\beta_{\ell}))^n(1+\tau)^{-\frac{1}{2}-(n+\frac{1}{2})\,\textnormal{sign}\,(q)\beta_{\ell}+iq}\\
		\times {}_2\mathbf{F}_1\left(\frac{1}{2}+\,\textnormal{sign}\,(q)\frac{\beta_{\ell}}{2}+iq,\frac{1}{2}-\,\textnormal{sign}\,(q)\frac{\beta_{\ell}}{2}+iq,\frac{1}{2}+iq-(n+\frac{1}{2})\,\textnormal{sign}\,(q)\beta_{\ell};-\varrho\right).
	\end{multline}
	The function $\Psi^{\infty}_0=(\Psi^{\infty}_0)_{\ell m}Y_{\ell m}$ is a solution to \eqref{eq:CSFmink} with $A=\widehat{A}$ and $\mathbbm{h}=0$.

	Furthermore, $f(\tau,r):=(\mathfrak{w}^0_{\ell})^{-1}(r)(\Psi^{\infty}_0)_{\ell m}(\tau,r)$ satisfies: for all $k,l\leq N$
	\begin{align}
	\label{eq:divisionwimproveddecim0}
		|(rX)^k ((\tau+1)T)^l f|\leq &\: C_N (\tau+1)^{-\frac{1}{2}}(\tau+1+2r)^{-\frac{1}{2}},\\
	\label{eq:divisionwimproveddecim1}
		|(rX)^k ((\tau+1)T)^l Tf|\leq &\: C_N (\tau+1)^{-\frac{3}{2}}(\tau+1+2r)^{-\frac{1}{2}},\\
			\label{eq:divisionwimproveddecim2}
		|(rX)^k ((\tau+1)T)^l Xf|\leq &\: C_N (\tau+1)^{-\frac{3}{2}}(\tau+1+2r)^{-\frac{1}{2}}.
	\end{align}

Without loss of generality, we may assume that $q>0$. If $q<0$, we simply repeat the argument with $\beta_{\ell}$ replaced by $-\beta_{\ell}$. We can express:
	\begin{equation*}
		(\Psi^{\infty}_0)_{\ell m}(\tau,r(\tau,\varrho))=\beta_{\ell}\sum_{n=0}^{\infty}\zeta^n(1+\tau)^{-a+2iq-n\beta_{\ell}}F_{n \textnormal{Im}\, \beta_{\ell}}(\varrho;\beta_{\ell}),
	\end{equation*}
	with $F_{x}(\varrho;\beta)$ defined in Lemma \ref{lm:unifomestnhypgeom}.

	By assumption on $\zeta$, \eqref{eq:boundedrhoFnestho} and \eqref{eq:boundedrhoFnesthoplus}, we can estimate:
	\begin{equation*}
		\log \zeta+\frac{1}{n}\log |F_{n \textnormal{Im}\, \beta_{\ell}}(\varrho;\beta_{\ell})|\leq -\eta_0 \textnormal{Im}\, \beta_{\ell}+\frac{\log C_{\varrho,q}}{n}.
	\end{equation*}
	Hence, $|\zeta|F_{n \textnormal{Im}\, \beta_{\ell}}(\varrho;\beta_{\ell})|^{\frac{1}{n}}|<e^{-\eta_0 \textnormal{Im}\, \beta_{\ell}}<1$, so for $\varrho\leq \varrho_0$:
	\begin{equation*}
		|(\Psi^{\infty}_0)_{\ell m}(\tau,r(\tau,\varrho))|\leq  C_{\varrho,q}(1+\tau)^{-\frac{1}{2}}|\beta_{\ell}|\sum_{n=0}^{\infty}e^{-\eta_0 \textnormal{Im}\, \beta_{\ell}}\leq  C_{\varrho,q}\eta_0.
	\end{equation*}
	This means that the series converges. Commutation with $\mathfrak{T}$ and $\varrho\mathfrak{X}$ is straightforward and we conclude that $(\Psi^{\infty}_0)_{\ell m}$ is smooth.

	Since $\Psi^{\infty}_{0}$ is a well-defined limit of a sum of solutions to \eqref{eq:maineqradfield} for $M=0$ by Lemma \ref{lm:solnminkhypg}, we conclude by linearity that $\Psi^{\infty}_{0}$ must itself by a solution.

The remaining estimates in the statement of the proposition follow by repeating the steps in the proof of Proposition \ref{prop:hypgeomrealbeta} with $N_{\beta_{\ell}}$ replaced by $\infty$, using \eqref{eq:largerhoFnestho1}.

\label{prop:hypgeombeta0}
	Let $\beta_{\ell}=0$ and $\alpha_+,\alpha_-\in \mathbb{C}$. Let $\mathfrak{w}_{\ell}^0(r)=r^{\frac{1}{2}+iq}(\alpha_+ \log r+\alpha_-)$.

Define
	 \begin{equation}
	\label{eq:defPsiinftybeta0}
	 	(\Psi^{\infty}_{0})_{\ell m}(\tau,r(\tau,\varrho)):=(\tau+1)^{-\frac{1}{2}+iq}\int_0^{\infty}(\tau+1)^{-ix}e^{-\eta x}{}_2\mathbf{F}_1\left(\frac{1}{2}+iq,\frac{1}{2}+iq,\frac{1}{2}+iq-ix;-\varrho\right)\,dx.
	 \end{equation}

	with
	\begin{equation*}
			\eta:=i \,\textnormal{sign}\,(q)\left[\frac{\alpha_-}{\alpha_+}-\log 2+2\gamma_{\rm Euler}-\frac{\Gamma'(\frac{1}{2}+iq)}{\Gamma(\frac{1}{2}+iq)}\right],
	\end{equation*}
	and with $\gamma_{\rm Euler}$ the Euler--Mascheroni constant. Assume that there exists a $\eta_0=\eta(|q|)>0$, such that
	\begin{equation}
	\label{eq:condeta}
		\,\textnormal{sign}\,(q) \textnormal{Im}\, \left(\frac{\alpha_-}{\alpha_+}\right)\leq -\frac{\pi}{2}\left(1-\tanh(\pi |q|)\right)+\eta_0 .
	\end{equation}

	Then $\Psi^{\infty}_0=(\Psi^{\infty}_0)_{\ell m}Y_{\ell m}$ is well-defined and smooth with respect to the coordinate chart $(\tau,\varrho_{\infty},\theta,\varphi)$ and it is a solution to \eqref{eq:CSFmink} with $A=\widehat{A}$ and $\mathbbm{h}=0$.

	Furthermore, $f(\tau,r):=(\mathfrak{w}^0_{\ell})^{-1}(r)(\Psi^{\infty}_0)_{\ell m}(\tau,r)$ satisfies: for all $k,l\leq N$
	\begin{align}
	\label{eq:divisionwimproveddec0beta0}
		|(rX)^k ((\tau+1)T)^l f|\leq &\: C_N (\log r)^{-1}(\tau+1)^{-\frac{1}{2}}(\tau+1+2r)^{-\frac{1}{2}},\\
	\label{eq:divisionwimproveddec1beta0}
		|(rX)^k ((\tau+1)T)^l Tf|\leq &\: C_N (\log r)^{-1}(\tau+1)^{-\frac{3}{2}}(\tau+1+2r)^{-\frac{1}{2}},\\
			\label{eq:divisionwimproveddec2beta0}
		|(rX)^k ((\tau+1)T)^l Xf|\leq &\: C_N (\log r)^{-1}(\tau+1)^{-\frac{3}{2}}(\tau+1+2r)^{-\frac{1}{2}}.
	\end{align}

We can express:
\begin{equation*}
	(\Psi^{\infty}_{0})_{\ell m}(\tau,\varrho)=(\tau+1)^{-\frac{1}{2}+iq}\int_0^{\infty}(\tau+1)^{-ix}e^{-\,\textnormal{sign}\,(q)\eta x}F_x(\varrho;0)\,dx,
\end{equation*}
with $F_{x}(\varrho;\beta)$ defined in Lemma \ref{lm:unifomestnhypgeom}.

Without loss of generality assume that $q>0$. In order to conclude that the above integral is well-defined, we will verify that the integrand decays exponentially in $x$. Note that
\begin{equation*}
	\textnormal{Re}\, \eta=-\textnormal{Im}\, \left(\frac{\alpha_-}{\alpha_+}\right)+\textnormal{Im}\, \frac{\Gamma'(\frac{1}{2}+iq)}{\Gamma(\frac{1}{2}+iq)}.
\end{equation*}
Furthermore,
\begin{equation*}
	\textnormal{Im}\, \frac{\Gamma'(\frac{1}{2}+iq)}{\Gamma(\frac{1}{2}+iq)}=\textnormal{Re}\, \frac{d}{dq}\log \Gamma\left(\frac{1}{2}+iq\right)=\frac{1}{2}\frac{d}{dq}\log\left|\Gamma\left(\frac{1}{2}+iq\right)\right|^2=-\frac{1}{2\pi}\frac{d}{dq}\log(\cosh(\pi q))=-\frac{1}{2\pi}\tanh(\pi q).
\end{equation*}
Hence, by assumption on $\frac{\alpha_-}{\alpha_+}$
\begin{equation*}
	\textnormal{Re}\, \eta\geq \frac{\pi}{2}+\eta_0
\end{equation*}
Applying \eqref{eq:boundedrhoFnestho} and \eqref{eq:boundedrhoFnesthoplus}, then implies that for $\varrho\leq \varrho_0$:
\begin{equation*}
	\left|e^{-\,\textnormal{sign}\,(q)\eta x}F_x(\varrho;0)\right|\leq e^{-\eta_0 x}.
\end{equation*}
The absolute value of the integrand is therefore exponentially decaying, so the integral is well-defined. Furthermore, by Lemma \ref{lm:solnminkhypg}, the linearity of \eqref{eq:CSFminkrhotau} and the dominated convergence theorem, $\Psi^{\infty}_0$ must be a solution to \eqref{eq:CSFminkrhotau}. Since we can freely commute with $\varrho\mathfrak{X}$ and $\mathfrak{T}$, we moreover have that $\Psi^{\infty}_0$ is a smooth solution, so $(\Psi^{\infty}_0)_{\ell m}(\tau,r)Y_{\ell m}(\theta,\varphi)$ is a smooth solution to \eqref{eq:CSFmink}. 

It remains to consider the function $f=\mathfrak{w}_0^{-1}\Psi^{\infty}_0$ for $\varrho\geq \varrho_0$. Note first of all that by \eqref{eq:largerhoFnestho2}, we can write:
\begin{equation}
\label{eq:keysplitFrhoxbeta0}
	F(\varrho;x)=\frac{\varrho^{-a}}{\Gamma(\frac{1}{2}+iq)\Gamma(-ix)}\left(\log \varrho+2\gamma_{\rm Euler}-\frac{\Gamma'(\frac{1}{2}+iq)}{\Gamma(\frac{1}{2}+iq)}-\frac{\Gamma'(-ix)}{\Gamma(-ix)}\right)+\log \varrho e^{(\frac{\pi}{2}+\epsilon)x}R(\varrho,x),
\end{equation}
where $(x\partial_x)^{\ell} R(\varrho,x)=O_{\infty}(\varrho^{-1})$. We split
\begin{equation*}
	\log\varrho=\log(1+\tau)-\log r-\log 2
\end{equation*}

can integrate by parts in $x$, taking $\epsilon<\eta_0$ to estimate:
\begin{multline*}
	\int_0^{\infty}(1+\tau)^{-ix}e^{-(\eta-\frac{\pi}{2}-\epsilon)x}\log (1+\tau) R(\varrho,x)\,dx=-\frac{1}{i}\int_0^{\infty} \frac{d}{dx}(e^{-ix \log (1+\tau)})e^{-(\eta-\frac{\pi}{2}-\epsilon)x} R(\varrho,x)\,dx\\
	=-iR(\varrho,0)-i\int_0^{\infty}e^{-ix \log (1+\tau)}\frac{d}{dx}\left(e^{-(\eta-\frac{\pi}{2}-\epsilon)x}R(\varrho,x)\right)\,dx.
\end{multline*}
The right-hand side can be bounded by $\varrho^{-\frac{3}{2}}$ and after applying $X$, we conclude that:
\begin{equation*}
	\left|X\left((\mathfrak{w}_{\ell}^0)^{-1}(1+\tau)^{-\frac{1}{2}+iq}\int_0^{\infty}(1+\tau)^{-ix}e^{-(\eta-\frac{\pi}{2}-\epsilon)x}\log (1+\tau) R(\varrho,x)\,dx\right)\right|\leq C (1+\tau)^{-2}(\log r)^{-1},
\end{equation*}
as desired. It is straightforward to commute with $rX$ and $(\tau+1) T$.

We will now consider the remaining term in \eqref{eq:keysplitFrhoxbeta0} and show that we can factor out $\mathfrak{w}_{\ell}^0(r)$, by choosing $\eta$ appropriately. As above, we first split $\log\varrho=\log(1+\tau)-\log r-\log 2$ and integrate by parts the $\log(1+\tau)$ contribution. We obtain:
\begin{multline*}
	\frac{\varrho^{-\frac{1}{2}-iq}}{\Gamma(\frac{1}{2}+iq)}\int_0^{\infty}(1+\tau)^{-ix}e^{-\eta x}\log (1+\tau) \frac{1}{\Gamma(-ix)}\,dx=-\frac{\varrho^{-\frac{1}{2}-iq}}{i \Gamma(\frac{1}{2}+iq)}\int_0^{\infty} \frac{d}{dx}(e^{-ix \log (1+\tau)})e^{-\eta x} \frac{1}{\Gamma(-ix)}\,dx\\
	=\frac{\varrho^{-\frac{1}{2}-iq}}{i \Gamma(\frac{1}{2}+iq)}\int_0^{\infty} \left[-\eta+i\frac{\Gamma'(-ix)}{\Gamma(-ix)}\right]\frac{1}{\Gamma(-ix)}(1+\tau)^{-ix}e^{-\eta x}\,dx,
\end{multline*}
where we used that the boundary term at $x=0$ vanishes since $\frac{1}{\Gamma(-ix)}$ vanishes at $x=0$.

The full integral then becomes:
\begin{equation*}
	-\frac{\varrho^{-\frac{1}{2}-iq}(\tau+1)^{-\frac{1}{2}+iq}}{\Gamma(\frac{1}{2}+iq)}\int_0^{\infty}(1+\tau)^{-ix} \frac{e^{-\eta x}}{\Gamma(-ix)}\left[\log r+\log 2 -2\gamma_{\rm Euler}+\frac{\Gamma'(\frac{1}{2}+iq)}{\Gamma(\frac{1}{2}+iq)}-i\eta\right]\,dx.
\end{equation*}
Now take
\begin{equation*}
	-i\eta=\frac{\alpha_-}{\alpha_+}-\log 2+2\gamma_{\rm Euler}-\frac{\Gamma'(\frac{1}{2}+iq)}{\Gamma(\frac{1}{2}+iq)}.
\end{equation*}
Then we can write the integral as follows.
\begin{equation*}
	-2^{\frac{1}{2}+iq}\frac{(\tau+1)^{-1}}{\Gamma(\frac{1}{2}+iq)}\mathfrak{w}_{\ell}^0(r)\int_0^{\infty}(1+\tau)^{-ix} \frac{e^{-\eta x}}{\Gamma(-ix)}\,dx.
\end{equation*}
After dividing by $\mathfrak{w}_{\ell}^0(r)$, the above expression is independent of $r$ and hence, the $X$-derivative vanishes. We conclude \eqref{eq:divisionwimproveddec0beta0}--\eqref{eq:divisionwimproveddec2beta0} for $\varrho\geq \varrho_0$.


We integrate by parts and use that ${}_2\mathbf{F}_1\left(\frac{1}{2}+iq,\frac{1}{2}+iq,\frac{1}{2}+iq;-\varrho\right)=\frac{(1+\varrho)^{-\frac{1}{2}-iq}}{\Gamma(\frac{1}{2}+iq)}$to rewrite:
\begin{multline*}
	(\Psi^{\infty}_{0})_{\ell m}(\tau,r(\tau,\varrho))=i((\log(1+\tau))^{-1}(\tau+1)^{-\frac{1}{2}+iq}\\
\times \int_0^{\infty}\frac{d}{dx}((\tau+1)^{-ix})e^{-\eta x}{}_2\mathbf{F}_1\left(\frac{1}{2}+iq,\frac{1}{2}+iq,\frac{1}{2}+iq-ix;-\varrho\right)\,dx\\
=-i((\log(1+\tau))^{-1}(\tau+1)^{-\frac{1}{2}+iq}\frac{(1+\varrho)^{-\frac{1}{2}-iq}}{\Gamma(\frac{1}{2}+iq)}\\
-i((\log(1+\tau))^{-1}(\tau+1)^{-\frac{1}{2}+iq}\\
\times \int_0^{\infty}(\tau+1)^{-ix}\frac{d}{dx}\left(e^{-\eta x}{}_2\mathbf{F}_1\left(\frac{1}{2}+iq,\frac{1}{2}+iq,\frac{1}{2}+iq-ix;-\varrho\right)\right)\,dx
\end{multline*}
We therefore obtain:
\begin{equation*}
|(rX)^l((1+\tau)T)^m\Psi^{\infty}_0|\lesssim 	(\log(1+\tau))^{-1}((1+\tau)^{-\frac{1}{2}-\frac{1}{2}\textnormal{Re}\,\beta_{\ell}}.
\end{equation*}
For $\varrho\leq \varrho_0$, $r^{-1}\lesssim (1+\tau)^{-1}$, so \eqref{eq:divisionwimproveddec0beta0}--\eqref{eq:divisionwimproveddec2beta0} then follow from the above estimates.

We first consider the case $\beta_{\ell}\in (0,1)$. Then
	\begin{equation*}
		(\Psi_0^{\infty})_{\ell m}(\tau,\infty)=\beta_{\ell}(1+\tau)^{-\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq}\sum_{n=0}^{N_{\beta_{\ell}}}\frac{\zeta^n(1+\tau)^{-n\beta_{\ell}}}{\Gamma\left(\frac{1}{2}+iq-(n+\frac{1}{2})\beta_{\ell}\right)}=\frac{\beta_{\ell}(1+\tau)^{-\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq}}{\Gamma\left(\frac{1}{2}+iq-\frac{1}{2}\beta_{\ell}\right)}+O((1+\tau)^{-\frac{1}{2}-\frac{3\beta_{\ell}}{2}}).
	\end{equation*}
	Let $r_0>0$ be arbitrary. Then:
	\begin{multline*}
	(\Psi^{\infty}_0)_{\ell m}(\tau,r_0)=-2^{\frac{1}{2}+\frac{1}{2}\beta_{\ell}}\frac{\pi \beta_{\ell}}{\alpha_+\sin (\pi \beta_{\ell})}(1+\tau)^{-1-\beta_{\ell}}\mathfrak{w}_0(r)\cdot \left[\sum_{n=0}^{N_{\beta_{\ell}}}\zeta^n \frac{(1+\tau)^{-n\beta_{\ell}}}{\Gamma(\beta_{\ell}+1) \Gamma(\frac{1}{2}-\frac{1}{2}\beta_{\ell}+iq)\Gamma(-(n+1)\beta_{\ell})}\right]\\
	+O_{\infty}\left((1+\tau)^{-2}\right)\\
	=-2^{\frac{1}{2}+\frac{1}{2}\beta_{\ell}}\frac{\pi \beta_{\ell}}{\alpha_+\sin (\pi \beta_{\ell}) \Gamma(\beta_{\ell}+1) \Gamma(\frac{1}{2}-\frac{1}{2}\beta_{\ell}+iq)\Gamma(-\beta_{\ell})}\mathfrak{w}_0(r)(1+\tau)^{-1-\beta_{\ell}}+O_{\infty}\left((1+\tau)^{-1-2\beta_{\ell}}\right).
	\end{multline*}
Now let $\beta_{\ell}\in i(0,\infty)$. Then the expressions from the $\beta_{\ell}\in (0,1)$ case remain valid, but with $\beta_{\ell}$ replaced by $\,\textnormal{sign}\,(q)\beta_{\ell}$ and $N_{\beta_{\ell}}$ replaced with $\infty$.

Finally, we consider the case $\beta_{\ell}=0$. We can express:
\begin{equation*}
	(\Psi^{\infty}_0)_{\ell m}(\tau,\infty)=(\tau+1)^{-\frac{1}{2}+iq}\int_0^{\infty}(\tau+1)^{-ix}e^{-\eta x}\frac{1}{\Gamma\left(\frac{1}{2}+iq-ix\right)}\,dx.
\end{equation*}
We write $(\tau+1)^{-ix}=i(\log(1+\tau))^{-1}\frac{d}{dx}\left(e^{-ix\log(1+\tau)}\right)$ and integrate by parts to obtain:
\begin{multline*}
	(\Psi^{\infty}_0)_{\ell m}(\tau,\infty)=-i(\tau+1)^{-\frac{1}{2}+iq}(\log(1+\tau))^{-1}\frac{1}{\Gamma\left(\frac{1}{2}+iq\right)}\\
	-i(\tau+1)^{-\frac{1}{2}+iq}(\log(1+\tau))^{-1}\int_0^{\infty}(\tau+1)^{-ix}\frac{d}{dx}\left(e^{-\eta x}\frac{1}{\Gamma\left(\frac{1}{2}+iq-ix\right)}\right)\,dx\\
	=-i(\tau+1)^{-\frac{1}{2}+iq}(\log(1+\tau))^{-1}\frac{1}{\Gamma\left(\frac{1}{2}+iq\right)}+(\log(1+\tau))^{-2}O_{\infty}((1+\tau)^{-\frac{1}{2}}),
\end{multline*}
where we obtained the last equality by integrating by parts in $x$ again to pull out another factor $(\log(1+\tau))^{-1}$.

We also obtain along $r=r_0$:
\begin{equation*}
	(\Psi^{\infty}_0)_{\ell m}(\tau,r_0)=-2^{\frac{1}{2}+iq}\frac{(\tau+1)^{-1}}{\Gamma(\frac{1}{2}+iq)}\mathfrak{w}_{\ell}^0(r)\int_0^{\infty}(1+\tau)^{-ix} \frac{e^{-\eta x}}{\Gamma(-ix)}\,dx+O_{\infty}((1+\tau)^{-2})
\end{equation*}
We integrate by parts and use that $\frac{1}{\Gamma(-ix)}$ vanishes at $x=0$ to obtain:
\begin{multline*}
	\int_0^{\infty}(1+\tau)^{-ix} \frac{e^{-\eta x}}{\Gamma(-ix)}\,dx=-i\frac{1}{\log(1+\tau)}\int_0^{\infty}(1+\tau)^{-ix}\frac{d}{dx}\left(\frac{e^{-\eta x}}{\Gamma(-ix)}\right)\,dx\\
	=\frac{1}{(\log(1+\tau))^2}\int_0^{\infty}\frac{d}{dx}\left((1+\tau)^{-ix}\right)\frac{d}{dx}\left(\frac{e^{-\eta x}}{\Gamma(-ix)}\right)\,dx\\
	=-\frac{1}{(\log(1+\tau))^2}\frac{d}{dx}\Big|_{x=0}\left(\frac{1}{\Gamma(-ix)}\right)+O_{\infty}((\log(1+\tau))^{-3})\\
=\frac{1}{(\log(1+\tau))^2}+O_{\infty}((\log(1+\tau))^{-3}).
\end{multline*}
We therefore conclude that:
\begin{multline*}
	(\Psi^{\infty}_0)_{\ell m}(\tau,r_0)=-\frac{2^{\frac{1}{2}+iq}}{\Gamma(\frac{1}{2}+iq)}\mathfrak{w}_{\ell}^0(r)\left[\log(1+\tau))^{-2}(\tau+1)^{-1}+(\log(1+\tau))^{-3}O_{\infty}((\tau+1)^{-1}\right]\\
	+O_{\infty}((1+\tau)^{-2}). \qedhere
	\end{multline*}

\label{prop:Psi0inftygrowthdecay}
Define the following constants: let $k\in \mathbb{N}_0$, then
\begin{align}
\mathfrak{c}_k:=&\:\begin{cases}
(-1)^k2^{-(k+1)}\frac{\beta_{\ell}\Gamma(\frac{1}{2}+\frac{\beta_{\ell}}{2}+iq+k+1)}{\Gamma(\frac{1}{2}+\frac{\beta_{\ell}}{2}+iq)\Gamma(\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq)},\quad (\beta_{\ell}\in (0,1)),\\
2^{-(k+1)}|\beta_{\ell}|\\
\times \sqrt{\sum_{n=0}^{\infty}|\zeta(\beta_{\ell})|^{\,\textnormal{sign}\,(q)2n}\left|\partial_z^{k+1}\: ({}_2\mathbf{F}_1)\right|^2\left(\frac{1+\,\textnormal{sign}\,(q)\beta_{\ell}}{2}+iq,\frac{1-\,\textnormal{sign}\,(q)\beta_{\ell}}{2}+iq, \frac{1+(2n-1)\,\textnormal{sign}\,(q)\beta_{\ell}}{2}+iq;0\right)},\\
\quad (\beta_{\ell}\in i(0,\infty)),\\
(-1)^k2^{-(k+1)}\frac{i\Gamma\left(\frac{1}{2}+iq+k+1\right)}{\Gamma(\frac{1}{2}+iq)^2},\quad (\beta_{\ell}=0),
\end{cases}\\
	\mathfrak{c}_{\rm int}:=&\:\begin{cases}
\frac{\left(q^2+\frac{1}{4}(1+\beta_{\ell})^2\right)|\beta_{\ell}|^2}{2(2+\beta_{\ell})|\Gamma\left(\frac{1}{2}+iq-\frac{\beta_{\ell}}{2}\right)|^2},\quad (\beta_{\ell}\in (0,1)),\\
\frac{|\beta_{\ell}|^2}{2}\sum_{n=0}^{\infty}\int_0^{\infty} |\zeta|^{\,\textnormal{sign}\,(q)2n}\left|\partial_z\: ({}_2\mathbf{F}_1)\right|^2\left(\frac{1+\,\textnormal{sign}\,(q)\beta_{\ell}}{2}+iq,\frac{1-\,\textnormal{sign}\,(q)\beta_{\ell}}{2}+iq, \frac{1+(2n-1)\,\textnormal{sign}\,(q)\beta_{\ell}}{2}+iq;-\varrho\right)\,d\varrho,\\
\quad (\beta_{\ell}\in i(0,\infty)),\\
\frac{\frac{1}{4}+q^2}{8|\Gamma(\frac{1}{2}+iq)|^2},\quad (\beta_{\ell}=0).
\end{cases}
\end{align}
	\begin{enumerate}[label=\emph{(\roman*)}]
		\item The following bounds hold for $(r^2X)^{k+1}(\Psi^{\infty}_0)_{\ell m}$ with $k\in \mathbb{N}_0$: there exist constants $C=C(q,\beta_{\ell})>0$ and $\widetilde{C}=\widetilde{C}(q)>0$, such that:
		\begin{align}
		\label{eq:lowboundrealbeta}
		\left|(r^2X)^{k+1}(\Psi^{\infty}_0)_{\ell m}(\tau,\infty)-\mathfrak{c}_k (1+\tau)^{\frac{k+1}{2}+iq-\frac{\beta_{\ell}}{2}}\right|\leq &\: C (1+\tau)^{\frac{k+1}{2}-\frac{3\beta_{\ell}}{2}}\quad (\beta_{\ell}\in (0,1)),\\
		\label{eq:lowboundimbeta1}	
		\limsup_{\tau\to \infty}(1+\tau)^{-\frac{k+1}{2}}|(r^2X)^{k+1}(\Psi^{\infty}_0)_{\ell m}|(\tau,\infty)\geq &\:\mathfrak{c}_k  \quad (\beta_{\ell}\in i(0,\infty)),\\
			\label{eq:lowboundimbeta2}	
	|(r^2X)^{k+1}(\Psi^{\infty}_0)_{\ell m}|(\tau,\infty)\leq &\: C (1+\tau)^{\frac{k+1}{2}} \quad (\beta_{\ell}\in i(0,\infty)) ,\\
		\label{eq:lowboundzerobeta}	
		\left|(r^2X)^{k+1}(\Psi^{\infty}_0)_{\ell m}(\tau,\infty)-\mathfrak{c}_k \frac{(1+\tau)^{\frac{k+1}{2}+iq}}{\log(1+\tau)}\right|\leq &\: \widetilde{C}(\log(1+\tau))^{-2}(1+\tau)^{\frac{k+1}{2}}\quad (\beta_{\ell}=0).
		\end{align}
\item Let $R>0$ be arbitrary. Then there exist constants $C=C(q,\beta_{\ell},R)>0$ and $\widetilde{C}=\widetilde{C}(q,R)>0$, such that:
\begin{align}
		\label{eq:enboundrealbeta}
		\left|\int_0^{\infty}r^2|X(\Psi^{\infty}_0)_{\ell m}|^2(\tau,r)\,dr-\mathfrak{c}_{\rm int} (1+\tau)^{-\beta_{\ell}}\right|\leq &\: C (1+\tau)^{-2\beta_{\ell}}\quad (\beta_{\ell}\in (0,1)),\\
		\label{eq:enboundimbeta1}	
		\limsup_{\tau\to \infty}\int_0^{\infty}r^2|X(\Psi^{\infty}_0)_{\ell m}|^2(\tau,r)\,dr\geq &\:\mathfrak{c}_{\rm int}  \quad (\beta_{\ell}\in i(0,\infty)),\\
			\label{eq:enboundimbeta2}	
	\sup_{\tau\in [0,\infty)}\int_0^{\infty}r^2|X(\Psi^{\infty}_0)_{\ell m}|^2(\tau,r)\,dr\leq &\: C  \quad (\beta_{\ell}\in i(0,\infty)) ,\\
		\label{eq:enboundzerobeta}	
		\left|\int_0^{\infty}r^2|X(\Psi^{\infty}_0)_{\ell m}|^2(\tau,r)\,dr-\frac{\mathfrak{c}_{\rm int}}{\log^2(1+\tau)}\right|\leq &\: \widetilde{C}(\log(1+\tau))^{-3}\quad (\beta_{\ell}=0).
		\end{align}
		\item Let $p\in (0,2]$ and consider the energy density $\mathcal{E}_p$ from \S \ref{sec:iedassm} and with $\Omega^2=1-2Mr^{-1}+Q^2$, $Q^2\leq M^2$. Let $N\in \mathbb{N}_0$. Then there exist constants $C_N=C_N(q,\beta_{\ell},p,N)>0$ and $\widetilde{C}_N=\widetilde{C}_N(q,R,p,N)>0$, such that for all $k_1+k_2+k_3\leq N$:
	\begin{equation}
	\int_{r_+}^{\infty}\int_{\mathbb{S}^2}\mathcal{E}_{p}[\slashed{\nabla}_{\mathbb{S}^2}^{k_1}(rX)^{k_2}((\tau+1)T)^{k_3}(\Psi^{\infty}_0)]\,d\sigma dr\leq \begin{cases}
 	C_{N}(\tau+1)^{p-2-\textnormal{Re}\, \beta_{\ell}}\quad &(\beta_{\ell}\neq 0),\\
 	\widetilde{C}_N\frac{(\tau+1)^{p-2}}{\log^2(1+\tau)}\quad &(\beta_{\ell}= 0).
 \end{cases}
\end{equation}
	\end{enumerate}

We will consider the case $k=0$. We will omit the subscript $\ell m$ in the notation $(\Psi^{\infty}_0)_{\ell m}$. The $k\geq 1$ follows from a straightforward generalization. Note that for $\beta_{\ell}\in (0,\infty)$:
\begin{multline*}
(r^2X\Psi^{\infty}_0)(\tau,\varrho)=-\frac{\tau+1}{2}(\mathfrak{X}\Psi^{\infty}_0)(\tau,\infty)=-\frac{\beta_{\ell}}{2}\sum_{n=0}^{N_{\beta_{\ell}}}\zeta^n(1+\tau)^{\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq-n\beta_{\ell}}{}_2(\partial_{\varrho}{F}_{n \beta})(\varrho;\beta_{\ell})\\
=-\frac{\beta_{\ell}}{2}(1+\tau)^{\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq}(\partial_{\varrho}{F}_{0})(\varrho;\beta_{\ell})(1+O((1+\tau)^{-\beta_{\ell}})).
\end{multline*}
Note that
\begin{equation*}
	{F}_{0}(\varrho;\beta_{\ell})={}_2\mathbf{F}_1\left(\frac{1}{2}+iq+\frac{\beta_{\ell}}{2},\frac{1}{2}+iq-\frac{\beta_{\ell}}{2},\frac{1}{2}+iq-\frac{\beta_{\ell}}{2};-\varrho\right)=\frac{(1+\varrho)^{-\frac{1}{2}-iq-\frac{\beta_{\ell}}{2}}}{\Gamma\left(\frac{1}{2}+iq-\frac{\beta_{\ell}}{2}\right)}.
\end{equation*}
Hence,
\begin{equation*}
	(\partial_{\varrho}F_{0})(\varrho;\beta_{\ell})=-\left(\frac{1}{2}+iq+\frac{\beta_{\ell}}{2}\right)\frac{(1+\varrho)^{-\frac{3}{2}-iq-\frac{\beta_{\ell}}{2}}}{\Gamma\left(\frac{1}{2}+iq-\frac{\beta_{\ell}}{2}\right)}.
\end{equation*}
We conclude that
\begin{equation*}
	(r^2X\Psi^{\infty}_0)(\tau,\infty)=\frac{\beta_{\ell}\left(\frac{1}{2}+iq+\frac{\beta_{\ell}}{2}\right)}{2\Gamma\left(\frac{1}{2}+iq-\frac{\beta_{\ell}}{2}\right)}(1+\tau)^{\frac{1}{2}-\frac{\beta_{\ell}}{2}+iq}(1+O((1+\tau)^{-\beta_{\ell}})).
\end{equation*}
Furthermore, using that $r^{-2}dr=-2(\tau+1)^{-1}d\varrho$ along constant $\tau$ level sets, we can express
\begin{multline*}
	\int_{R}^{\infty}r^2|X\Psi^{\infty}_0|^2(\tau,r)\,dr=\frac{(\tau+1)}{2}\int_{0}^{\frac{\tau+1}{2R}}|\mathfrak{X}\Psi^0_{\infty}|^2(\tau,\varrho)\,d\varrho\\
	=\frac{|\beta_{\ell}|^2(\tau+1)^{- \beta_{\ell}}}{2}\int_{0}^{\frac{\tau+1}{2R}}|(\partial_{\varrho}F_{0})(\varrho;\beta_{\ell})|^2(1+O((\tau+1)^{-\beta_{\ell}}))\,d\varrho\\
	=\frac{\left(q^2+\frac{1}{4}(1+\beta_{\ell})^2\right)|\beta_{\ell}|^2(\tau+1)^{- \beta_{\ell}}}{2|\Gamma\left(\frac{1}{2}+iq-\frac{\beta_{\ell}}{2}\right)|^2}\int_{0}^{\frac{\tau+1}{2R}}(1+\varrho)^{-3-\beta_{\ell}}(1+O((\tau+1)^{-\beta_{\ell}}))\,d\\
	=\frac{\left(q^2+\frac{1}{4}(1+\beta_{\ell})^2\right)|\beta_{\ell}|^2(\tau+1)^{- \beta_{\ell}}}{2(2+\beta_{\ell})|\Gamma\left(\frac{1}{2}+iq-\frac{\beta_{\ell}}{2}\right)|^2}(1+O((\tau+1)^{-\beta_{\ell}})).
\end{multline*}
By using that $r^{-1}= 2\varrho (\tau+1)^{-1}$ it is also straightforward to obtain for $p\in [0,2)$ the existence of a constant $C>0$, such that:
\begin{equation*}
	\int_{R}^{\infty}r^p|X(\Psi^{\infty}_0)_{\ell m}|^2+r^{-2}(|(\Psi^{\infty}_0)_{\ell m}|^2+|T(\Psi^{\infty}_0)_{\ell m}|^2)(\tau,r)\,dr\leq C(\tau+1)^{p-2-\beta_{\ell}}.
\end{equation*}
It is moreover straightforward to commute with $(\tau+1)T$ and $rX$ and obtain for $\ell(\ell+1)<q^2$ and $k_1+k_2+k_3=N\in \mathbb{N}_0$ the existence of a constant $C_N>0$, such that:
\begin{equation*}
	\int_{r_+}^{\infty}\int_{\mathbb{S}^2}\mathcal{E}_p[\slashed{\nabla}_{\mathbb{S}^2}^{k_1}(rX)^{k_2}((\tau+1)T)^{k_3}(\Psi^{\infty}_0)]\,d\sigma dr\leq C_N(\tau+1)^{p-2-\beta_{\ell}}.
\end{equation*}

Now suppose that $\beta_{\ell}\in i(0,\infty)$. Without loss of generality, we will assume that $q>0$. We use the general expressions above to obtain:
\begin{equation*}
	|r^2X\Psi^{\infty}_0|(\tau,\varrho)\leq \frac{|\beta_{\ell}|}{2}(1+\tau)^{\frac{1}{2}}\sum_{n=0}^{\infty}|\zeta|^{n}\left|\partial_{\varrho}F_{n\textnormal{Im}\, \beta_{\ell}}(\varrho;\beta_{\ell})\right|,
\end{equation*}
where the right-hand side converges. This follows from the proof of Proposition \ref{prop:imaginarybetatail} where $\partial_{\varrho}F_{n\textnormal{Im}\, \beta_{\ell}}$ is replaced by $F_{n\textnormal{Im}\, \beta_{\ell}}$, but the additional $\varrho$-derivative only introduces additional polynomial growth in $n$, which does not affect the convergence of the relevant series.

Furthermore, by applying the Minkowski inequality, we can also estimate:
\begin{equation*}
	\frac{(\tau+1)}{2}\int_0^{\frac{\tau+1}{2R}}|\mathfrak{X}\Psi^0_{\infty}|^2(\tau,\varrho)\,d\varrho\leq  \frac{|\beta_{\ell}|^2}{2}\left(\sum_{n=0}|\zeta|^n ||\partial_{\varrho}F_{n\textnormal{Im}\, \beta_{\ell}}||_{L^2_{\varrho}[0, \frac{\tau+1}{2R}]}\right)^2.
\end{equation*}
By Lemma \ref{lm:unifomestnhypgeom}, there exists a constant $C_{q, \varrho_0}>0$, such that we can estimate:
\begin{equation*}
	||\partial_{\varrho}F_{n\textnormal{Im}\, \beta_{\ell}}||_{L^2_{\varrho}[0, \varrho_0]}\leq C_{q, \varrho_0}e^{\frac{\pi}{2}n \textnormal{Im}\, \beta_{\ell}}.
\end{equation*}
Furthermore, we can apply Lemma \ref{lm:unifomestnhypgeom} to obtain moreover for $\varrho\geq \varrho_0$:
\begin{equation*}
	||\partial_{\varrho}F_{n\textnormal{Im}\, \beta_{\ell}}||_{L^2_{\varrho}[\varrho,\infty)}\leq C_{q, \varrho_0,\epsilon}\varrho^{-3}e^{(\frac{\pi}{2}+\epsilon)n \textnormal{Im}\, \beta_{\ell}}.
\end{equation*}
 for a constant $C_{q ,\varrho_0,\epsilon}>0$. By the properties assumed on $\zeta$ in Proposition \ref{prop:imaginarybetatail}, we therefore conclude that there exists a constant $C_{q,\beta_{\ell}}$ such that:
 \begin{equation*}
	\frac{(\tau+1)}{2}\int_0^{\frac{\tau+1}{2R}}|\mathfrak{X}\Psi^0_{\infty}|^2(\tau,\varrho)\,d\varrho\leq  C_{q,\beta_{\ell}}.
	\end{equation*}
 Furthermore, it is straightforward to extend the above estimate to obtain for $\ell(\ell+1)<q^2$ and $k_1+k_2+k_3=N\in \mathbb{N}_0$ the existence of a constant $C_N>0$, such that for $p\in [0,2]$:
\begin{equation*}
	\int_{r_+}^{\infty}\int_{\mathbb{S}^2}\mathcal{E}_p[\slashed{\nabla}_{\mathbb{S}^2}^{k_1}(rX)^{k_2}((\tau+1)T)^{k_3}(\Psi^{\infty}_0)]\,d\sigma dr\leq C_N(\tau+1)^{p-2}.
\end{equation*}

 In order to obtain an appropriate lower bound for $|r^2X\Psi^{\infty}_0|^2$, we instead write:
\begin{multline*}
	|r^2X\Psi^{\infty}_0|^2(\tau,\varrho)=\frac{|\beta_{\ell}|^2}{4}(1+\tau)\sum_{k\in \mathbb{Z}}\sum_{n,m\in \mathbb{N}_0}(\tau+1)^{-k \beta_{\ell}} \zeta^n \overline{\zeta}^m(\partial_{\varrho}{F}_{n \textnormal{Im}\, \beta_{\ell}})(\varrho;\beta_{\ell})\cdot (\partial_{\varrho}\overline{{F}_{m \textnormal{Im}\, \beta_{\ell}}})(\varrho;\beta_{\ell})\\
	=\frac{|\beta_{\ell}|^2}{4}(1+\tau)\sum_{n,m\in \mathbb{N}_0}e^{-i(n-m)\sigma} \zeta^n \overline{\zeta}^m(\partial_{\varrho}{F}_{n \textnormal{Im}\, \beta_{\ell}})(\varrho;\beta_{\ell})\cdot (\partial_{\varrho}\overline{{F}_{m \textnormal{Im}\, \beta_{\ell}}})(\varrho;\beta_{\ell}),
\end{multline*}
with $\sigma=\textnormal{Im}\, \beta_{\ell}\log(1+\tau)$. Since the above series is uniformly absolutely-convergent, it follows that:
\begin{multline}
\label{eq:expvaluePsi0infest}
	\left|S^{-1}\int_0^S(1+\tau(\sigma))^{-1}|r^2X\Psi^0_{\infty}|^2(\tau(\sigma),\varrho))\,d\sigma-\frac{|\beta_{\ell}|^2}{4}\sum_{n=0}^{\infty}|\zeta|^{2n}|\partial_{\varrho}{F}_{n \textnormal{Im}\, \beta}|^2(\varrho;\beta_{\ell})\right|\\
	\leq S^{-1}\frac{|\beta_{\ell}|^2}{4}\sum_{\substack{n,m\in \mathbb{N}_0\\n\neq m}}\frac{2}{|n-m|}|\zeta|^{n+m} |\partial_{\varrho}{F}_{n \textnormal{Im}\, \beta_{\ell}}|(\varrho;\beta_{\ell})\cdot |\partial_{\varrho}{F}_{m \textnormal{Im}\, \beta_{\ell}})|\varrho;\beta_{\ell})\leq C S^{-1}.
\end{multline}

Using that for any continuous $f:(0,\infty)\to \mathbb{R}$:
\begin{equation}
\label{eq:limsupid}
	\limsup_{x\to \infty}f(x)\geq \lim_{L\to \infty}\frac{1}{L}\int_0^Lf(x)\,dx,
\end{equation}
we therefore conclude that
\begin{multline*}
\limsup_{\tau\to \infty}(1+\tau)^{-1}|r^2X\Psi^0_{\infty}|^2(\tau,0)	\geq \frac{|\beta_{\ell}|^2}{4}\sum_{n=0}^{\infty}|\zeta|^{2n}|\partial_{\varrho}{F}_{n \textnormal{Im}\, \beta}|^2(0;\beta_{\ell})\\
=\frac{|\beta_{\ell}|^2}{4}\sum_{n=0}^{\infty}|\zeta|^{2n} \left|\partial_z\: ({}_2\mathbf{F}_1)\right|^2\left(\frac{1+\beta_{\ell}}{2}+iq,\frac{1-\beta_{\ell}}{2}+iq, \frac{1+(2n-1)\beta_{\ell}}{2}+iq;0\right).
\end{multline*}
Furthermore, we can express:
\begin{multline*}
	\int_{R}^{\infty}r^2|X\Psi^{\infty}_0|^2(\tau,r)\,dr=\frac{(\tau+1)}{2}\int_{0}^{\frac{\tau+1}{2R}}|\mathfrak{X}\Psi^0_{\infty}|^2(\tau,\varrho)\,d\varrho\\
	=\frac{|\beta_{\ell}|^2}{2}\sum_{k\in \mathbb{Z}}e^{-i k\sigma  } \int_0^{\frac{\tau+1}{2R}}\sum_{n,m\in \mathbb{N}_0,\: n-m=k} \zeta^n \overline{\zeta}^m(\partial_{\varrho}{F}_{n \textnormal{Im}\, \beta})(\varrho;\beta_{\ell})\cdot (\partial_{\varrho}\overline{{F}_{m \textnormal{Im}\, \beta}})(\varrho;\beta_{\ell})\,d\varrho.
\end{multline*}
As above, we have that:
\begin{equation*}
	\limsup_{\tau \to \infty}\int_{R}^{\infty}r^2|X\Psi^{\infty}_0|^2(\tau,r)\,dr\geq \frac{|\beta_{\ell}|^2}{2}\sum_{n=0}^{\infty}\int_0^{\frac{\tau+1}{2R}} |\zeta|^{2n}|\partial_{\varrho}\overline{{F}_{n \textnormal{Im}\, \beta}}|^2(\varrho;\beta_{\ell})\,d\varrho.
\end{equation*}
By Lemma \ref{lm:unifomestnhypgeom}, it follows moreover that $\limsup_{\tau \to \infty} \int_{\frac{\tau+1}{2R}}^{\infty} |\zeta|^{2n}|\partial_{\varrho}\overline{{F}_{m \beta}}|^2(\varrho;\beta_{\ell})\,d\varrho=0$, so we conclude:
\begin{multline*}
	\limsup_{\tau \to \infty}\int_{R}^{\infty}r^2|X\Psi^{\infty}_0|^2(\tau,r)\,dr\\
	\geq \frac{|\beta_{\ell}|^2}{2}\sum_{n=0}^{\infty}\int_0^{\infty} |\zeta|^{2n}\left|\partial_z\: ({}_2\mathbf{F}_1)\right|^2\left(\frac{1+\beta_{\ell}}{2}+iq,\frac{1-\beta_{\ell}}{2}+iq, \frac{1+(2n-1)\beta_{\ell}}{2}+iq;-\varrho\right)\,d\varrho.
\end{multline*}
The right-hand side is clearly strictly greater than 0.

Finally, we consider $\beta_{\ell}=0$. Then, after integrating by parts in $x$, we obtain:
\begin{multline*}
	(r^2X\Psi^{\infty}_0)(\tau,r(\tau,\varrho))=-\frac{\tau+1}{2}\mathfrak{X}\Psi^{\infty}_0(\tau,\varrho)=\frac{1}{2}(\tau+1)^{\frac{1}{2}+iq}\int_0^{\infty}(\tau+1)^{-ix}e^{-\eta x}(\partial_{\varrho}F_x)(\varrho;0)\,dx\\
	=-\frac{i}{2} (\log(1+\tau))^{-1}(\tau+1)^{\frac{1}{2}+iq}(\partial_{\varrho}\: F_0)(\varrho;0)(1+O((\log(1+\tau))^{-1})\\
	=\frac{i\left(\frac{1}{2}+iq\right)}{2\Gamma(\frac{1}{2}+iq)}\frac{(\tau+1)^{\frac{1}{2}+iq}}{\log(1+\tau)}(1+\varrho)^{-\frac{3}{2}-iq}(1+O((\log(1+\tau))^{-1}).
\end{multline*}
In particular,
\begin{equation*}
		(r^2X\Psi^{\infty}_0)(\tau,\infty)=\frac{i\left(\frac{1}{2}+iq\right)}{2\Gamma(\frac{1}{2}+iq)}\frac{(\tau+1)^{\frac{1}{2}+iq}}{\log(1+\tau)}(1+O((\log(1+\tau))^{-1})
\end{equation*}
and
\begin{multline*}
	\int_R^{\infty}r^2|X\Psi^{\infty}_0|^2(\tau,r)\,dr=\frac{\frac{1}{4}+q^2}{4|\Gamma(\frac{1}{2}+iq)|^2}(\log(1+\tau))^{-2}\int_0^{\frac{\tau+1}{2R}}(1+\varrho)^{-3}(1+O((\log(1+\tau))^{-1})\,d\varrho\\
	=\frac{\frac{1}{4}+q^2}{8|\Gamma(\frac{1}{2}+iq)|^2}(\log(1+\tau))^{-2}(1+O((\log(1+\tau))^{-1}).
\end{multline*}
 Furthermore, after applying Lemma \ref{lm:unifomestnhypgeom}, it is straightforward to extend the above estimate to obtain for $\ell(\ell+1)<q^2$ and $k_1+k_2+k_3=N\in \mathbb{N}_0$ the existence of a constant $C_N>0$, such that for $p\in [0,2]$:
\begin{equation*}
	\int_{r_+}^{\infty}\int_{\mathbb{S}^2}\mathcal{E}_p[\slashed{\nabla}_{\mathbb{S}^2}^{k_1}(rX)^{k_2}((\tau+1)T)^{k_3}(\Psi^{\infty}_0)]\,d\sigma dr\leq C_N(\log(1+\tau))^{-2}(\tau+1)^{p-2}. \qedhere
\end{equation*}
